/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160627-9","meetingId":"h28-cm06","date":"2016年6月27日","dateIso":"2016-06-27","committee":"文教委員会","time":"午前１０時００分～午前１１時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第５８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"文言の問題だと思うのですけれども、１点確認させてください。義務教育学校というくくりでの教員免許というのは既にあるのでしたか。確認です。私が追いかけられていないだけで、既に存在するのでしょうか。","respondent":"熊谷指導課長","answer":"教員ですけれども、義務教育学校の免許というのは現在ございませんで、原則、小学校免許で前期課程、それから中学校免許で後期課程を指導可能ということで、今後、原則として小・中両方の免許を有している事が義務教育学校の教員免許ということになります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、この文言を新たに加えることによって、新たにこれまでの規定では資格がなかったけれども、義務教育学校を加えたことで、枠が増えるというわけではないという事なのか、それとも、免許というのと「資格を有する」というのは範囲が違うのですか。","respondent":"高山子ども育成課長","answer":"実は、この基準というのは、国、厚生労働省令で定めます基準に自治体として従うべき基準ということで、要は、同じ文言を区の条例においても記載すべしというような意味合いで改正するものでございまして、国の基準が変わったから区の条例が変わったといったものでございまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あべ委員","kind":"意見","question":"頭の中を整理すると、厚労省に従って文言を変えるけれども、今のところは対象が広がるわけではないけれども、将来的にそれができたときにも対応できるようにということでよろしいですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"今の続きで、特に今の段階では、小学校、中学校の教員であることで十分ここは満たしている。でも、国のところで義務教育学校という名称が入ったので、ここに国にならって入れたということで、今のところは別に不具合がないということだったので、将来のことを考えると、どんな感じなのか。そこのところをわかる範囲で教えてくれませんか。","respondent":"熊谷指導課長","answer":"ただ、当面の間は、先ほどお話ししたように、小学校免許は前期課程、中学校免許は後期課程ということになっております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、特に今の状況で変わらないし、将来、義務教育学校の両方の免許が必要となっても、小学校、中学校を持っていれば指導員に十分なれるということで、文言が加わっただけという捉え方でよろしいのでしょうか。","respondent":"高山子ども育成課長","answer":"繰り返しの説明になってしまうのですが、厚生労働省令で定めます基準を、区としては条例の中で、全く同じ要件で従うべき基準ということで同様の記載が必要になってまいりますので、今般、この追加に関しては、文言上といいますか、将来的に当分の間の経過期間、経過した後に。","voiceIndex":12,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけ表現がわからなかったのですが、資料のところの(3)の「義務教育学校」の後に「高等学校または中等教育学校」、この「中等教育学校」というのは具体的にどういうところなのか、すみません、教えてください。","respondent":"熊谷指導課長","answer":"中等教育学校は、今、都立学校で５校ありますけれども、あとは九段中等教育学校、区立学校が１校ありますが、これはやはり同じように、中学校と高等学校の免許を両免持っている者ということになります。","voiceIndex":14,"id":"exchange-006"}]},{"id":"topic-02","title":"正する条例、(3)第６０号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例および(4)第６３号議案","agenda":"正する条例、(3)第６０号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例および(4)第６３号議案","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"４点確認させていただきたいのですけれども、「年齢制限を撤廃とし」とあるのですけれども、これは戸籍上の子どもの数で数えてということでよいのかということが１点です。４点目が、第６０号議案の認定こども園、幼稚園、特定地域型保育事業とありますけれども、区内に該当となる施設はどれが何園あるのか、教えていただきたいと思います。","respondent":"竹田保育課長","answer":"４月１日にさかのぼって適用されるのかということですが、さかのぼって適用いたしますので、本会議議決後、保護者の方に適宜ご連絡したいと考えております。","voiceIndex":27,"id":"exchange-007"},{"speaker":"のだて委員","kind":"確認","question":"年齢制限のところですけれども、２つの条件があるということで、そうすると、今は少ないですけれども、高校生で就職に出たと。すると、第１子には数えられないということでしょうか。もう一点が、認定こども園７５園等の数を教えていただきましたけれども、これは区内の数ということでいいのか、確認ですが、もう一度お願いいたします。","respondent":"竹田保育課長","answer":"多子減額の対象として数えるお子さんですが、先ほど申し上げたとおりで、生計を同一としていること、監督保護を受けていることということですから、そこから考えまして、もうお仕事をされて独立できるような収入を得ている方については。","voiceIndex":29,"id":"exchange-008"},{"speaker":"のだて委員","kind":"確認","question":"私立幼稚園と特定地域保育型施設のほうも、この数で正しいのか、もう一度確認です。","respondent":"竹田保育課長","answer":"しかし、助成金というのが旧制度の幼稚園にもございまして、そちらの助成金のほうで同様の内容となるように、東京都、国が要綱を改正するというふうに聞いておりますので、区内の私立幼稚園に通われている方につきましても、同様の処遇を受ける予定です。","voiceIndex":31,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"多子軽減が、これまでも我が会派としては戸籍上のということで求めてきて、それが拡大されたことは喜ばしいと考えています。ですけれども、３６０万円以下という所得制限をつけてしまったことが悲しいと考えています。これを撤廃していくというお考えはあるのか。ぜひ撤廃していっていただきたいと思いますけれども、伺います。","respondent":"竹田保育課長","answer":"今回の制度改正は、国全体で、国の省令、政令等の改正に伴いまして全国的に行われるものです。幼児教育の無償化ということですが、金額が高額になりますので、一自治体の裁量で幼児教育全部を無償化していくというのは、なかなか難しいというふうに考えております。","voiceIndex":33,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそれも念頭に入れて、子どもはみんな同じ子どもですから、同じ軽減を受けられるように検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、国の制度の変更に伴ってということですが、この制度変更によりまして、品川区の子どもたち、どれくらい恩恵を受けるのか、人数的なところというのがわかりましたら、教えていただきたいと思います。","respondent":"竹田保育課長","answer":"試算ですが、多子軽減を受ける方が約４０人程度、それから、ひとり親世帯が約６０人程度というふうに試算しております。","voiceIndex":36,"id":"exchange-012"},{"speaker":"新妻委員","kind":"確認","question":"これは既に対象者が見えていて、この方たちにお知らせをするということでしょうか。それとも、調査か何かをかけて、もう一回対象者を見ていくということでしょうか。確認をさせてください。","respondent":"竹田保育課長","answer":"こちら、現行のシステムのほうで該当者の洗い出しはできますので、速やかな実施ができるように準備は進めているところですので、改めて調査という必要はないと考えております。","voiceIndex":38,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"今、多子軽減を受けている世帯がどのくらいあるかということを教えてください。今回新たにというのは、さっき数字を伺いました。それから、これがシステムで洗い出しができるということなのですけれども、申請ベースで手続が必要なものなのか、それとも、区のほうでシステムを使って対象者に自動的にこの保育料をお知らせする形になるのかを教えてください。","respondent":"竹田保育課長","answer":"今回、人数の点ですが、従来は小学校に上がる前までの子どもたちが対象で、この４月から小学３年生まで拡大したのですけれども、第２子に該当する方が約３０％程度、それから第３子に該当する方が約３％程度というふうに考えております。","voiceIndex":40,"id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"その次の質問で伺おうと思っていたのですが、認証保育所のほうの扱い、今回の議案で上がってきている中には、制度上、認証というのは対象になってきていないと思うのですけれども、ただ、認可に入れなくて認証に入った方はこうした利益を受けられないという、軽減措置の対象にならないということではやはりよろしくないので、認証にもぜひそれに匹敵する助成制度をと思っていたのですが。","respondent":"竹田保育課長","answer":"認証保育所の助成につきましては要綱で定めておりますので、今回、条例改正が決まりました後に速やかに要綱のほうも改正いたしまして、認証に通われるお子さんも同じ恩恵を受けられるように速やかに手続を進める予定です。","voiceIndex":42,"id":"exchange-015"},{"speaker":"あべ委員","kind":"確認","question":"そこまで配慮していただいて、大変ありがたいです。認証についても、対象の方については区のほうで手続なしといいますか、認証のほうはたしかスタンダードな手続は必要だったと思ったのですけれども、手続的に何か必要なことがあるかというのと、それから、要綱の適用日は４月１日からということでいいかどうかという、その点、確認させてください。","respondent":"竹田保育課長","answer":"手続上の問題ですが、すみません、詳細は把握していないのですが、できるだけ保護者の方にご負担にならないような形を考えております。それから、もう一点のご質問ですが、適用日は、同じ４月１日を考えております。","voiceIndex":44,"id":"exchange-016"},{"speaker":"あべ委員","kind":"意見","question":"認証に入られている方の多くは、認可に入れなかった方が多いということを考えると、やはり認証の方も漏れがないように、この制度改正の恩恵に匹敵するものを受けられるようにということで、ご配慮いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それぞれのところで、半額と無償の子どもの数、多分、出ていると思うので、別表の３と４と５のところに該当する子どもの人数を、さっきのはざっくりしていたので、できましたら詳しく教えていただきたいと思っているのですが、あと、そこの別表３のところの今までの予算というか、平成２８年度から動き始めましたけれども、そこの予算と、別表４と５のところは当然国から予算が来ると思うのですが、その辺。","respondent":"竹田保育課長","answer":"人数ですが、別表３は半額になる児童の区分ですが、４月に小学３年生までに拡大したところで、半額になる児童数は約１,０００人ほど増えております。それから、別表４のところが……。","voiceIndex":47,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今はわからないということで、別表４と５のところの内訳は後でも結構なので、数字を出していただきたいと思います。国からの予算はまだこれからということですけれども、別表３のところの予算が、多分品川独自のところのは立っていたと思うので、別表３の１,０００人と１５０人のところの予算がどう立てられていたのかだけでも教えてください。","respondent":"竹田保育課長","answer":"すみません、今、細かい数字は持ち合わせていないのですけれども、それぞれ人数増を、先ほど申し上げましたとおり、第２子が１,０００人、それから、第３子の対象者が１５０人程度増えることを想定しておりましたので、そちらに合わせた予算組みをしています。","voiceIndex":51,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ国の制度が入ってきて、具体的に財政がどうなったのかというところも知りたいので、この部分に関しては今年度、平成２８年度の予算が立っているはずですよね。別表３のところの１,０００人と１５０人。そこの数字は後でも結構ですので、教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見を添えて、賛成したいと思います。子育て支援に所得制限を設けることは適切ではないと考えています。しかし、今回は低所得者の多子に関して年齢制限撤廃ということで、拡充されるということで、歓迎したいと思います。今後に関して、年収３６０万円以上の世帯に対しても、多子軽減の年齢撤廃を求めていきたいと思いますので、よろしくお願いします。本案に対しては賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"}]},{"id":"topic-03","title":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"１つは、過去の宮古市復興支援の取り組みのこれまでの成果はどのようにお考えなのでしょうか。それと、２番目として、今までの事業費はどの程度かかっていて、誰が負担していたのでしょうか。３番目として、品川でも活動に取り組んでいる、こちらの主体はどなたなのでしょうか。それから、４点目は、現地での対応は主にどなたがされているのでしょうか。以上、４点のご質問にお答えをお願いいたします。","respondent":"高山子ども育成課長","answer":"過去３年間、こういった同種の事業を実施してきた成果としましては、品川区のＰＴＡと、それから現地の宮古市のＰＴＡとのつながりという中で、さまざまな復興支援にかかわります事業、例えば、義援金の提供でありますとか。","voiceIndex":83,"id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"非常に意義ある成果が得られた活動だと思うのですが、これは今回なぜ補正で計上されているのでしょうか。","respondent":"高山子ども育成課長","answer":"６月補正にのせた意義といいますと、実はこの件につきましては、先ほど申しましたように、これまでは震災復興のモニターという形で運営されてきたこともありまして、品川区の直接的な関与というのはなかったのですが、今申し上げたような大変有意義な取り組みを。","voiceIndex":85,"id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今、お話を聞いていて、非常に有意義な取り組みだし、地域の交流もあるし、防災対策にもなるので、ぜひとも継続するために予算化したということは非常によろしいことではないかと、うちの会派も高く評価するのですが、今後の継続に対する区の取り組みと、今後予想して、継続していくことに関して、例えば、今回のこの事業の親子交流に行政の職員の方も同行して、実際、現地をよく視察して。","respondent":"高山子ども育成課長、齋藤子ども未来部長","answer":"それによって、事業の成果、評価などもしていければというふうに考えております。今回、宮古市の市長さんともお会いして、義援金をお渡しすることになっておりますので、私が代表として行きますので、事業の成果についてはまた来年継続できるような形でできればと考えています。","voiceIndex":87,"id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"意見","question":"すばらしい事業なので、ぜひ今後も予算化して積極的な取り組みをお願いしたいと思うのですが、齋藤部長からも後で十分報告を聞かせていただけることを楽しみにしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"それで、皆さんご存じのとおりですけれども、今のお話にもあったように、これまで３年間、区のＰＴＡと現地の皆さんとでつくり上げてきた事業と考えているのですけれども、４年目から予算の出どころが変わったことによって、主催ですとか、事業の性格が変わったというとあれですけれども、ちょっと形として仕切り直しをしたというふうに考えていいのでしょうか。","respondent":"高山子ども育成課長","answer":"資料のつくり込み上、ＰＴＡのＰの字も出てこないというようなご指摘はあるのですが、一応と申しますか、この内容で実施させていただきたいということではあるのですが、その担い手等については契約上の話となってまいりますので、あえてといいますか。","voiceIndex":91,"id":"exchange-026"},{"speaker":"あべ委員","kind":"確認","question":"それぞれありがとうございました。確認なのですけれども、区の委託事業ということで、委託先はＰＴＡなのですか。それとも、「つなこし」になるのでしょうか。委託先を教えていただければと思います。","respondent":"高山子ども育成課長","answer":"委託先につきましては、「つなこし」という品川区の小学校ＰＴＡ連合会から派生した非営利団体ということで、そちらのほうと委託契約を考えております。","voiceIndex":93,"id":"exchange-027"},{"speaker":"のだて委員","kind":"確認","question":"宮古市のほうですけれども、先ほども出ていましたけれども、実際にこれを、行った先で委託事業者の方が添乗員というのですか、ついて回って、いろいろな体験、森の体験とか川の体験をやるところで、インストラクターの方が説明してくれるというようなものになるのか、確認です。それとも自己負担になるということなのか伺いたいと思います。伺います。","respondent":"高山子ども育成課長","answer":"こちらのほうの事業実施にあたりましては、引率者として、「つなこし」のメンバー７人が東京から赴きまして、現地でのそういった活動全般にかかわっていただくです。","voiceIndex":96,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"３年間やってきたということなのですが、この間の参加人数とか、あと、感想文とかそういったまとめというのはあるのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"ということで、参加者につきましてはそういった状況でございまして、それから、感想などをとっているかという点で申しますと、そういったものにつきましては一部伺っておりまして、例えば、一部ご紹介しますと、親御さんのご意見としては。","voiceIndex":98,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"過去３年間が、３０名、５０名、７０名と参加人数がどんどん増えていって、今回、１０組２０名ということで減ってしまうわけなのですけれども、区がやる最初の年ということで２０名になっているのかもしれませんが、今後、拡大していく予定はあるのでしょうか。","respondent":"高山子ども育成課長","answer":"そういう意味では、１０組２０名で１００万円というのをどういうふうにご評価いただけるかというところもありますが、今年度実施してみて、例えば、応募の状況でありますとか、あるいは現地での対応、現地での感想なども踏まえながら。","voiceIndex":100,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"八潮の幼保一体施設のほうなのですけれども、今の八潮わかば幼稚園の定員数は書いてあるのですが、幼保一体になったときに、保育園のほうは何人になるのでしょうか。現在の八潮南保育園は１０２名だと思うのですけれども、それが維持されるのか、伺いたいと思います。幼稚園の４歳、５歳部分も含めてあるのか、こういうことを教えていただきたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"３点目なのですが、並列型か年齢区分型かというところなのですが、現時点では並列型を予定しています。保育園に関しては０歳から５歳児まで、幼稚園に関しては４歳、５歳の幼児というところで考えております。","voiceIndex":102,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"幼保一体施設をこれから何園つくっていくとか、この位置づけとか、体系的な計画というのはあるのでしょうか。３点目が、八潮南保育園、一体化されたときに八潮南保育園があくわけですけれども、八潮南保育園の敷地はどういうふうにしていくのか、教えていただきたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"３点目の八潮南保育園の扱いなのですけれども、平成２８年２月の文教委員会でもお話ししていますが、その時点の乳幼児人口であったり、他の地区の保育園等の整備の状況等でまた検討する、そういう考えです。","voiceIndex":104,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"保育園の基本設計はまだということで、それは申しわけありませんでした。一緒に実施設計をやっていくということで、しかし、やはり考え方としては、同じ規模を維持していきたいということなのか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"八潮南保育園から動く定員の数なのですけれども、繰り返しになって申しわけないのですけれども、設計の中で検討するのですが、基本的に移ったお子さんに関しては必ず当然卒園までいていただくことになるのですけれども、定員に関しては、その時点の近隣地区の保育園の整備状況。","voiceIndex":106,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"リオ大会の後にこれを配るとなっているのですけれども、リオは確かに迫っているので、時間的に難しいというのはあるのでしょうが、大会後に配るということはなぜなのか、伺いたいと思います。マイスクールのほうで、今回、補正になったというのは、先ほど少しご説明がありましたけれども、どうして補正に入ることになったのか、もう少し詳しく伺いたいと思います。","respondent":"熊谷指導課長","answer":"１点目の、オリンピック・パラリンピック品川版の学習読本ですが、これは補正ではないのですけれども、そのことをお答えしたほうがよろしいでしょうか。補正は、各学校に都から委託ということで、各学校３０万ずつつくものなのですが……。","voiceIndex":108,"id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"八潮についてとマイスクールについてと、それぞれ伺いたいと思います。それと、やはり平成２９年度から工事が始まるということは、これから入園を考えていらっしゃるご家庭にとっても非常に大きなお話だと思いますので、どういった形で周知をしていくのかということを教えてください。","respondent":"佐藤保育施設調整担当課長","answer":"４歳、５歳、１クラスずつしかありませんので、６つの部屋のうち２つを利用しているというところなので、２年間かけて順繰りに、居ながら工事を行う予定です。","voiceIndex":113,"id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"この改修工事は民営化の議論と非常に密接なかかわり合いがあると思うのですけれども、これは実施設計は１,９００万円となっていますが、工事費用はかなり何億という数字になってくるのでしょうか。それが区で行うことと、今後民営化する、ごめんなさい、質問がうまくまとまらないのですけれども、この工事と民営化の議論とのかかわり合いというのを少し説明していただけますか。","respondent":"佐藤保育施設調整担当課長","answer":"１点目の、工事の安全に関しては、最大限努力してやっていきたいと思います。２点目、幼稚園の申込者への周知に関しては、委員ご指摘のところを考慮しまして、近隣施設等々へのチラシであったりというのもやっていきたいと思います。","voiceIndex":115,"id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"民営化等、この工事のかかわりについては明日改めて質問することにいたしまして、あと、もう一点、五反田のマイスクールなのですけれども、すみません、コーディネーターが新規につくことによって、五反田マイスクールの事業内容が何か変わる部分があるのか、人が手厚くなるけれどもやっている内容は特に変わりませんということなのか。","respondent":"村尾教育総合支援センター長","answer":"特に大きな部分としては、やはり家庭との連携をどう図れるかというところで、コーディネーターにはぜひ適応指導教室とか、また、不登校の子どもたちとかかわったことがある経験者を配置させていただいて、より手厚くできればと考えているところです。","voiceIndex":117,"id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"コーディネーターには例えば、元教員とか、学校現場にいらした方、あるいは心理系の方、どういった方を想定されているのか、あるいはどのように募集、選考をするのかということを教えてください。","respondent":"村尾教育総合支援センター長","answer":"現在、コーディネーターには、マイスクール八潮の指導員に入っていただいて、やはりキャリアを持っていますので、かかわり方等、とても経験則を持っていますので、そこを充てて進めていこうというふうに考えているところです。","voiceIndex":119,"id":"exchange-038"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在、４歳と５歳で１部屋ずつ使われているということでしたが、具体的な人数をお伺いしたいのと、あと、今後、募集に関しては、定員まで募集をされていくのかというところと、あと、今後の説明ですが、明日の民営化のところでもご説明があるかと思うのですけれども、具体的な、この幼稚園は上に住宅がありますので、住宅と密接をしているということでは、住民の皆様への周知も必要かと思うのですが。","respondent":"佐藤保育施設調整担当課長","answer":"２点目の八潮わかば幼稚園が入っている住宅等の住民への説明なのですが、理事者の方であったり、主要な方、あと、住民の方全体への説明会、全部で３回ほど予定しておりまして、丁寧に細かく説明をして、理解を得る努力をしていきたいと考えております。","voiceIndex":121,"id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"八潮においてはかなり大規模な改修になりますので、住民への丁寧な説明会、そしてまた、保護者等への説明もぜひお願いをしたいと思います。今後、新しいマンションもまたオープンしますし、公務員住宅も人が増えているということで、勝島地域、八潮の子どもの動向の方向性というのをどう捉えているのか、お聞かせいただきたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"現在、八潮の保育園に入っている八潮地区の人と、そうでない方の割合も、大体５割から６割程度が八潮地区の方で、それ以外の地区の方はその引き算で、４割から５割は他の地区の方というところもありますので、今後。","voiceIndex":123,"id":"exchange-040"},{"speaker":"新妻委員","kind":"質問・要望","question":"八潮においては、高齢化率が進んでいることもあって、子どもの数が減っていくという動向を読んでいらっしゃるということなのですが、勝島からのこの幼稚園への入園者というのをどう思われているのか。八潮に来るのは不便なので、八潮の方向には来ないというふうに読まれているのか、大井町のほうに通われるというふうに読まれているのか、そこら辺を確認させていただきたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"八潮わかば幼稚園に関しては、橋から八潮に入ってすぐ近くのところにありますので、一定、八潮地区以外の方の通園というのも今後もあるのかというふうに考えているところです。","voiceIndex":125,"id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"八潮のほうは、先ほど並列型というお話だったのですけれども、幼保一体施設は区内６つ目ですが、やはりこれは幼保連携型認定こども園というような、いわゆる新制度というようなものがあるけれども、その仕組みをとらないということで、区の方針として、やはりそこの方向にはつくっていかないという認識で進めているのでしょうかというところの確認です。","respondent":"高山子ども育成課長、村尾教育総合支援センター長、佐藤保育施設調整担当課長","answer":"「つなこし」という団体の活動が、この被災地応援ツアーにとどまらない活動をされておりますので、そういったその他の事業の進捗といいますか。マイスクール五反田の件で、委員おっしゃるとおり、４７６万円というのは国の予算となっていて、その中でコーディネーターは入っているのですが、実際。公立については、いわゆる保育教諭という雇用の課題が２３区全体でありますので、その辺の職員の採用も含めて、今、検討しています。","voiceIndex":127,"id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。宮古市のほうはぜひ継続をしていただければと思います。マイスクールのほうはわかりました。幼保一体施設のほうは、また別の機会に認定こども園について質問させていただきたいと思いますが、ぜひどういった形かでもいいので、どのようにしていくという研究を進めていければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、国からコーディネーターの予算がついたということは喜ばしいと思っていますけれども、１９２万円で、ちょっと伺ったら、週１回の非常勤だということなのです。もう一点は、八潮の幼保一体なのです。この辺、ぜひ計画をきちんと示してほしいし、先にやるべきところもあるのではないかというところにおいては説明が全然されていないと思うので、その点が１点と、なぜ急に幼保一体なのか。","respondent":"村尾教育総合支援センター長","answer":"コーディネーターにつきましては、先ほども少しお話ししたのですが、国のほうの施策、特にモデル事業の中の一つの重点として、教育支援センター等の設置促進の中のコーディネーターの配置というのは、国のほうもやはりいろいろ今考えているということで、今回。","voiceIndex":132,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろ考えてはいるのでしょうけれども、１つには、改修、改築、これのみんなが納得できるような計画がないのです。なので、私、ここ、本当に一体化施設の計画だけでちょろっと出てきてはいるのですが、とてもそれだけで認めるというわけにはいかないと思うのですが、大きな計画とかなしに、こうやってなし崩し的に進めていくというところの問題点は感じていないのでしょうか。お伺いします。","respondent":"佐藤保育施設調整担当課長","answer":"計画については、幼保の計画もそうなのですけれども、繰り返しになって申しわけないのですが、仮設を建てるところの土地の手当てが決まらない限り、具体的な工事スケジュールが立てられない状況がありますので、それでも区は数年前に、今回もそうですけれども。","voiceIndex":136,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"意見","question":"幾つかあるのですが、今の八潮の幼保一体のところで、反対をいたします。幼保一体、それ自体には反対ではないのですけれども、新しく品川区の方針である民営化の流れの中で出てきている基本設計ということで、この部分は納得できないので、反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-046"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、社会、地域、家庭など、さまざまな問題が絡み合ってのことだと思うのですが、そこが不明確のままなのですけれども、連携とかいろいろおっしゃっていましたが、今後、どういったことで自殺をとめていくおつもりなのかというところにおいては、４年間で８人の尊い命が失われたと質問の中でしているわけですけれども、生きるのに困難な要因を探して一つ一つなくしていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-047"},{"speaker":"あべ委員","kind":"質問","question":"区としてどう受けとめ、どんな対応をするのか、したのか。あるいは、運営費や開設準備補助金などの再精査といったらいいのでしょうか、そういったものをするかしないかというようなこと、ご報告があるのかと思っていたのですけれども、明日の事項にも載っていないので、もしご報告いただければと思っているのですが、それをするかどうかは正副にお任せいたします。","respondent":"竹田保育課長","answer":"今後も区は立ち入り検査を定期的に行うなど、不適切な支出がないよう、指導、検査を強めていく考えです。","voiceIndex":151,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4886#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":32349,"voices":154}},{"id":"h28-20160627-5","meetingId":"h28-cm06","date":"2016年6月27日","dateIso":"2016-06-27","committee":"総務委員会","time":"午前１０時００分～午後 ４時３５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"では、(1)の第５４号議案からの審査ではありますが、会議の運営上、順番を入れ替え、審査を行います。 まず、(6)第６６号議案","agenda":"では、(1)の第５４号議案からの審査ではありますが、会議の運営上、順番を入れ替え、審査を行います。 まず、(6)第６６号議案","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"先ほど視察のときに、だれでもトイレとかができるというふうに言われたのですけれども、どの辺に、どれぐらいの、一つですか。だれでもトイレのことを教えていただけますか。","respondent":"溝口公園課長","answer":"経理課のほうでご用意した資料の９ページをご覧いただきたいと思います。今回、管理棟を建設します。この中に組み込む形でだれでもトイレを設置する形になっております。トイレ自体はだれでもトイレが一つと、男女が分かれた形でのトイレをつくるという計画をしているものです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"私はいつもこの委員会で同じことを発言させていただいているのですけれども、だれでもトイレの中に最近はベビー用のおむつ交換台は当然設置されているのですけれども、ちょっと大きい成人用といいますか、そういうものは設置されているのかどうか確認したいと思います。","respondent":"溝口公園課長","answer":"基本的にだれでもトイレは誰でも使えるという形を考えておりまして、子どものおむつ替えとか、広さにもよりますけれども、なるべく設置していく方向になっております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"そうすると、この契約金額で確定してしまうと、大人用までは難しいということでしょうか。本庁舎の３階にありますけれども、素人考えかもしれませんけれども、それほどすごいスペースが必要というふうには見えなくて、もし可能であれば、もちろんベビー用にも使えるわけですし、そういうことが可能かどうか伺いたいと思います。","respondent":"溝口公園課長","answer":"この管理事務所につきましては、管理人が常駐しますので、そういったところでお話をいただければ対応できるような部屋というのも用意してありますので、そういったところで対応していけるというふうに考えてあります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうしても言葉の都合上、大人用という言い方をするのですけれども、ベビーではなくなった段階でベビー用のおむつ交換は使えなくて、例えば公園とかそういう施設は子どもたち用の施設を障害のある方も当然使うようなことは想定していただきたいなというふうに思います。今日、契約金額を決めてしまって、その中で無理ということであれば、それにかわるような、代替のことを検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"こういう建物でも、やはり杭工事というのはするのでしょうか。それと、想定される津波による被害も考えると思うのですが、地盤の高さというのはそういうものにも対応するようにできているように今回建てるのですか、それとも、そういうのは一切考えないでやっているのか、ちょっとその辺を聞かせてください。","respondent":"小林施設整備課長、溝口公園課長","answer":"構造的な杭のご質問ですけれども、当然地質に応じて、平屋だったらばベタ基礎をやったりするのですが、今回は２階建てなので、地質の調査をしてメーターを決めて、杭のほうの事業というのはあるものと私も認識はしております。いざ災害時には、そういったものが濡れないようにということで、備蓄倉庫については２階につくるような計画になっておりますので、一応災害上安全に利用できる。","voiceIndex":14,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"せっかくきちんとしたものを建てて、３０年、４０年もつと思うのですが、そういうような備蓄云々ということもあるならば、津波による想定される被害、その他、今、杭も地盤がしっかりしているとおっしゃっていましたけれども、民間の住宅はもっと地盤がしっかりしていても、仮に３階建てでも杭を打ってしっかりやっていると思うので、その辺、間違いないということでしたら何も申し上げることはありませんが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"一つだけ今まであった噴水をなくして、スペースの面だとか管理棟という建物の性格からして、前に噴水があるというのもちょっと位置的にはずれたほうがいいかなと思ったりするので、なくしたということについては、そういう点ではわからなくもないけれども、なぜなくしたのかという理由を１点伺いたいと思っているのです。その１点だけ伺いたいと思います。２点です。","respondent":"溝口公園課長、立川経理課長","answer":"水の利用とかになりますと、プールも夏場はありますし、またさらに今年度工事することでプレイパークですとか、また来年度子どもの遊び場、そういったものも整備していく検討をしておりますので。辞退の理由ですが、企業それぞれ理由がありまして、主なものとしましては、配置技術者の不足であるとか、積算金額の乖離、そういったことが主な理由です。","voiceIndex":18,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっとお伺いしたいのですけれども、構造の部分なのですが、鉄筋コンクリート造と管理棟も売店も両方なっているのですが、これについては、こちら側からそういうふうに提示したのか。例えばＳ造とかいろいろあるわけではないですか。それは行政側から出したのかどうなのかというのをまずお聞きしたい。","respondent":"溝口公園課長","answer":"一つはやはり、広域避難場所である区民公園にある管理棟になりますので、災害時にしっかり使える建物にしなければいけない、そういった観点で今回は鉄筋コンクリート造、また費用対効果、そういったものも含めて検討した中で定めて、今回発注させていただいたという形になります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"確認","question":"非常に今難しい時期だなと思っています。そう考えると、売店とかは、例えば軽量鉄骨造にすれば、多分安いはずなのだよね。管理棟が同じようにこれぐらい、ほとんど平屋で一部２階というぐらいだったら、今の、非常にここは業者が限られてくるということはあるかもしれないけれども、Ｓ造でも軽量鉄骨に近いＳ造みたいなものでも、確認の同程度の許可を取っているところもあるわけです。","respondent":"小林施設整備課長","answer":"エリアもその近くの場所になっておりますので、同じ業種がそこの売店も行きますので、工期がまた別だとそこら辺の構造的なものは再検討が必要ですけれども、一応工程が同じで、場所も近くだということで、同じ業種で進めるということで今回考えました。","voiceIndex":23,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お願いだけをしておきます。２棟あわせたのだから、逆に言えば。そういうことも含めて監理監督はしっかりやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"}]},{"id":"topic-02","title":"第７３号議案、大森駅水神口自転車等駐車場整備工事請負契約の変更","agenda":"第７３号議案、大森駅水神口自転車等駐車場整備工事請負契約の変更","exchanges":[{"speaker":"南委員","kind":"質問","question":"賃金水準の変動に伴いということなので、大体これ、１,０００万円もないですよね。本当にわずか、数百万程度のための変更ということなのですけれども、大体働いている職人の方々の賃金というのは、それに伴ってどのぐらい上がるというふうに見たらいいのでしょうか。わかる範囲でいいのですけれども、それだけ教えてください。","respondent":"立川経理課長","answer":"今回の改定では、全国では平均４.９％の改定です。工種により金額は異なりますが。東京都におきましては、全体平均で２.８％の改定額です。","voiceIndex":38,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"結構一般的には建築関係の方々の賃金というのは、以前に比べてずっと少なく、低くなってきているというふうに今までは言われていたので、賃金改定そのものは、私はいいことだというふうに受けとめていきたいと思っているのですけれども、自分で社会保険料も、いろいろそういうところも自分で賄うという点で、やはりどういうものなのかという実態をある程度つかんでおく必要があるのではないかと思うので。","respondent":"立川経理課長","answer":"下がっていればその分を計算し直す、その結果がこの金額になっております。","voiceIndex":40,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"全体から見れば２２５万円何がしですが、実際これが民間だったら、これぐらいは工事費の中で吸収してよという話になると思うのです。何か非常に不思議な世界かなと。ちょっと民間ではこの規模だとほとんど考えられないのですが、その点で、課長、見解として、こういうのが当たり前のように区としては考えているのでしょうか。ちょっとなじめないので、その辺、ご答弁いただければありがたい。","respondent":"立川経理課長","answer":"その根底には、いわゆる公共工事の現場の労働者の賃金というのは、これまで低く抑えられ気味であったということがありましたので、その辺を踏まえまして、平成２５年からこの特例措置というのが実施されているところです。","voiceIndex":46,"id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"本来そういうことならば、日本全国の民間企業なんかは、そういうことを訴えて適正な労働賃金にしなければおかしいなと思うのと、実際我々が聞いた話だと、実際に賃金が上がっているのは大手のほうに賃金が吸収されて、中小、子ども、孫請け、ひ孫請けには、逆にそのまま賃金が上がらずにいるという話さえ聞く現状で、何かちょっと不思議な状況だと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"最初から明解に出ていれば、そこから単純に２.何％上げればいいということになるわけで、そこは多分これはこれぐらいの中でというので、いろいろ行政側も努力をされて、せめぎ合いをして業者ともやって、この２２５万円というものが出てきていると私は理解だと思っていたのだけれども、それはそうではなくて、予定価格から最初からそういう金額を見込んでやっていて、それに対してのとなると。","respondent":"立川経理課長","answer":"先ほどちょっと申し忘れたのですけれども、基本的に民間は数社から見積もりをとるなりして、いわゆる現場の実勢価格をもとに予定価格を定めて発注しているということですけれども、いわゆる公共工事におきましては。","voiceIndex":49,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"確認","question":"ときに除外規定みたいなものもあるわけではないですか。普通、例えば物価上昇分を見込んで入札するわけだ、民間だったら。ところが、物価高騰分は別にしてもいいですよ。それは都の補助金の中でも、それはそうしましょう、そうしておかないと不調ばかりで入札できなかったら、工期が遅れてしまうから、そういう形をとろうとしているわけではないですか。行政はそうはできないではないですか。確認だけ。","respondent":"立川経理課長","answer":"委員ご指摘のとおりいわゆる契約約款のところに、工事費につきましてはスライド条項というものを設けておりますので、急激な賃金や物価の変動に対しては、いわゆる契約の後に協議ということになっております。","voiceIndex":51,"id":"exchange-016"}]},{"id":"topic-03","title":"第７２号議案、勝島橋補修工事請負契約","agenda":"第７２号議案、勝島橋補修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"１点だけ。先ほど見させていただきましたが、できれば今こういう状況で補修工事をしますよという写真ぐらい添付していただけるとありがたいなと。それだけはちょっと申し添えておきます。少なくとも一応表面はきれいだった。それだけです。","respondent":"立川経理課長","answer":"補修工事等の場合、現状の状態がどうなのかということを写真等で資料にしたいというふうに考えております。","voiceIndex":77,"id":"exchange-017"}]},{"id":"topic-04","title":"第６５号議案、総合庁舎熱源改修工事請負契約","agenda":"第６５号議案、総合庁舎熱源改修工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"確認させてください。老朽化に伴うということなのですが、大体どれくらいたったものなのかということと、こういうものは大体これぐらいの期間で安全性を確保するために更新していくものなのだよということの決まりがあるのか、その辺のことを教えてください。","respondent":"立川経理課長","answer":"前回いわゆる熱源機器の改修を行ったのは２４年前です。それで、設備につきましては大体２０年前後で改修したほうがいいというふうになっておりますので、今回はそのタイミングということで実施するものです。","voiceIndex":91,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ伺ってもいいですか。ちょっと話が全然違ってしまうかもしれないのですが、庁舎の夜間出入口のところ、あそこら辺というのはにおいがずっと問題になって、とれないではないですか。あれは、ここの箇所がどうなのかわからないのだけれども、こういう工事のときに、あれの根本的な工事というのはできるのなら、やれるのではないですか。","respondent":"小林施設整備課長","answer":"ただ、今スロープの下というところについてはかなり改善されていまして、においはまるっきりなくならないですけれども、かなり改善されたと思います。","voiceIndex":93,"id":"exchange-019"}]},{"id":"topic-05","title":"第７０号議案、品川図書館空調改修工事請負契約","agenda":"第７０号議案、品川図書館空調改修工事請負契約","exchanges":[{"speaker":"南委員","kind":"確認","question":"１点だけ確認なのですけれども、別々だということはちょっとわかるところなのですけれども、改めて六行会の地下にホールがありますよね。あそことは全然別の仕組みになっているということで、品川図書館だけというふうな理解なのですよね。空調は全体かなと、ちょっとそういうのもあるので、その点を確認したいのですが。","respondent":"小林施設整備課長","answer":"そのとおりです。今回の図書館エリアにつきましては、２階から４階までです。","voiceIndex":107,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"それからもう１点、これから夏に向かっていく中ですけれども、工事は当然この夏は回避をして工事をされるのだろうと思っているのですけれども、その辺の確認。それと、工期は出ていましたか。もし、工期が出ていたら私が見落としているので、わからないので教えていただきたい。","respondent":"小林施設整備課長","answer":"資料の２４ページの３番目の工期、平成２９年１月３１日を目標に工事をいたします。それで、今のところは３フロアありますので、一つのフロアごとに改修工事を施工する予定です。","voiceIndex":109,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"終了が１月３１日であって、工期の開始というのは夏の暑い時期を避けてやるのだろうと思うのですけれども、開始時期がいつごろからかなというのがちょっと知りたかったので教えてください。","respondent":"小林施設整備課長","answer":"失礼いたしました。冷房運転期間につきましては、９月末までは冷房を効かせまして、その後１０月ごろから停止をして、本格的に工事を進める予定です。","voiceIndex":111,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"すみません、ちょっとお聞きしたいのですが、金額も結構、２億円ということであれなのですが、実際空調工事という改修工事ならば、さまざまな区内にある電気工事店でもできるのではないかなと思ったのですが、まずそれをちょっとお聞きしたいのと、これは制限付きになっているのですが、そういうところが入れないのかなと、そこまで制限されているのかなということと、２階、３階、４階。","respondent":"小林施設整備課長","answer":"一つの機械で４０馬力だとか、かなり大きいものを２台入れたり、１台入れたりとか、フロアで４台ぐらいそれを入れますので、かなり高額になってくるのは確かだと思います。","voiceIndex":113,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"すみません。もう１点お話ししたと思うのですが、普通のまちの電気屋ということではなくて、品川区内に電気工事店がたくさんありますよね。おそらくそういうところも、こういう工事ならば参入できるのではないかと思ったのですが、そこでやはり制限をかけているというのはどういうわけなのですか。","respondent":"立川経理課長","answer":"いわゆるＪＶを組んでの入札ということになりまして、第１グループですと区内業者であり、過去１０年間で品川区発注の類似工事費が、いわゆる予定価格の３０％以上あるということ、それから第２グループでは、いわゆる区内企業であり、格付がＡからＣまで。","voiceIndex":115,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"すみません。先ほどと同じような趣旨の質問になるのですけれども、これについてもさっき口頭でのご説明では老朽化とあったかなと、この文書には書いていないのですが、どの程度の老朽化で、先ほどみたいにどれくらいで更新すべきものとして今回の工事なのか、その辺を教えてください。","respondent":"小林施設整備課長","answer":"ただ、今回のこの部分については、既に一部空調関係で故障が多発しているということでありますので、主管課のほうからは早急な対応が必要ということで、こちらに執行委任が来ているです。","voiceIndex":117,"id":"exchange-025"}]},{"id":"topic-06","title":"案、芳水小学校第１期校舎改築その他工事請負契約、(8)第６８号議案、芳水小学校第１期校舎改築その他空気調和設備工事請負契約、および(9)第６９号議案","agenda":"案、芳水小学校第１期校舎改築その他工事請負契約、(8)第６８号議案、芳水小学校第１期校舎改築その他空気調和設備工事請負契約、および(9)第６９号議案","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それで、この学校が改築されるということは、あの地域の、規模が多分大きくなるのだろうと思っているのですけれども、どのくらい大きくなるのかがもしわかれば教えていただきたいのと、あの地域の子どもたちの人口予測との関係をどういうふうに捉えているのかというのを改めて伺いたいと思います。とりえあえず３点です。","respondent":"篠田学校計画担当課長","answer":"人口予測ですけれども、ご案内のとおりあの地区は再開発が進んでおりますので、現在１５学級でクラス編制をしておりますが、この先１８クラス以上のクラス編制が見込まれるということで、今回最大でも２４クラスまで、普通教室もとれるような形で設計しておりますので。","voiceIndex":131,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと私わからなかったのですけれども、５０年たっているという点はわかりました。それと、人口予測して２４学級まで可能だというところは、それはそれとして説明として伺ったのですが、ということは、もっともっとあの地域の小学生の数が増えていくという予測を持っているということなのかどうか、ちょっと確認をしたいと思いました。それで、ちょっと教えていただきたいと思いました。","respondent":"小林施設整備課長、篠田学校計画担当課長","answer":"それで、児童たちの安全を確保する担保がこのままでいきますとありませんので、一斉にやるということで教育委員会は答えを出して、年度を分けてやっていったところです。ただ、中身につきましては、例えばレイアウトですとか、運営方法その他のものにつきましては、現在、品川図書館のほうでいろいろ検討を進めているです。","voiceIndex":133,"id":"exchange-027"},{"speaker":"南委員","kind":"確認","question":"一度耐震しているのに、今回の大規模改築になるというのは、今説明をいただいた中で、結局今の状況だと人口増に対応できないからリニューアル、全面改築するのだと、そういうことなのですか。人口増というふうにちょっと私は説明を聞いて、トータルでそういうふうに受けとめたのですけれども、それでいいのかどうか、ちょっとそこを確認したいと思います。","respondent":"篠田学校計画担当課長","answer":"人口増という要因もありますし、あわせまして、施設の老朽化等ありますので、確かに耐震改修はしているのですけれども、この先人口増等への対応を考えますと、この場ではなかなか受け入れもできないということもありますので、総合的に判断した結果。","voiceIndex":136,"id":"exchange-028"},{"speaker":"南委員","kind":"確認","question":"最後に。そうすると、今の建物では、９年前と６年前に２回にわたって建築基準法上待ったなしという校舎の状況があったので、耐震改修はしたけれども、人口増にはとても耐えられる、そういう状況ではなくなる、予想されるということで改築をしたと、こういうことでいいということですかね。確認をしたいと思います。","respondent":"篠田学校計画担当課長","answer":"基本的にはそういった認識で総合的に判断をして、こういった選択をさせていただいたです。","voiceIndex":138,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"先ほどのご説明だと、多目的室、地域利用エリアが今回話題になっている大崎図書館の代替施設ということはわかりました。レイアウトとかはこの後、今議論の途中ということですが、そもそもスペース的な広さが今の図書館の床面積といいますか、それと比べでどうなのでしょうか、教えてください。","respondent":"篠田学校計画担当課長","answer":"現在の大崎図書館については、申し訳ございません、正確な数字は持ち合わせていないのですが、２,０００m2を超えるような形の床面積をとっております。今回多目的室として学校側のほうに用意されるスペースの広さとしましては、５００m2を予定しています。","voiceIndex":140,"id":"exchange-030"}]},{"id":"topic-07","title":"第７４号議案、浜川雨水排水管建設工事その２請負契約の変更","agenda":"第７４号議案、浜川雨水排水管建設工事その２請負契約の変更","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"説明のところに、施工方法の変更に伴いと書いてあるのですけれども、これはちょっとよくわからなかったので、説明をしていただきたいと思います。施工方法がどういうふうに変わったのかというところを教えていただきたいと思います。","respondent":"和田河川下水道課長","answer":"現場で立坑を掘ってみたところ、別の下水道管が支障となりまして、そのドリルを設計どおりに設置できないことがわかったものです。そのことから、このドリルの角度や位置などを変更したものです。","voiceIndex":170,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"ちょっと全然専門的なところでわからないのですけれども、角度を変えたりとか位置を変えたりということで、しっかりと既設の管にはまるような、そういう設計に変更したということなのですけれども、それは掘り当てて初めてちょっと変更しなくてはいけないということがわかったのか、あるいはどういう形で、どこまでどんなふうにわかったのかということを教えてください。","respondent":"和田河川下水道課長","answer":"ですから、その立坑を掘るときに初めてそこにドリルを掘削するための位置と角度、既設の下水道管があるということがわかりましたので、その立坑を掘った時点から変更の事象が発生したです。","voiceIndex":172,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"そういう工事の変更というのは、こういう形での変更というのはよくあり得ることなのですか。いろいろな、中に埋設物が埋まっていたとか、全然予想もしなかったようなものが入っていたということはよくあるのですけれども、あり得ると思いますよね。結局見えないところですから。今回のようなケースというのは、一般的にあり得ることなのかというところをちょっと知りたいです。","respondent":"和田河川下水道課長","answer":"通常下水道工事のみならず、開削工事を伴う工事にこういう変更はつきものだというふうに申し上げておきます。","voiceIndex":174,"id":"exchange-033"}]},{"id":"topic-08","title":"よび費用弁償に関する条例の一部を改正する条例、(2)第５５号議案、品川区監査委員の給与等に関する条例の一部を改正する条例、および(3)第５６号議案","agenda":"よび費用弁償に関する条例の一部を改正する条例、(2)第５５号議案、品川区監査委員の給与等に関する条例の一部を改正する条例、および(3)第５６号議案","exchanges":[{"speaker":"南委員","kind":"質問","question":"第５４号議案の中ほどの３に書いてあるように、月の初日からその月の末日まで、一月というふうに理解するのですけれども、そういう場合には支給しないというふうになっているのですが、例えば出勤できない日にちが１日ではなくて、中ごろから次の月にまたがって、中ごろで出勤できるようになったという場合は、これは適用しないと、そういうことになるのですか。","respondent":"久保田総務課長","answer":"ただ、出勤ということだけが勤務の実績ということではございませんので、例えばいろいろな視察に行かれるとか、またいろいろな意見を聞くといった機会もありますので、登庁して会議に出ていただくということだけではなくて、その他。","voiceIndex":212,"id":"exchange-034"},{"speaker":"南委員","kind":"意見","question":"そうすると、１日から末日まで、この期間という規定だということで、たとえ３０日とか３１日休んだとしても、１日から末日までというところに該当しなければ支給はするよと、そういうことになるということでいいのですね。","respondent":"久保田総務課長","answer":"そのような規定になってあります。","voiceIndex":214,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"わかりました。その次に、職責を果たすことができないと認められるときはというのは、どういうことなのか、職責を果たすことができないという、ちょっと概念的にはわかるけれども、どういう状況のときをこういうふうに該当するよというふうになるのかを教えてください。","respondent":"久保田総務課長","answer":"杉並区を例にとってみますと、今回の裁判になった選挙管理委員会の方なのですけれども、脳出血等を起こして意識障害があったということで、選挙管理委員としての職責が果たせなかったですので、大きな一つの例としましては、そういった形で自分の意思を明確にあらわせない。","voiceIndex":216,"id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"確かに脳出血をして病院に入院している、出勤できないと、そこはわかったのですけれども、例えばお医者さんの診断書をいただくとか、その辺の確認というのが、職責を果たせないという確認というのは、誰がどういうふうに決めるのかというところが、あまり不明確だと拡大解釈したり、ケース、ケースでというのもあったりして大変になるかなと、ちょっとそんな危惧があるので、聞いているのですけれども。","respondent":"久保田総務課長","answer":"ですから、そこはきちんとした事務局の職員等が勤務実績として確認ができるというものが勤務実績になるです。","voiceIndex":218,"id":"exchange-037"},{"speaker":"南委員","kind":"意見","question":"明らかに病院に行って、お見舞いも含めてちょっと様子を見に行ったときに、いろいろな管につながれて、ちょっとこれでは無理だろうなと思う、そういう場面というのはあると思うし、それは無理だというふうに判断ができると思うのですけれども、やはり厳密にしておかなければいけないのかなという気がするので、私は個人的にはありかなと思ってはいるのですけれども、誰がそういうふうに判断。","respondent":"田村総務部長","answer":"それはなぜかというと、行政委員だとか選挙管理委員だとか、例えば腰痛だとか風邪だったら、普通に仕事ができるのでいいのですけれども、例えば意識障害になってしまったりすると、やはりお医者さんの判断というのは専門的な判断として必要だし。","voiceIndex":220,"id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"すごく理解できるところですから、確かに個別に判断していくしかないのだというふうには思うのですけれども、また杉並区の裁判になったということは実は私、あまりよく知らなかったのですけれども、そういうふうになってくるというところはわからなくはないので、住民目線で見たときに、やはり一定の評価とかいろいろな意見があったということは事実なので、それはそれとして理解できなくないので。","respondent":"久保田総務課長","answer":"部長から答弁がありましたように、個々のケースという話になれば、それは当然ながらその方、各委員の方の症状とか判断の能力等を確認して判断していかなければならないというふうに思ってあります。","voiceIndex":222,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。月額報酬ということにこだわって、１回１回の会議ごとのものにしなかったというのは、要するに会議だけではない職務が具体的に想定されるからということで理解していいのでしょうか。例えば、日常的にそういうものというのはどれぐらい発生するものなのか、わかる範囲で教えていただきたいと思います。","respondent":"久保田総務課長","answer":"それ以外にも会議以外にも例えば研修会ですとか啓発活動、あと教育委員の方ですと、周年行事、学校の周年行事等にもご参加いただいてありますので、そういう意味では会議等以外にもいろいろな活動が日常的にあるというふうに理解していただいて、原則としては。","voiceIndex":224,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。行政委員会というと、具体的には教育委員会と選挙管理委員会というふうに理解しているのですけれども、〔「監査委員」と呼ぶ者あり〕監査委員、監査委員は別に考えるわけですよね、第５５号議案で。例えば、新宿区がこの二つを分けて考えていると思うのですけれども、片方はたしか出会手当のような形で考えていると思うのですが、何かそういうふうに考えられない理由があれば教えてください。","respondent":"久保田総務課長","answer":"行政委員としての報酬、費用弁償に関する規定を定めているというものです。その職責の中身とかをこの中で決めているものではございませんので、あくまでも報酬と費用弁償にかかわる部分の規定ということで、教育委員と選挙管理委員は１本でやっているというものです。","voiceIndex":226,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"さっきちょっとお聞きしたつもりだったのですけれども、会議を基本に考えるということは伺いましたが、そのほかに教育委員と選挙管理委員の日常的な職務で、教育委員のほうはそういうような周年行事とかほかにも、私もちょっと教育委員会のほうはわりとわかるような気がして、選挙管理委員会は、例えば選挙、今みたいなときは、選挙管理委員会はすごく大変なのではないかなと思うのですが。","respondent":"工藤選挙管理委員会事務局長","answer":"外部の会議といたしましては、２３区で特選連という会議体をつくっておりまして、そちらのほうでいろいろと委員長以下委員の方に出ていただきまして、情報交換をしましたり、全国的な組織で全選連という組織体がありますけれども、そちらのほうの総会に出ていただきましたり。","voiceIndex":228,"id":"exchange-042"}]},{"id":"topic-09","title":"第６４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","agenda":"第６４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"その他の契約というところは私たちが一般的に使っているレンタカー等々なので、そういう意味ではわかるのですけれども、その上の一般運送契約というのがちょっとよくわからなくて、こちらを読んでもちょっとわからない。申し訳ないのですけれども、教えてください。","respondent":"工藤選挙管理委員会事務局長","answer":"こちらのほうの一般運送契約ですけれども、こちらに載せてございませんけれども、ハイヤー、タクシー等、人を運送する事業者との契約ということになりますので、いわゆるその他の契約のレンタカーとガソリンと運転手の雇用。","voiceIndex":258,"id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"引き続きなのですけれども、その下のところの企画費というのは、さっきポスターのデザイン料だと説明されたのですけれども、そうするとカメラマンの費用というのですか、お願いした委託料、どういう名目なのかよくわからない、カメラマンの費用も入るということでいいですか。","respondent":"工藤選挙管理委員会事務局長","answer":"企画費の件です。先ほどご説明いたしましたように、デザイン料等ですので、そのようなカメラマン等を使っていると、かかる経費等もこちらのほうに含まれるです。","voiceIndex":260,"id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっとお伺いしたいのですが、公職選挙法というのが変わるということで、例えばここにこれだけ現行支給しますよというのがあるのだけれども、この金額というのは東京はこうだとか、地方はこうだとか、まず分かれているのかどうかというのをお聞きしたいのと、金額については、例えば国が一方的に決めてくるのか、例えば東京でもいいけれども、どこかの自治体で決められるということがあるのか。","respondent":"工藤選挙管理委員会事務局長","answer":"ただ、地方のほうでもいろいろと情報をとりましても、法律の要請が国に準じて基準を定めなさいという形になっていますので、基本的にはこの限度額ということで、統一的に行われているという認識です。","voiceIndex":262,"id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"質問","question":"各自治体が条例でということ。だから、具体的に言うと、どうしてこういうことを言うかというと、例えば運転手の雇用というのは１日当たり１万２,５００円ですよ。そういう両方のしばりがあるわけではないですか。公にちゃんと。しばりの中で我々もやっているのだから、それだったらこの金額を上げてほしいと思うわけではないですか。ここら辺の仕組みをもうちょっと具体的にわかるように説明してほしい。","respondent":"工藤選挙管理委員会事務局長","answer":"国に対する要望等というお話ですけれども、そういった実情等もいろいろといわゆる要望事項を挙げるというような、そういった仕組みも一つ残されてありますので、そういった中でこのような公費負担のあり方につきましては。","voiceIndex":264,"id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"意見","question":"それで、いろいろな方が立候補できるように平等にということであるならば、先ほど言ったように１点は車、これがこれぐらい公費負担してくれますよ、そこに運転手の方もこれぐらいしてくれますよ、ポスターもこういうふうにしてくれますよ、さっき言ったように、私が全部とは言っていないけれども、車を使う方の９割ぐらいの方は多分ウグイスさんがいて、そのうちの８割かそれぐらいの方は多分費用を払ったり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":266,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"やはり、公費負担に関する条例なのですけれども、今答弁されたように、選挙にお金をできるだけかけないようにするということは、それは当然のことだし、公費負担だからなおさらそこのところは額を多くすればいいというものでもないなとちょっと思ったのであれなのですけれども、もう１回確認したいのですけれども、公費負担という、その公費負担をこの選挙に関してつけるというふうになった。","respondent":"工藤選挙管理委員会事務局長","answer":"そういった意味では、値上がりした額という部分も、これも計算しますと３％前後だですので、私どももそのように捉えているところです。","voiceIndex":267,"id":"exchange-048"}]},{"id":"topic-10","title":"平成２８年請願第５号、「社会資本整備総合交付金」の活用など、八潮６９号棟が公的住宅として存続できるよう品川区に施策を求める請願","agenda":"平成２８年請願第５号、「社会資本整備総合交付金」の活用など、八潮６９号棟が公的住宅として存続できるよう品川区に施策を求める請願","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この請願には、社会資本整備総合交付金の活用などと書いてあって、品川区もこの交付金はさまざまな項目で活用している、そういう実態があるわけですけれども、品川区が活用している総合交付金は大体どんなもので、どんな内容があるのか、また今回住宅の購入にというふうになっているのですけれども、そういうことが可能なのかどうか、また予算書を見ると。","respondent":"柏原企画調整課長","answer":"簡単に言いますと、インフラ系の国のほうの交付金になってございまして、以前幾つか分かれていた交付金が平成２２年から統括といいますか、一つにまとめられて、比較的使いやすい交付金にということでまとめられた交付金です。","voiceIndex":283,"id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"そのほかのいろいろなところでも、例えば岩手、福島、新潟、富山、石川、山形県の村山市、そういうところでも一生懸命そういう努力をして、住民の居住を確保するというふうなことを自治体としてしている、そういうところで、やはり品川でもこういう請願が何回かにわたって議会に出され、区のほうにもいろいろな要望をお届けしていると思うのですけれども、今回の八潮の宿舎の売却について。","respondent":"柏原企画調整課長","answer":"その住宅について、国のほうの指針、そういったところが動く中で、まずは国のほうが基本的なところを考えながら経営に当たる、そういうところがまず基本的なところであるというのは、これまでもこういった議論の中でお話ししましたところでございまして、現在におきましても。","voiceIndex":285,"id":"exchange-050"},{"speaker":"南委員","kind":"意見","question":"雇用政策というのは国の問題だということはわかるし、品川区にそういう行政で分類したときには、雇用政策についてはなかなか該当する部分がないというところはこの間も表明してきたので、それはそれとしてわかるけれども、３２０世帯か３３０世帯ぐらい今居住しておられて、１,０００人ぐらいの方々が住まいを奪われてしまうという国の一方的な閣議決定によって、そういう状況に追い立てられて。","respondent":"柏原企画調整課長","answer":"そのことに対して、区だけでできることと、それから東京都や国にお話ししなくてはいけない部分、そういったところは種々ありますので、そういったところのお話を伺いながら、できること、何ができるかというのを含めて考えていきたい、そういったところです。","voiceIndex":287,"id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"民間売却になったとしても、１０年間は保証するけれども、その先、あと民間の購入した事業者の胸先三寸でわかりませんみたいな、そういう無責任な態度を国がとって、本当に国というのは許せないな、ひどいなというふうに思うのですけれども、現実がそこなので、やはり廃止は撤回しろという品川区の意思表明をするのと同時に、何とか手立てをとっていかないといけないというふうに思っているので。","respondent":"柏原企画調整課長","answer":"そういった行動をとりながら、区として何ができるのかというのをこれからも考えていくという姿勢でいるものです。","voiceIndex":289,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"そこを信頼していっていいのかどうか、そういう考え方で区は見ているのかというところもちょっと伺いたいと思っているのです。やはり居住者にとっては非常に大きなさらなる不安になってくるわけで、やはりこれはそういうふうな方向での解決策にしてはいけないと私は思うのですけれども、区はどういうふうに考えているのか、そこも伺いたいと思います。","respondent":"柏原企画調整課長","answer":"そこに対して、区でできる部分、できない部分がありますので、区が住んでいる方、区民の方に対してどういうサポートができるのか、そういったいったところを、例えば機構であったり、お住まいの方々に説明するといったところで対応させていただいているです。","voiceIndex":291,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"存続できるように検討を開始してくださいと、こういうふうなご要望について、今こういうものがあるので、何とも言えないけれども、しかし一定の方向性を区としては考えていただきたいと、こういう要望に対しては、やはり先ほどのような答弁に終わってしまうのですかね、もう１回その辺についてしっかり伺っておきたいと思っているのですけれども。","respondent":"柏原企画調整課長","answer":"その先どうなるかというのは、これは今のところは何とも言えるものではありませんので、注視するというところなのですけれども、先ほども社会資本整備総合交付金のお話がございました。","voiceIndex":293,"id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"機構のほうで出している条件として、１０年間は継続するということが挙げられていて、それは守られるだろうということなのですが、その契約の中に、もしその契約が守られない場合にはどうするというようなことが入っているのか、それで誰が保証できるのだろうかというのがちょっと疑問なのですけれども、その辺についてはいかがでしょうか。","respondent":"柏原企画調整課長","answer":"ですから、それ以上のことは想像の話になってしまいますので、こういうことは、ちょっとお答えは難しいかなというふうに思ってあります。","voiceIndex":295,"id":"exchange-055"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは契約以前に約束ですから、これがちゃんとホームページ等に載っていれば、私はそれが一つの大きな契約条件に基本的になると思います。品川区は今後もやはり機構に対しては住民に誠意ある対応を私は今までどおり要望してほしいということと、そしてこの住宅に住まわれる方々に対して、今後も親身なアドバイスをしていただきたいということはお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":299,"id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですが、例えばこれが請願項目１の最後のほうに「公的住宅として」と書かれているのですが、先ほども区においての住宅施策にかかわってくるというところで、例えばこれが住宅施策の中で区民住宅、区営住宅になったときに、今いる方たちは特定の目的を持って今住めるようになっているというところで言うと、区営住宅、区民住宅とか、区の住宅になったときに、公立的な立場からして。","respondent":"柏原企画調整課長","answer":"我々のほうとしても、今お住まいの方たちの細かい要件、条件等、例えば所得の状況であったり、そういったところまでは確認調査はしておりませんので、一概にどうなるかというのは、この場ではなかなかお答えが難しいのですけれども、そういう位置づけにしたということであれば。","voiceIndex":300,"id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"もちろん機構が今は当事者なわけですから、そこが第一に考えなければいけないのは当然だというふうに思うのですけれども、でも今現に公的な役割というか、いろいろなちょっと生活に対して弱い立場の方たちが現に住んでいらっしゃるということは、もし万が一そこにその方たちが住めなくなるようなことがあれば、結局は区に対してそれぞれ相談がいくようになるわけですよね。","respondent":"柏原企画調整課長","answer":"今後この話が例えば１０年という期限は一応ありますけれども、そういった中で、その後の動きというのはどうなのかというのは、仮にこの動きがそのまま進んでいたということになりますと、例えばそこのオーナーさんであったり、それから住んでいる方からすれば。","voiceIndex":302,"id":"exchange-058"},{"speaker":"石田（秀）委員","kind":"確認","question":"何点か確認をさせてください。だから、そこで確認をしたいのは、ここでそんなやり方はおかしい。これを平成３３年まで見通しといったら、私は１回の入札でもしだめだとしても、多分何回かやるのだろうと思うけれども、そこら辺のところは多分普通の入札の仕方だったら、そうだと思うのだけれども、これは一般論で構わないので、どういう流れになるのかなという一般論を教えてください。","respondent":"柏原企画調整課長","answer":"ただ、これから動く話ですので、結果については正直今お答えできないですけれども、仮に不調ということがあった場合でしたら、もう一度なり何なりで、別のやり方で同じようなことをやる可能性は検討していますというふうに事務レベルでは聞いてあります。","voiceIndex":304,"id":"exchange-059"},{"speaker":"吉田委員","kind":"質問","question":"今の石田委員のご質問にもありましたけれども、結局もし不調だとか、そういうような仮定のご質問だったかと思うのです。今機構の入札がどうなるかわからない段階で、議会として何かこの請願に対して採択、不採択というふうに決めてしまうのがどうなのかなというのもあって、これは皆さんのほうに意見なのですけれども、継続という可能性はないのか伺いたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":306,"id":"exchange-060"},{"speaker":"南委員","kind":"質問","question":"ちょっと私が質問したいと思って、今吉田委員のご意見もなるほどなというふうに思ってお伺いしました。ですから、使える、そういうものであって、やはり品川区が区民の暮らしを守る、居住を奪われる、そういう状況に対して品川区はわかりましたと、品川区としても、では安心を提供しましょうと、そういう判断になったときにも、財政的な影響はそんなにない。","respondent":"柏原企画調整課長","answer":"全国レベルで言いますと、１,２００件ぐらいまだ雇用促進住宅はありますので、トータルとしては維持管理という部分では大きなグロスの部分で言うと大きな数になるところでありますけれども、個々の住宅を見ていただくと、例えば今回の八潮の物件につきましても。","voiceIndex":308,"id":"exchange-061"},{"speaker":"南委員","kind":"質問・要望","question":"品川区もそこの点ではそうだという話なので、そうであるならば、やはりきちんとこの項目２の２番目に出ているように、例えば延長を政府に求めろとかというふうに出ているけれども、そういう意思があるのかどうか、あるいは延長ではなくて、こんなとんでもない撤回の計画案などはやめろと、そういうスタンスで国に発言するべきだというふうに思うのですけれども、今まで一度足りともしてきたのか。","respondent":"柏原企画調整課長","answer":"国に対しての意見というところであろうと思いますけれども、これも先ほど他の委員ともご議論させていただいたところですけれども、国が目的を持った住宅に対して判断をしたということに対して区がそれに対して何か物を申すべき立場ではないです。","voiceIndex":311,"id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"やはり必要な発言は、品川区民の生活そのものがかかっている問題ですから、やはり言うべきことは言う、そういうふうに自分は言ってきましたよ、区民の皆さん、八潮の皆さん、雇用促進に住んでおられる皆さん、こういう立場で品川区は頑張っていますよと、国に対してもはっきり皆さんの立場に立って、廃止を撤回しろと、そういう立場で言いましたというふうなことを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":313,"id":"exchange-063"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今各委員の質疑をいろいろ聞かせていただいて、請願の内容を確認させていただきましたが、請願者の住宅問題なのですが、こちらの６９号棟で、そもそも論でもしわかれば教えていただきたいのですが、自治会として機構とか国とかに対して何らかの、これまでもあったのかもしれませんが、交渉とかそうした部分もあると思うのです。","respondent":"柏原企画調整課長","answer":"６９号棟の自治会組織がございまして、その自治会の方とも何度か代表の方とお会いさせていただいてあります。","voiceIndex":314,"id":"exchange-064"},{"speaker":"つる副委員長","kind":"質問","question":"今話し合いということでありましたけれども、何か詳細なこととかというのは、特に自治会のほうからはお聞きしていないのですか。","respondent":"柏原企画調整課長","answer":"詳細な部分はどういった形で出したかというのは、お話では聞いてありますけれども、今回のこの入札という動きになったというところは承知していたけれども、機構の人たちがこれまでの経緯というか。","voiceIndex":316,"id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今日結論を出していただきたいと思います。不採択でお願いをします。いろいろ今お話を伺いましたけれども、今国の中で雇用促進住宅を廃止するということは決定しているということで、今入札も行われているということであります。それで、平成３３年ということまでには廃止、または今売却をしよう。売却をした場合は、１０年間その部分についての居住の賃貸条件も変えずにいくということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":319,"id":"exchange-066"},{"speaker":"つる副委員長","kind":"質問・要望","question":"最後に、各委員の皆さんの質疑を確認させていただいて、やはり居住者のお声というのが一番大事ということが大前提なのですが、そうした中で、そこに住まわれているまさに自治会の皆さんというのが、やはり住民の方のお声の代表であろうという観点を含めて、さっきお聞きすると、機構に説明を求めるとか、また加えて１０年間の維持という部分、これをしっかり担保させる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、今回は継続でいきたいというふうに思っています。１１年目以降がやはり不安になるわけで、そういうことでもって、よしとするわけにはいかないというふうに思うのです。非常に残念でした。したがって、採択を主張したかったのですけれども、継続で諮っていただきたい、継続を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":321,"id":"exchange-068"},{"speaker":"大倉委員","kind":"質問・要望","question":"皆様のさまざまなお話を聞いている中で、最後につる副委員長のほうから、６９号棟の方々が今厚生労働省と話し合いを求めていたり、１０年間を求めているというところで、しっかりと尊重していきたいという部分と、それに対して区も今話し合いを既にしているというところで、そういった意味では検討を開始しているのかなと、今後に向けてさまざまなお話し合いをしているという中では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":322,"id":"exchange-069"},{"speaker":"須貝委員","kind":"質問・要望","question":"私も、本日結論を出すということと、不採択ということです。まして、これだけの方々が住んでいるのを、どうやって追い出すのかなというと、なかなか私は難しい範疇にあると思いますので、あまり住民の方に不安をあおるというのはいかがなものかなというふうに思います。皆さんを守る法律もありますから、その辺はやはり住民の方もよく調べて対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":323,"id":"exchange-070"},{"speaker":"南委員","kind":"意見","question":"継続が少数だったので、今日採択をするということについては、賛成か反対か問うということについてはいいです。とっていただいていいです。〔「違う。採択か不採択かと言わないと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":328,"id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2048#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":64008,"voices":339}},{"id":"h28-20160628-6","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"区民委員会","time":"午前１０時００分～午前１１時２０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"──────────────────────────────────────────── (2) 区民斎場なぎさ会館仮設駐車場の一時移設について 次に","agenda":"──────────────────────────────────────────── (2) 区民斎場なぎさ会館仮設駐車場の一時移設について 次に","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"人道橋を渡って歩行者通路を通ってこの会館に入っていくのですけれども、これは裏口になるのですか。それはまた現地で移動とかさせるのですか。葬儀の動線です。葬儀場の。これは裏から入ってそのまま行ってしまったら、非常に葬儀の動線上よろしくないのではないかなと思うのですけれども。そんなに並ぶ葬儀をここでやるかどうかは別にしても、これだと裏口から入るようなイメージがあるのですけれども。","respondent":"提坂戸籍住民課長","answer":"人道橋を渡っていただいて、一旦歩道を歩いていただいて、３０ｍぐらいになるのですけれども、裏のほうから入っていただく形になるのですけれども、それについてご理解、ご協力をお願いしたいところです。","voiceIndex":8,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問","question":"ここで矢印がそのまま館内に入っているのですけれども、この館内と法面というのかな、どうなっているのかわからないのですけれども、ここの間というのは安全性の確保はできないのですか。外側からこう来て、正面入口から入ったほうがいいのかななんて。もしあれでしたら、実際に歩いてみてどうなのだというのはやってみてもいいのではないかなと思うのですけれども。イメージがわかないのです、この図。","respondent":"提坂戸籍住民課長","answer":"参列の方というのは２階のほうに移動していただく形になるので、さほど問題にはならないと思うのですが。本館があります。正面を閉鎖しているところではあります。","voiceIndex":12,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、先ほど少しありましたけれども、参列者が車に乗って、入り口前でおろすのはオーケーだということですけれども、それがオーケーかという確認と、そうすると、その車はぐるっと回ってこの駐車場へ行くと遠回りですよね。その案内というのですか、雨が降った日はやはり入り口でおろして、ドライバーさんだけはぐるっとという感じになると思うのですけれども、その案内がどうかというところ。","respondent":"提坂戸籍住民課長","answer":"基本的には健康な方については駐車場のほうから、３０ｍ歩く形でご協力いただきたいところなのですが、雨天の場合とかそういう場合もありますので、その辺は誘導員が常時おりますので、その辺の指示に従って移動していただければと思います。","voiceIndex":22,"id":"exchange-003"},{"speaker":"伊藤副委員長","kind":"質問","question":"１つだけ。人道橋を渡ってくるコースはいいのですけれども、自転車の駐輪場があるのはご存じですか、なぎさ会館のすぐ脇に。言っている意味わかりますかね。ですから、１つのアイデアですけれども、自転車の駐輪場を少し移転していただければ、今、各委員がお話されたように裏から入ることなく、脇を通って正面から入れるルートが確保できるわけです。そういうことはご検討されなかったのですか。","respondent":"提坂戸籍住民課長","answer":"今、なぎさ会館の建物の裏側に駐輪場があるかと思うのですけれども、それを若干左のほうに移設をする予定です。それで、通行の妨げにならないように配慮いたしまして、それで正面玄関から入っていただくことは十分可能です。","voiceIndex":24,"id":"exchange-004"},{"speaker":"伊藤副委員長","kind":"質問","question":"私の話は、自転車の駐輪場をこの間だけどこかに移設をすれば、わざわざ裏口から行く必要ないでしょうという指摘をさせていただいているのです。人道橋を渡って、車からおりた方が、もし自転車の駐輪場を移設できれば、脇を通って正面から入ることはできますよね。そういうことを検討されなかったのですかということをお聞きしたい。","respondent":"提坂戸籍住民課長","answer":"河川下水道課のほうでもいろいろ検討は重ねているとは思うのですが、スペースの関係で裏に駐輪場をつくるしかないということで検討に至ったと思います。","voiceIndex":28,"id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"確認ですけれども、先ほどのガードマンという、警備の方、通常は１人だったかなと思うのですが、そうなると、これだけＳ字になるということは、箇所、箇所に必要かなと。どのようにガードマンの配置はお考えですか。","respondent":"提坂戸籍住民課長","answer":"ガードマンについては６名配置する予定です。時間的には、お通夜がある日については８時半から夜の１０時まで、お通夜とかない場合は朝８時半から５時まで配置する予定です。","voiceIndex":30,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"十分に配置をくださるということで、葬儀のあるときはわかるのですが、ないときもこの人数という形になるのですか。","respondent":"提坂戸籍住民課長","answer":"日中については車の出入りがあることを想定しております。基本的には６名配置すると聞いてあります。","voiceIndex":32,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"通常はこの会館を使われる方のみ、この駐車場を使われるわけですね。ということは、葬儀がないのに出入りがあるというのはどういうあれですか。","respondent":"提坂戸籍住民課長","answer":"基本的に葬儀社とか、その辺の出入りとかもあるようには聞いておりますけれども、万全の体制を組むようにとは聞いてあります。","voiceIndex":34,"id":"exchange-008"}]},{"id":"topic-02","title":"────────────────────────────────────── (3) 品川区観光振興協議会および品川区観光フォーラムについて 次に","agenda":"────────────────────────────────────── (3) 品川区観光振興協議会および品川区観光フォーラムについて 次に","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"もう一回教えていただきたいのですけれども、位置づけというのですか、品川区は都市部なので都市型観光を推進していかなければいけない。以前にあった品川区都市型観光アクションプランでしたか、あれが平成２７年度で終わって、それにかわるものというのが何に、確認ですけれども、何になったのか。必要なのです。","respondent":"鈴木文化観光課長","answer":"それと、先ほど、観光振興協議会の中心をしながわ観光協会が担うということでありますので、各観光事業者や関係団体の調整もしながわ観光協会が基本的には担っていただく予定です。","voiceIndex":42,"id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひ、それぞれの役割を明確にして、区民の方が見てもわかる、そもそも区民がしながわ観光協会があるということ自体、それを知っているかどうかというのは定かではない部分があるので、そこはしっかり明確にしていただきたいということと、スケジュールは基本的に年度で、来年の３月末が一つの年度区切りで、計画があって、中間報告があって、年度報告という形になるのですけれども。","respondent":"鈴木文化観光課長","answer":"前半５年間のオリンピック・パラリンピック東京大会に向けてのことと、それから後半５年のオリンピック・パラリンピック東京大会以降のことについても、区の観光ということで継続して取り組んでまいりますので。","voiceIndex":44,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"できて２年かそのぐらいしかたっていないと思うのですけれども、なぜこの方にという思いがあって質問しようと思ったのですけれども、裏を見たら立教大学観光学部教授を、伝統ある観光に関しても立教大学のということで今納得したのですけれども、その辺についてお伺いしたいのと、それから、オリンピック・パラリンピック準備課長にお伺いしたいのですけれども、ここで観光振興協議会についても。","respondent":"鈴木文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"２点目の観光フォーラムですが、このフォーラムはご案内を差し上げておりますのは、先ほど申し上げました観光振興協議会と同様に区内の観光事業者。ご質問の品川区観光政策全般にかかわります、私、オリンピック・パラリンピックを担当する準備課長としての立ち位置ですが、こちらの資料の４番のスケジュールにあります都市型観光プラン推進本部の中の事務局ということで。","voiceIndex":46,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"安心しました。ぜひ、品川区の都市型観光という意味においても安全という意味で入っていただきたい。警視庁とつないでいただきたいという思いがあるのですけれども、その辺においては、安全・安心という意味で、その辺についてはいかがでしょうか。","respondent":"鈴木文化観光課長","answer":"警視庁との関連または連携ですが、実は先ほどご説明しました秋の観光フェアですが、このときにも観光で来ていただくためには安全なまちというアピールも必要ということで、警視庁と、消防庁、自衛隊、それぞれブースを出していただいて。","voiceIndex":49,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区観光振興協議会、ここが中枢だというお話がありましたけれども、区の要綱でつくるということなので、民間の団体というよりも会議体ということになるのでしょうか。組織図というのですか、あと、参加されるのは事業者というお話がありましたけれども、区内のホテルから、さまざま観光に携わる事業者だとは思うのですけれども、どういうメンバーなのか、少し補足をしていただきたいと思います。","respondent":"鈴木文化観光課長","answer":"ただ、実際に当日集まっていただいた方は主に各団体、事業者の代表の方です。この後、実際に設置します部会のほうでは実務レベルの方にお集まりいただいて、検討するという組織構成になっているものです。","voiceIndex":51,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"観光プランで人を呼び込むこと、見せることとかはすごく大事だとは思うのですけれども、先ほども安全面の話が出たのですけれども、有害図書とか、そういうことの話し合いというのはこういう観光協会の中でも話されたりするのですか。","respondent":"鈴木文化観光課長","answer":"それが区の施策で具体的な対応が必要な場合には、先ほど申し上げました都市型観光プラン推進本部で所管する部に伝えまして連携をするということで考えております。","voiceIndex":53,"id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"確認","question":"何点か確認したいのですけれども、品川区都市型観光プランを先にやって、その中で観光アクションプランがあって、アクションプランに続けて観光振興協議会と理解したのですけれども、多分それで正しいと思うのですが、それで、観光振興協議会の中にマスコミ関係の方をなぜ入れなかったのかなという思いが一つあるのです。","respondent":"鈴木文化観光課長","answer":"坂井市の例でありますような専門的な方を招いて観光振興をしっかりですが、品川区の場合は、先ほど申し上げました観光振興協議会に副会長ということで先ほどの安島先生にご就任いただきまして、観光振興協議会の中心的なところでいろいろな専門的な知見やアドバイスをいただいて。","voiceIndex":56,"id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"これだけの人材をそろえて、しかも大学教授も副会長になっていただいたからには、ここからそういうすばらしいヒット作をつくっていただきたいなという切なる願いがあるので、そういう中で私としては、副会長の教授の先生もすばらしいとは思うのですけれども、民間のキャッチコピー会社というのかな、そういうところの方を招聘するなり。","respondent":"鈴木文化観光課長","answer":"この冊子につきましては区内に居住していらっしゃるプロのイラストレーターとか、カメラマンとか、編集者の方、そういう方に編集員をやっていただいて、これから具体的にご指摘のあったようなキャラクターだとか。","voiceIndex":58,"id":"exchange-016"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"ケーブルテレビを軽視するわけではないのです。それは入っていただきたいのだけれども、さまざまなマスコミ媒体があるわけですけれども、ぜひ取材をしていただいて、さまざまなマスコミ媒体に載せていただいて、品川区はこういうことをやっていくということを宣伝することも観光の一環ですから、ぜひ検討してください。よろしくお願いします。","respondent":"鈴木文化観光課長","answer":"マスコミへの情報提供を使ってのＰＲ、ご指摘のとおりです。実はこの間の観光振興協議会、それから今度の観光フォーラム、そして秋の観光フェアも、区の広報と連携をして取材等の対応でのマスコミへの情報発信もしっかりと続けていきたいと考えております。","voiceIndex":60,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今いろいろご答弁を聞いていたのですけれども、おそらく通常の観光における概念というのがあると思うのです。観光はこうだという。そういう部分をもっと幅広く考えて、１足す１が２の観光ではだめだと思うので、１足す１が３になるという観光でないと多分、人は寄ってこないと思いますので、その辺は本当に幅を広げて取り組んでいただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-018"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"今日、調査項目が決まって、これから議論をしていこうというところなので、私も含めてそれぞれがどこで、どんな問題意識があるのかよくわからない部分があるので、今日のところはそれぞれの問題意識、今日出し合うのもあれだけれども、次回以降でもそれぞれの問題意識を出し合うことから議論を進めたらいいのかなと思うので、今日は示されただけなので、私もよく深めたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"提案","question":"先ほど話をさせていただいた福井県坂井市で全国シティプロモーションサミットというのが１０月２６日と２７日に開かれます。濱野区長も実はパネラーとして参加するのです。だから、決まっているわけではないですけれども、案として話をするわけであって、これは区民委員会のちょうど調査事項に合致するので、検討してみたらいかがでしょうかという提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"去年、私、総務委員会でシティープロモーションだったので、区民委員会のほうで大丈夫なのかな。ただ、テーマそのものが私の手元にないのであれですけれども、それも踏まえた案なのかなと思いますけれども、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"これからいろいろ考えていく上で、うちのこの委員会には２人の部長がいらっしゃって、観光・文化系と、地域振興と。だって、視察に行ったときに部長の質問とかがあるから、その辺は伺ってしまって、委員長、もしよければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"どこというのはまだ具体的に私もないのですけれども、中小企業支援については、うちの会派としても今回、所管事務調査にいいなと思っていたので、区としてもたしかプレスのあれの中にも再構築という観点であったかなと思うのと、中小企業支援のいろいろな角度の支援があるではないですか。そんな角度でお願いしたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-023"},{"speaker":"いながわ委員","kind":"提案","question":"提案というかあれですけれども、とりあえず調査項目が２つに決まって、それに際しての多分行政視察になると思うので、先ほど委員長がおっしゃったようにこれからこの詳細が出て、７月４日までに提出ということなので、それを見た中で、次の委員会で具体的にというふうにうまく進めていったらいいのではないかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-024"}]},{"id":"topic-04","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"資料、ありがとうございました。補足しますと、質問の中で私の反対討論が引用されて、区長の答弁もここが念頭にあったと私は思っているのですけれども、私はこの強制性について前文と第３条の「活動するよう」という、ここを根拠に主張したのですけれども、区の自主性は担保されているという説明が第４条と第５条ということで、この関係がよくわからなかったので改めてご説明いただきたいということです。","respondent":"伊崎地域活動課長","answer":"ここで、町会、自治会の自主的団体としての位置づけを明確化をしています。続いて、第５条で、区の責務といたしまして、第１項で「区長は、町会および自治会と協働し、地域コミュニティの活性化に資する施策を総合的に策定し、実施しなければならない。","voiceIndex":84,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、問題はこの条例の目的なのです。前回、第３条について概要説明のところで聞いたときに、課長は区民の方に参加の協力を求めるというご説明がありましたけれども、第３条の「活動するよう」とは参加の協力を求めるという、要するに区民に要望するという意味なのか、「活動をする」ですから私は、参加と行動の強制だと私は思っているのですけれども、条文に添ってご説明いただきたいと思います。","respondent":"伊崎地域活動課長","answer":"ただいまご指摘いただきました第３条ですけれども、第３条の(1)の「活動するよう」というところの文理解釈の問題だと今、承りました。","voiceIndex":88,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、そこを改めて伺いたいのと、そうであれば区民への要望、「区民に求めます」というふうにすればよかったのが、何で「活動するよう」という希望、要望としたのかよくわからないので、私が言いたいのはそこに、条例ですから、区長の考えでどちらにもとれる「活動をするよう」なのか、「活動を希望する」なのか、そこに曖昧さが。","respondent":"伊崎地域活動課長","answer":"ですので、今、日本語としての助動詞の意味合いについてのご説明をし、そこからこの条例についての意味を述べさせていただいたものです。","voiceIndex":90,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"２つ目の質問が、担保と言いながら客観的な守らなければならない、妨げてはならないではなくて、区長の主体的な尊重としたのはなぜなのか、ここにもまたどちらにもとれることが可能な余地を残す、つくった方には失礼だけれども曖昧性が残る文章ではないかと思うのですけれども、その点も伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日のやりとりでも、やはり文章上の曖昧性を私は感じますし、自主性を損なう余地、解釈によってはありうる余地があるのだと思います。ただ、区長が本会議で自主性は担保されていると答弁したことは、これはとても重いことだと思いますので、自主性をしっかりと活かしていただきたいと、意見だけ述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-029"},{"speaker":"いながわ委員","kind":"質問・要望","question":"まだできて間もないので、私も町会の一役員ですけれども、まだそういう話も出ていないですし、逆に言えばマンションとかも入りやすくなったという話もちらっと聞いたりはしているので、これがしっかりと運用されるように、今後もしっかりとやっていただきたいという意見というか、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"確認","question":"私も１点だけ。この条例は４月１日から施行されています。確認したいのが、この条例が施行されたことによって、町会の自主性や主体性が阻害されたと言ったらいいかな、中塚委員がおっしゃったようなことがあったのでしょうか。私はないと思う。私は、いながわ委員がおっしゃったように、これに基づいて町会はより主体的に動きやすくなったと思うのだけれども、その確認だけお願いします。","respondent":"伊崎地域活動課長","answer":"今おっしゃられたとおり、これからどのような活動の支援の、具体策をまだお示ししたばかりですので、どのように活用されて、町会、自治会が主体的に加入促進などをはじめ、活動の活性化を行っていくかということは、区としても支援をしてまいりたいと考えております。","voiceIndex":97,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2756#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":26064,"voices":106}},{"id":"h28-20160628-7","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"厚生委員会","time":"午前１０時００分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに(1)、平成２７年度介護保険制度の運営状況","agenda":"はじめに(1)、平成２７年度介護保険制度の運営状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何点かお聞かせいただきたいと思います。３ページの介護予防ケアマネジメントでは９７人で、後の１２ページの７、総合事業の実施状況のところで、介護予防ケアマネジメントで事業対象者が５６３人となっているのですけれども、これが総合事業対象者、つまり、認定を受けずにチェックリストで要支援１、２相当ということで判断をされた方なのか、そのことをお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"総合事業の対象者ですけれども、要支援１、２に相当する方のほか、認定されていなくても、基本チェックリストをしたときに、その事業の対象がふさわしいと判定された方となっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、要支援１、２相当になった方が総合事業になっていくのかと思ったのですけれども、これを見ると、介護予防の事業で、かなり自立の方も含まれての総合事業ということになっているわけですね。そしてまた、訪問型、通所型、この部分だけが要支援相当でなければ受けられないという考え方になるのか、そこのところを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"そろそろ弱くなってきたとか、このままの状態でいったら本当に要支援とか要介護になりそうだと思われる方につきましては、総合事業のサービスのほうにケアマネージャーが振り分けるという方法になっております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それだけのサービスを受ける総合事業対象者、結局、要支援１、２相当ということですよね、その方は３ページに書かれている介護予防、ケアマネジメントの９７人ということで考えていいのか、教えていただきたい。それから、認定は希望すれば受けられるということは、相談に見えた方全員に説明されているのかどうかについても、先ほどお聞きしたのですけれども、お願いします。","respondent":"永尾高齢者福祉課長","answer":"希望すれば認定を受けられるかどうか、ということですけれども、もちろんまず第一に状態像を見るのですけれども、ご本人、ご家族が認定を受けたいということであれば、それは拒まずに、また、制度も変わっておりますので、その内容も含めて、説明を丁寧に行っているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。それから、認定は、受けたいと言ってきた人は受けられるというのではなくて、全ての方が希望すれば受けられるという説明は、ぜひ、していただきたいと思いますので、そのことはもう１回お願いしたいと思います。そういう中で、特定施設がどんどん増えていることに対して、区としてはどう考えられているのかについて、お聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"今までは特別養護老人ホームのみだったのですが、今度どんどん民間が出てきて、有料老人ホーム等ができておりまして、様々な形態で高齢者の生活を支えることは大事なことだと認識しています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７９.２％ということで、単純に割り返すと２,５６０人くらいの方が滞納となるのかと思うのですけれども、どういう実態で滞納になっているのか、区としては把握されていたら教えていただきたい。この中には本当に生活が大変で滞納している、国民健康保険にしても、そういう実態がすごく多いですから、そういうところでは他の生活福祉課などと連携をとっているのかについてもお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"実際に滞納されている方の実態になりますけれども、年金をもらっているのですけれども、金額が少ないという方が一番難しいかと考えています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に１１ページで、歳入、歳出となっていますけれども、地域支援事業が５.９％ということですけれども、地域支援事業が総合事業になったとしても、多分上限が設けられると思いますけれども、何％くらいまで上限として大丈夫なのか、また、その考え方も合わせてお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"地域支援事業につきましては、今回の制度改正で考え方が変わりまして、これまでは３％上限などという形になっていましたけれども、そういう考え方ではなくて、事業を始める前の予防給付の額に高齢者の伸びを掛けたものに変更になりました。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、今回は５.９％になっていますけれども、キャパシティとしてどこら辺まで地域支援事業の中に含めていくのかというあたりを、わかったら教えてください。","respondent":"永尾高齢者福祉課長","answer":"上限は、そういうふうな仕組みにはなっているのですけれども、ただ、これも介護保険財政になってきますので、全体の総金額を見据えながら、どこまでが適正かということを考えていかなければいけないと思っています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問","question":"１点だけですけれども、６ページの地域密着型サービスの利用実績の中で、1)、2)の認知症関連のところの予防の件数が非常に少ないということで、2)はずっとゼロなのですけれども、それぞれの事業内容と、なかなか件数が伸びない理由等がわかれば、教えてください。","respondent":"永尾高齢者福祉課長","answer":"1)認知症対応型通所介護ですけれども、こちらの予防につきましては、要支援１、２の方となると、要支援２の方は厳しいかもしれませんけれども、要支援１の方の場合だとそこまで進んでいない方が多いと思います。","voiceIndex":21,"id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"2)については何となくわかりました。今の高齢者福祉課長の答弁でも、そうでもないというお話なので、そこら辺が何となくぴんと来ない。認知症に対応するいろいろな施策はやられているので、そちらのほうでいいということなのか。これがあまり必要なければ、これはどうなのだろうと思いますし、そこら辺がよくわからないので、もう１回、お願いします。","respondent":"永尾高齢者福祉課長","answer":"認知症対応型通所介護の事業ですけれども、実際に一定程度認知症が進んでおりまして、その方のデイというイメージになっております。認知症のまだ軽い方につきましては、一般介護予防事業等を利用することをお勧めしています。","voiceIndex":23,"id":"exchange-009"},{"speaker":"安藤副委員長","kind":"質問","question":"幾つかお伺いします。それから、１０ページの介護保険料の特例減額という制度で、２９件ということでしたけれども、対象の方が第３段階、第４段階ということで、少ないのではないか、対象となる方はもっといらっしゃるのではないかという印象があるのですけれども、これは本人の申請によるものなのでしょうか、そこら辺をお伺いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"苦情のことですけれども、１３件ということで、苦情とカウントする中身ですが、制度の説明とか、制度のことでわからないなどということは件数には入っていません。","voiceIndex":26,"id":"exchange-010"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"最後のところは、様々ある中では、それほどでもないものまで様々ということなのですけれども、利用料が高くて、施設もそれほどでもないというところを選ぶ人はいないと思うのです。それから、２９件という数字ですが、区としては、もう少しいるのではないかと考えているのか、そこら辺について、少ないのではないか、多いのではないかというところも含めて、お考えをお伺いしたいと思います。これは意見です。","respondent":"永尾高齢者福祉課長","answer":"苦情の関係ですけれども、確かに区民の方のそういうお声を聞くことによって、事業者のほうのサービスや区の説明の仕方とか、福祉法人等の対応など、そういういろいろな部分で参考になることは多いかと考えています。","voiceIndex":28,"id":"exchange-011"}]},{"id":"topic-02","title":"平塚シルバーセンター跡の施設整備","agenda":"平塚シルバーセンター跡の施設整備","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここはもともとシルバーセンターだったわけですけれども、地域の方からは、シルバーセンターと同じような機能をつけてほしいというご要望が出ているということですけれども、１階は、高齢者が集えて介護予防にも資する場ということで、具体的にどんな状況になるのかということ。それから、２階建てということですけれども、ここは２階までしか建てられないところなのか、そのことについてもお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"２点目ですけれども、施設の性格ですが、昨日の住民による通称サービスのような形にするかどうか等につきまして、どういったものに位置づけていくのか、どういう事業がここで展開したほうがよろしいのかということについても、今後、検討したうえで決めていきたいと考えています。","voiceIndex":35,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"シルバーセンターという名称ではなくても、どういうものにしていくかということは、これから地域の方と検討していくということですので、ぜひ、地域の方の要望に沿った形で、使えるようにということでお願いしておきたいと思います。２階建てということでは、そういうことで地域に配慮したということで、それはそれでとても大事なことだと思います。","respondent":"松山高齢者地域支援課長","answer":"住民主体の通所サービスのことですけれども、昨日の大崎ゆうゆう地域ミニデイのモデル事業のモデルを検討して、区内展開を図るという方向ですので、こちらにつきましても、その可能性は探っていきたいと考えています。","voiceIndex":37,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"何点か教えていただきたいと思います。２階にオアシスルーム、ポップンルームということで計画をするということですけれども、たしか、オアシスルームは今８カ所くらいあったかと思いますけれども、ポップンルームも荏原保育園でやっているのですね、わかりました。当然、交通を遮断するというようなタイミングがあるかと思いますので、その点をお聞かせいただければと思います。","respondent":"松山高齢者地域支援課長","answer":"ご指摘のとおり、確かに前面道路が４ｍないところや、道路が直線でないということで、道路事情等、近隣の方にかなりご迷惑をおかけするようなこともあるかと思いますが、十分に業者と連携を取りまして、安全に、また騒音、あるいはほこり等。","voiceIndex":39,"id":"exchange-014"}]},{"id":"topic-03","title":"ロタウイルスワクチン任意予防接種費用の一部助成","agenda":"ロタウイルスワクチン任意予防接種費用の一部助成","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"ロタウイルスワクチンの予防は、私どもの会派には専門家がいらっしゃって、こだわりの要望だったことに区のほうも応えていただいたということで、大変ありがたく思っています。本日はこの資料の書き方なのですが、これを対象者が見たときに、あるいは同様のものを見たときに、少し交通整理が必要なのではないかと懸念するところですが、その辺の考え方を教えてください。","respondent":"舟木保健予防課長","answer":"そこは、こちらのほうも契約医療機関のほうにご説明いたしまして、そのような形で進めさせていただきたいと考えています。事業を進めながら、よりわかりやすく、改善していくところはしていきたいと考えています。","voiceIndex":46,"id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後にお願いになります。いざスタートして、どうしても口頭ベースの説明は必要なのですが、ガイドライン的なものというか、ドクターによっても説明の仕方はニュアンスの違いがあると思いますし、ここはぜひとも保健所のリーダーシップで、マニュアルというか、ガイドラインのわかりやすさを求めた展開が必要な気がしました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今の渡辺委員の質問に関連して、もう少し詳しく教えていただきたいのですが、１価ワクチンのほうは２回接種ということで、我々のイメージだと、１回約１万５,０００円で、大体半額くらいが助成される。","respondent":"舟木保健予防課長","answer":"単価につきましては、医療機関によって異なるのですが、調査いたしましたところ、１価ワクチンにつきましては、大体１万２,０００円か１万８,０００円の間で平均的に１万５,０００円弱くらいかと、こちらのほうの調査の結果で出てまいりました。","voiceIndex":49,"id":"exchange-017"},{"speaker":"たけうち委員","kind":"提案","question":"よくわかりました。多分お母さんたちは、私たちより詳しいのだと思うのですけれども、いろいろなお問い合わせがあると思いますけれども、先ほど、渡辺委員からもありましたけれども、我々の会派としても提案してきたので、混乱のないようにぜひお願いしたいと要望して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどご説明の中で、接種率を向上させることによって疾病の予防を図るとありましたけれども、接種率がどのくらいになっているのか、わかったら教えていただきたい。それから、２３区の状況をネットで見たところでは、渋谷区では８,５００円を２回まで助成しているということはあったのですけれども、それ以外のところで、２３区の助成の状況がわかったら教えていただきたいと思います。","respondent":"舟木保健予防課長","answer":"中野区が今年度から始めていると聞いておりまして、こちらのほうは６,０００円１回という形で聞いております。ロタワクチンにつきましては、国のほうも、今、検討を進めているところですが、定期化するにあたっては課題が幾つか挙がっております。","voiceIndex":52,"id":"exchange-019"},{"speaker":"松永委員","kind":"確認","question":"少し確認でお伺いしたいのですが、先ほどの質問の中にあったように、契約医療機関によって金額が異なるということですけれども、ワクチンは全く一緒のものなのか、それとも扱っている機関によって種類が変わってくるのか、メーカーが違うのか、その辺の確認をお願いしたいと思います。","respondent":"舟木保健予防課長","answer":"予防接種につきましては、保険診療ではありませんので、値段の設定は医療機関ごとの設定となっておりますので、そこの部分で、どうしても接種費用に差が出てしまうことになっております。","voiceIndex":54,"id":"exchange-020"}]},{"id":"topic-04","title":"の３、行政視察","agenda":"の３、行政視察","exchanges":[{"speaker":"たけうち委員","kind":"提案","question":"私たちが興味を持っているのは、ここでは、全部のサポートセンターではないのですけれども、数カ所に高齢者向けの住宅を併設させているという取り組みをしています。それも佛子園の一つの事業形態になっているのですけれども、そういった面で、佛子園の地域包括、全世代、全対象型というのと、先ほどの長岡市の取り組みを見てみたいと思っており、提案します。","respondent":"渡部委員長","answer":"たまたまなのですが、今のたけうち委員からご発言があった、シェア金沢、こちらはオープン間もない中でかなり注目されているということが、調べたら出てきて、今のお話とかぶりますが、障害児入所施設、そしてその就労支援等、そしてまた高齢者デイサービスを加えて。","voiceIndex":61,"id":"exchange-021"},{"speaker":"松永委員","kind":"意見","question":"皆様ご存じのように、長野県が長寿であって、平均寿命も長いということで、どういった取り組みをされているのか、もう少し詳しく知りたいということがありまして、一番が長野県松川村というところで、それから塩尻市、諏訪市という形になっているのです。その辺を詳しく勉強したいということであります。委員長、副委員長に任せます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回の所管事務調査の中に障害者のことが入っていないので、今年は障害者権利条約が批准して２年で、報告を出したり、差別解消法の実施や総合支援法の改定などということで、節目の年でもあると思いますので、所管事務調査の中に入らないのであれば、視察の中で障害者施設を入れていただいて、そこを深めていただくということで検討いただけたらと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3450#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":29102,"voices":72}},{"id":"h28-20160628-8","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"建設委員会","time":"午前１０時００分～午前１１時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"補助１８号線に係る土地収用に関する損失補償請求事件","agenda":"補助１８号線に係る土地収用に関する損失補償請求事件","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"もともとの、東京都収用委員会の確定した数字というのは幾らぐらいだったのかというのが、まず１点お聞きしたいと思います。それともう１点、こういう訴訟に至ったというのは、決定したのは平成２２年ですけれども、いつ頃からこういう折衝をしたことによって、この当初の金額が確定したのか、まずその２点を教えてください。","respondent":"矢木用地担当課長","answer":"こちらにつきましては、平成３年１１月２８日に事業認可の告示がございまして、具体的には、原告と交渉をしたのは、平成１０年の１２月から交渉開始しておりました。そして、平成２２年３月に収用認可の採決が出ているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"金額等、わかりました。場所も大体、見当がついたのですけれども、この場所は、もう道路は広がっているのですよね、確か。平成１０年から長年にわたって折衝を進めていっていただいて、区としての対応は随分尽くしたのだと思うのですが、その辺、折衝状況をもうちょっと教えていただければと、お願いいたします。","respondent":"矢木用地担当課長","answer":"ただし、原告といたしましては、マンションの前面にあります駐車場５台分の替地というところで、非常に主張してございまして、ここの替地という交渉、希望地を、こちらの品川区といたしましても交渉したのですが、そこの場はちょっと不調になったということで。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然区としては、十分に対応を尽くして、丁寧に対応していただいたと思います。何が言いたいかというと、逆に、丁寧な対応を、これから、ほかの問題、道路も絡んでくると思うので、十分な対応をしていただきたいなというのが１つ、今後に向けてお願いがあります。それから、収用委員会のこういう決定というのは、割合とその後、こういう訴訟などになるものなのですか。その辺がどうなのかと。","respondent":"矢木用地担当課長","answer":"収用委員会の採決後の判決ですが、平成１３年から、ちょっと私ども、データをとってみたのですが、その中では、正直言って、１件、２件、３件ぐらい、マックスでも３件程度の収用裁決がありますが、それは何百という地権者の方の中でそのぐらいの割合で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺、繰り返しになってしまうけれども、やはり丁寧な対応をしていただいたと思うこのケース、それでもこんな結果になってしまったと思うので、今後に向けて、区としてやはり丁寧な、所有者に対して、しっかり納得していただいた上で、納得いくような収用、収用に行く前ですね、売却を求めていくような形をとってもらいたいと思いますので、これは要望で終わらせますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"都市計画道路事業のための土地収用で、損失補償額の変更を求めるということで訴えられたということなのですけれども、訴えたことで、なぜ品川区が払わなければいけないことになるのかというのがちょっとわからないので、教えていただけますか。","respondent":"矢木用地担当課長、安井土木管理課長","answer":"こちらは、私どももあらゆる主張をしたわけですが、裁判所が客観的事実に基づいて、被告・原告双方の主張に基づいて判断したところ、一部、考え方の違いと申しましょうか、が出て、追加補償という形になったものです。補足しますけれども、これは、品川区が都市計画道路補助１８号線の整備を進めるということで、区施工の都市計画道路で整備したものですので、品川区が被告として登場したという形になっているものです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"４,５９２万円という、すごく大きいですよね、金額が。実際は、大分なくなっているのですけれども。これは、原告のほうの独自の算定でこういうことを言ってきているのかということ。それで実際は、この裁判にかけることで、きちんといろいろな算定の中で、こういう金額に結果的になったのだと思うのですけれども、あまりにもこの大きい差があるので、この金額の差はどこから来る差なのでしょうか。","respondent":"矢木用地担当課長","answer":"こちらの差額の大部分につきましては、用地の単価、こちらのほうが、区主張が１５９万５,０００円でありましたが、原告のほうが１８８万９,０００円ということで、約３０万円近くの差額があり、というのが大きなところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"意見","question":"わかりました。もともと、都市計画道路というのが決まっているものなので、その差が幾らあったとしても、ではもう返してねというのが都市計画道路なので、その中でこういう裁判をやられてしまうということは、ちょっと何でしょうという、とても不思議な感じで。なおかつ、こういう裁判をかけるというのは、主張するというのは、どうしてそういうふうになっているのかなと思うのですが、わかる範囲で。","respondent":"矢木用地担当課長","answer":"その後、平成３年になりまして、いよいよ告示ということで、計画決定してという話の中では、当然のことながら、ここは計画地であるということは認識があったということは確認しています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"いろいろな事情があってということなのでしょうけれども、ただ、区の立場としては、やはりここは、都市計画道路として指定されているということは、もう十分言っていいのだと思うのですよね。公共としてしっかり主張してもいいところなのではないかなと思うのですが、いかがでしょうか。","respondent":"矢木用地担当課長","answer":"委員ご指摘のとおり、こちら、都市計画道路ということで主張してまいりまして、裁判でも、実質上勝訴ということで、公にも認められているところです。今後も、こちらの主張は従前どおり主張してまいりたいと考えております。","voiceIndex":19,"id":"exchange-008"}]},{"id":"topic-02","title":"しながわ区民公園中央ゾーン改修工事等","agenda":"しながわ区民公園中央ゾーン改修工事等","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"３番の今後のスケジュールのところで、黒丸を始点とする線があって年度末までとあるのですけれども、この始まりというのは、大体何月ぐらいなのかを、それぞれ伺いたいのと。キャンプ場は、老朽化した施設を更新するということですけれども、使える形で更新されるのでしょうか。","respondent":"溝口公園課長","answer":"そのほかの3)、4)、ここについては、９月頃から工事に着手していきたいというふうに考えております。キャンプ場につきましては、一旦閉鎖させていただいて、今もう既に周知しているところですが、９月の初めから今年度いっぱいは使用中止という形で周知をしています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、ここは９月から閉鎖という形になるのですね。それで、キャンプ場を新たにしていくというところでは、今、手ぶらでキャンプみたいなものも言われていますけれども、そういった、いろいろな方が便利に使いやすいキャンプ場にしていくという考えはあるのでしょうか。","respondent":"溝口公園課長","answer":"キャンプ場の利用につきましては、今後いろいろよく聞きながら、また利用実態等を踏まえながら、様々な利用者の利便性の向上、または利用してもらえるキャンプ場になるように考えていきたいというふうに考えているものです。","voiceIndex":27,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"この、しながわ区民公園ですけれども、多くの障害者の方も利用していると思うのですけれども、園路のところでは、利用者の円滑な通行と、ということで書かれているのですけれども、バリアフリーの面でいうと、トイレだったりとか、そういったところ、バリアフリーの面はどんな感じに…。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうですね、どんな配慮がされるのか、あれば、教えてください。","respondent":"溝口公園課長","answer":"身障者対応として、今まで、障害者用のトイレはあったのですけれども、だれでもトイレが設置されていなかったので、今回この管理棟の中に、そういっただれでもトイレを設置することによって、バリアフリー対応にしていきたいというふうに考えております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今、石田委員のお話のキャンプ場の話なのですけれども、年間、通年通して、いろいろ区民の憩いの場になっていると思うのですが、少年野球だったり、それぞれ様々な団体が楽しまれている中で、９月から１２月まで閉鎖ということで、これは老朽化ということで整備していただくのは結構なのですけれども、今、キャンプ場、既存の釜が、すみません、何基あるかちょっとわからないのですけれども。","respondent":"溝口公園課長","answer":"ちょっと説明が悪くてですね、キャンプ場の閉鎖期間なのですけれども、９月から来年の３月いっぱいまでを予定しているものです。今回、キャンプ場につきましては１５基の釜がありまして、整備後も同じように１５基整備するものです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"この売店というのは、どういう売店、規模を考えているのでしょうか。もうちょっと楽しめる売店があったらいいなと思うのですけれども。それと、あと保育園になりますけれども、この区分けというのは、きちんと分かれてと言いますか、公園の中に保育園ができますけれども、公園との境目というか、それはきちんと切り離した形で建設はされるのでしょうか。","respondent":"溝口公園課長","answer":"ただ、運営につきましては、どういう形、また、せっかく中央広場の中に集約するという形になっておりますので、今後、整備していく中で、どういった形での運営をしていくのか、どういったものを品揃えしていくのか、そういったものを含めて、しっかり考えた上で、来年の４月には。","voiceIndex":35,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"保育のほうは所管のほうと整備を。結構、広くて、素敵な感じはするのですけれども、公園の中に保育園があるというのは。でも、その反面、危険性も伴ってきますので、それはいろいろ調整を図っていただきたいと思います。ちょっと、食のことを含めて、何かこの辺工夫ができるといいなと思うのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"今回、売店は今の状態でいいとは思っておりませんので、どういう形でのサービスを提供していくのか、それはしっかりと検討していきたいと思います。","voiceIndex":37,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"この工事の改修計画で、プレイパークというものが出ていますけれども、計画平面図でいくと子育て支援事業ということで、プレイパークというもの、これは品川区内、確か２カ所目というふうに聞いていますが、どういうものかということを１点お聞きするのと。今回、ここにプレイパークをつくるということになった、これまでの経緯も、ちょっと簡単にご説明いただきたいと思います。","respondent":"溝口公園課長","answer":"これまでも、いろいろ、プレイパークの設置について、所管である子ども育成課、そういったところからお話がある中で、今回、整備をしていく過程の中で、ここであればそういったものができるのではないか、そういったことの経緯も踏まえて、今回、スペースといいますか。","voiceIndex":39,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"今ので言うと、何も置かないと、いわゆる広場であれば、そこをプレイパークとして活用できるというようなお話だったかと思うのですけれども、そうすると、立地的なことを考えて、区民公園だったらいいと。そういうこととはまたちょっと違う、子育て支援事業としては、所管が違うからちょっとあれなのですけれども、立地的なことで、今回ここにということになった理由を、もうちょっと詳しくお願いします。","respondent":"松代防災まちづくり部長","answer":"本来なら所管課長が答えるべきなのですけれども、私も公園事業関係を４０年近くやっていまして、思いがありまして、ちょっとお話しします。","voiceIndex":41,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"最後にちょっと、これだけ整備された後、こちらは勝島にも近いので、人口が結構増えてくると、たくさんの方が今まで以上に来られる可能性というか、もちろんそういう思いもあって整備されるのでしょうけれども、駐輪場とか駐車場、今回の整備の範囲にはちょっと入っていないのですけれども、その辺の整備というか、キャパシティーというものが。","respondent":"溝口公園課長","answer":"自転車で来られる方、また車で来られる方、多いと思います。基本的に駐車場自体をすぐ拡幅するというのは、こういった公園として利用している部分もありますので、難しいと思います。","voiceIndex":43,"id":"exchange-018"}]},{"id":"topic-03","title":"目黒川氾濫および津波発生時の避難基準","agenda":"目黒川氾濫および津波発生時の避難基準","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"避難の対象者への避難情報の伝達方法については今後検討ということなのですけれども、避難対象者というのは、どれぐらいいるのでしょうか。","respondent":"和田河川下水道課長","answer":"まだ机上の概算ではありますけれども、今回の目黒川の避難対象、それから津波の避難対象と合わせて、１万世帯ぐらいだというふうに考えております。","voiceIndex":51,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"伝達方法については今後検討ということですけれども、やはり伝達していないと意味がない対策だし、今回の基準になってきてしまうと思うので。昨日のところでは、１軒１軒回ってというようなお話もありましたけれども、ほかに、伝達方法、配布、ポストに入れておくということなどもあると思うのですけれども、確実に伝達していくというところでは、今のところどういったところをお考えなのか、教えてください。","respondent":"和田河川下水道課長","answer":"昨日の審議の中で、１軒１軒回ってといいますのは、これから伝達を直接するために、固定電話とかメールとか携帯電話に、直接、区役所が携帯電話番号や固定電話番号をいただいて、そこに直接電話をかけて呼びかけるということを想定しているもので。","voiceIndex":55,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"津波に対する避難対象地域と、目黒川の氾濫に対する避難対象地域の案、この地図なのですけれども、まず、この赤い点線部が避難対象地域という理解でよろしいのでしょうか、ということがまず１点。この津波に対する避難対象地域の、青いところ、さらに緑色のこの部分は、これはどういった意味なのでしょうか。ちょっとこの２点をお伺いいたします。","respondent":"和田河川下水道課長","answer":"津波のほうのご指摘、ご質問ですが、右側の拡大図の中に、青色の枠と、その中に緑色のちょこっとしたものがありますけれども、先ほど私が説明した、浸水シミュレーションの結果が、この緑色、この青色の枠の中にちょこちょこっと見えます緑色の範囲。","voiceIndex":57,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"ご答弁ありがとうあります。では、この津波に対する避難対象地域の赤線も町丁目ということでよろしいのでしょうか。津波に対する避難対象地域の、このオレンジ色の太い線は、津波注意報、海抜２ｍ以下の地域ということを表わしているという理解でよろしいのでしょうか。","respondent":"和田河川下水道課長","answer":"オレンジの線ですが、右上に凡例が書いてあります。津波注意報で、海抜２ｍ以下の津波が発生した場合に、避難指示を呼びかける。先ほど、資料の２ページ目の下の、津波注意報の場合の、避難指示を呼びかける施設名と書いてある、その施設の位置を表わしたものです。","voiceIndex":59,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"意見","question":"１点だけ。目黒川の氾濫に対する避難対象地域（案）が出ていますが、これは五反田の地域になりますが、これより下流部はどういうふうに考えたらいいのか。もう大丈夫だという判断なのか。それはどういうふうに考えているのか。","respondent":"和田河川下水道課長","answer":"０.５ｍ以下でも、危ない方というのはいらっしゃると思うのですけれども、まずは危険なところを避難対象地域として発令させていただきまして、その状況を見て、下流側へも避難勧告、避難指示は判断していきたいというふうには考えてあります。","voiceIndex":61,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大体わかったのですが、場所として、居木橋あたりからずっと下流あたりは、あの辺は高いから、そういう点では大丈夫だろうと判断するということでよろしいでしょうか。","respondent":"和田河川下水道課長","answer":"そのとおりです。","voiceIndex":63,"id":"exchange-024"}]},{"id":"topic-04","title":"多摩川の洪水浸水想定区域の指定・公表","agenda":"多摩川の洪水浸水想定区域の指定・公表","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この１の(1)のところで、２日間に５８８mmの降雨があったときに多摩川が氾濫するということなのでしょうか。それ以下なら氾濫はしないということなのでしょうか。","respondent":"古巻防災課長","answer":"今回の想定に関しましては、最大規模２日間に５８８mmで、多摩川が氾濫したという想定に基づいたシミュレーションを国のほうで行ったということになりまして、それ以下で氾濫しないのかどうかというところの判断は何とも難しいところだと思いますけれども、ここで、必ず。","voiceIndex":72,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"意見","question":"先ほど説明もあったとおり、氾濫した場合に、南大井等の地域で１ｍ浸水というところでは、大変な水位だなというふうに思ったので、どれぐらいが最大なのかなというふうに思ったのですけれども、はい、わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-026"},{"speaker":"塚本委員","kind":"確認","question":"最初にちょっと確認したいのですけれども、これは、氾濫というのだと、決壊という種類もありますけれども、多摩川の水が増えると、決壊をしたということが前提で、これは考えられているわけですか。そうではなくて、この２日間で５８８mm降れば、決壊するしないにかかわらず、水があふれてくるということなのか。ちょっとお聞きしたいので、ご答弁をお願いします。","respondent":"和田河川下水道課長","answer":"したがいまして、それよりも上流に降った場合とか、下流に降った場合というのは、想定はされていないものなのですけれども、国土交通省から聞いたところによりますと、これまで、多摩川の流域に降った降雨のうち。","voiceIndex":75,"id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうすると、１つは、完全にここは決壊するというバツ印がついていますよね、シミュレーションの図で見ると。ここまで、ここが危ないというところがわかっているということは、決壊しないようにここをまず補強するという対策も、１つは考えられるのかなと思うので、そこはどうなっているのかということと。どういう状況で避難指示を出していくのかというのを、ちょっと教えていただきたいのですが。","respondent":"和田河川下水道課長","answer":"避難指示のタイミングの問題ですけれども、多摩川も、先ほど目黒川で説明したものと同様に、氾濫危険水位のときに避難勧告、それから氾濫発生水位のときに避難指示を出すということになってありますので、基本的には決壊する前に避難指示は出されるというものです。","voiceIndex":77,"id":"exchange-028"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としては、今回の所管事務調査でもお願いしました防災関係ということで。これ、被災地支援というのはどういうふうにやっているのか。福岡は確か、地元完結型とかというのが出てたというのですけれども、ちょっとそこまで詰めていないので、その辺がどうかなというのが、１点、調査できないかと思っています。日程的にも、委員会等ありますので、あとは正副にお任せする形で、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-029"},{"speaker":"筒井委員","kind":"意見","question":"具体的な都市名というのは、そこまではっきりと、曖昧な状態なのですけれども。いずれも、震災対策についても舟運についても、やはり品川区という面で、都市型の防災、都市型の観光というのを参考にしたいので、例えば名古屋市などは、南海トラフ地震対策とか、恐らく相当やられていると思いますので、都市型震災対策としては、そうした町とかがいいかなと思いますけれども。参考までに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-030"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"道路推進や整備、全体に反対なわけではないですけれども、否定するものではないですけれども、私たちこの間、一般質問等々でも示させていただいているところですので、道路大会には参加はしないということで、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":26745,"voices":107}},{"id":"h28-20160628-9","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"文教委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"小・中学生の生活状況調査の実施","agenda":"小・中学生の生活状況調査の実施","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですが、国の子供の貧困に対する大綱が平成２６年８月に決まったということで、今回、この調査が約２年たってしまった経緯を教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"しかしながら、より連携を深めないと、よい施策はというところまで来ましたので、今回、連携を深めるためにということで検討委員会を立ち上げまして、対応することになった次第です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"そうすると、これまでもそれぞれの所管でやってきたのを、今回、さらに連携をしていかなければ子どもの貧困対策というものが進んでいかないということで、今回の連絡会議でそうなったという理解でいいか、ちょっと確認です。","respondent":"廣田子ども家庭支援課長","answer":"今までも連携はしていたのですが、システマティックにやりたいということと、もう一つが貧困対策、経済状況が厳しい家庭だけではなく、経済状況が厳しい家庭を優先的にということはあるのですけれども、全児童に、品川区の子どもたちに対する施策を強化するということで。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"この調査対象が２年生と９年生になっている理由を教えていただきたいと思います。調査内容で、世帯の基本情報とあるのですけれども、この基本情報というのは何が含まれているのか教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"設問の詳細については、今、細かく詰めているところではありますが、主に質問項目の基本情報としましては、世帯の人数と生計をともにしている人、あとは世帯の収入についてもお聞きする予定です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"９年生のところは、進学についても聞いていきたいということで、国のほうでも奨学金等を検討しているみたいなのですけれども、区としても、やはりそういったところをつかみたいというところもあって、この９年生のアンケート調査をやっていくということなのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"奨学金とか、個別具体的なことではなくて、親御さんが子どもの進学をどこまで考えているかというところを実態としてつかみたいというところで考えてあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"質問","question":"こういう調査をするということに関しては非常によいことだと思うのですが、これは調査をするというところまでであって、集計は学務課ですると書いてあるのですけれども、この後、そのデータをどうやってまとめて、どのような形で報告するとか、どのような形で施策に活かすとか、その辺のことはどういうふうにお考えなのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"現在、小・中学生の生活状況の調査のご報告なのですが、全体としまして、就学援助でありますとか、生活保護でありますとか、ひとり親世帯に関して、今は行政情報を集約いたしまして、それをまとめ、現在の施策と突き合わせまして。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"どのような形で報告書を作成して、それを受けるほうはどうなのでしょうか。どこで、どのような活用方法というのか。例えばホームページでするのか、文教委員会でするのか。","respondent":"廣田子ども家庭支援課長","answer":"報告につきましては、まず議会に報告させていただきまして、検証の内容によりまして、新規の事業と拡充事業をやるとかが出ましたら、予算等に反映させなければならないので、そちらでお諮りさせていただこうと考えています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"どういう形でやるのですか。区民への周知を聞いているわけではなく、どういう形で、どういう対象にやるのですかということをお聞きしている。","respondent":"廣田子ども家庭支援課長","answer":"施策の検証ですので、まず議会に報告するということを考えてあります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"この検討委員会について少し教えてください。子どもの未来応援プロジェクト検討委員会というのは、どこの部署がかかわり合ってつくられていて、どのくらいの人数で、あと、例えば外部の専門家がいらっしゃるかどうか。この検討委員会がどのくらいのスパンで行われて、何を目指しているのか。ありていに言えば、検討委員会の概要と目的とスケジュールを教えてください。","respondent":"廣田子ども家庭支援課長","answer":"現在のところ、外部の委員を入れる予定はございません。スパンについてなのですけれども、検討委員会自体は、本年度は４回程度を予定しておりますが、その下に作業部会と調整部会というものをつくりまして、調整部会につきましては課長級が中心となって、実務者との調整。","voiceIndex":19,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"スケジュール的には、例えば何年間でこの調査の何をするとか、そういったことは決まっているのですか。それとも、調査をした後で、また考えていって、いつごろまでに何をするという、その先というのは特に考えていらっしゃらないのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"その後につきましては、行政データの洗い出しをしたときに、現在、予算取りもしていない状況で、できる限りのことをするということをやってありますので、さらに調査が必要なのかどうかも含めまして検証した中で、平成２８年度の検討委員会の検証を行った上で。","voiceIndex":21,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういった意味では、この調査を行うだけではなくて、それをベースに品川区の子どもの実態に即した全庁的な政策を１つ掲げていくようなところまで持っていっていただきたいと思うのですけれども、やはり人口の問題とか、あるいは、ひとり親とか虐待の実態ですとか、そういったことはかなり専門的な部分も入ってくると思うので、どこからかの段階では専門家の助言も入ったほうがいいのではないかと思いますが。","respondent":"廣田子ども家庭支援課長","answer":"現在、どこまでのデータが出るかというところで、今まで出なかったデータも洗い出している状態で、データを出し切った段階で、必要性を感じたところで検討をしたいと思います。","voiceIndex":23,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"区立小・中学校、義務教育学校の在籍者を対象にということなのですけれども、例えば７年生以上、中学生の３割は区立学校ではない学校に通っているわけです。区立学校の在籍者でないところにもまたこういうような問題などもあると思いますし、実態を知るという意味では、調査が難しい面もあるかもしれないですけれども、ここを最初から落とすのはぜひやめていただきたいと思うのですが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"ひとり親家庭、就学援助、生活保護というのが３点セットで、比較的、優先的に施策が必要な対象と言われているものなのですが、その対象だけのデータですと、ある一定所得以下の人というところで条件が限られてしまうので、今回、区立の小・中学校に広げて、両親がそろっていても。","voiceIndex":25,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"それは、次の段階では、何らか補足することを考えていらっしゃるということですか。それとも、実際にはやらないかもしれないということなのでしょうか。品川区の小・中学生の生活状況ではなくて、品川区の区立小・中学校在籍者の生活データというタイトルにしていかなければいけないのではないか。そうでないと、見誤るところがたくさんあるのではないかと思います。","respondent":"廣田子ども家庭支援課長","answer":"私立等の課題もあろうかと思いますけれども、ここでサンプル数には不足はないので、とりあえず、状況をこれで検証させていただき、また新たなる課題に向かうときに、方法等については検討させていただこうと考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"あべ委員","kind":"意見","question":"サンプル数に不足はないと思います。けれども、一定の属性を持った人たちがすっぽり抜けてしまうというのは、サンプルの質としてどうかと思います。今回は今回で、区立の学校で行うというのであれば、それはそれで否定するものではありませんし、これでやっていただければいいと思うのですけれども、これだけの結果をもって区内の小・中学生の実態であるということは、私は間違いだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、ひとり親家庭の児童育成手当を受けられている方への調査もされていると思うのですが、それとの兼ね合いも少し教えていただきたいのと、内容が違うのか、その点も確認をさせていただきたいと思います。何かアンケートをいただくということがもし可能であれば、調査内容も教えていただければと思うのですが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"１点目が、配付は学校で回収は郵送でということなのですが、学校で回収したほうが回収率が高いということは認識していますが、今回、収入についてもお聞きするということと、教育そのものではなくて、生活の状況を聞くということで、学校に収入について知られるのではないかと。","voiceIndex":30,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"結果については、委員会中での報告、よろしくお願いします。予算決めがこれからになる、施策をつくっていくために予算に反映させるということですが、例えばこども食堂の実施とか、また、そういうところへの補助とか、何か区としてできるイメージがありましたら、教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"現在、公に申し上げられるものはないのですけれども、検討をしながら、結果が出るまで動かないというわけではありません。","voiceIndex":32,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"２つお尋ねします。１つは、調査をする場合は、ある一定の仮説を立てて調査されると思うのですけれども、現状で、先ほどから認識している部分があると思うのですが、その中でも、このあたりはこういう認識を持っているんだけれども、この辺は、本来はどうなのかというところを調査しようと、具体的に少しわかれば、教えていただければと思います。","respondent":"廣田子ども家庭支援課長、有馬学務課長","answer":"進学についても設問を入れるのですが、進学資金について、親がどれだけ事前に準備をするであるとか、積み立ての準備をしているであるとか、どう取り組んでいるかというところを聞いて、実際に経済的な面も含めまして。そのために、我々、学務課としても、校長連絡会を通じまして、この意図というものをしっかり現場に伝わるようにということで、各校長先生にお願いをしていきたいと考えています。","voiceIndex":34,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これを今後にぜひ広げていただきたいのが１つです。率直に子どもの貧困という捉え方からしたら、就学前のところはどういうふうにされるのかと。さっき伺った、ほかに何か手だてが、いろいろあるのかもしれませんけれども、子どもという捉え方からしたら、ゼロ歳、生まれる前からかもしれませんが、ずっとつなげて調査をしていただきたいと思うのが１点です。","respondent":"廣田子ども家庭支援課長","answer":"他区につきましては、会議体を立ち上げているところが、３月の調査で十数区だったと思うのですが、他区が行った調査では、何らかの形で立ち上げているところがあると認識しています。","voiceIndex":37,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"これから実際的には課題の見える化と支援策を考えていくというところで、充実をされていくと思いますので、期待をしたいと思います。今回は調査なのですけれども、お伺いする、聞き取るだけではなくて、困ったときの相談体制などが結構あちこちあります。そういうものの発信をあわせて、簡単なものでもいいので、この中でできないかと思っているのですけれども、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"何らかの形で相談体制は処置することは大切だと思いますので、考えたいと思います。","voiceIndex":39,"id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"１点、聞き漏らしました。回収率について、どのように考えていらっしゃいますでしょうか。配付をして、郵送で戻ってくるということは、先生が集めるわけではない。それは調査の読み取りの問題にもなってくるかもしれないのですけれども、その回収率はどの程度と考えていらして、回収率を上げる努力をもし何か考えていらっしゃるなら、教えていただきたい。それについてどのようにお考えなのか教えてください。","respondent":"廣田子ども家庭支援課長","answer":"郵送にしたので、今のところの見込みとしては、６割は回収してほしいと考えています。４,１００人の６割なので、回収して６割が返ってくると２,４００人ほどになるので、サンプル数だけで言えばいいと考えています。","voiceIndex":41,"id":"exchange-019"}]},{"id":"topic-02","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今は計画段階で、変わるかもしれないということだったのですけれども、できれば、各施設の年齢別の定員を教えていただけたらと思うのですが、よろしくお願いします。","respondent":"大澤待機児童対策担当課長","answer":"このえ中延保育園、ゼロ歳児が６名、１歳児が１０名、２歳児が１２名、３、４、５歳は１４名ずつとなります。北品川一丁目保育施設につきましては、１歳児が６名、２歳児が９名、３歳以上は１５名ずつとなります。","voiceIndex":47,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"北品川一丁目保育施設は公設民営ということなのですけれども、ぜひ、会派としては公営でやっていただきたいと思って、常々言っておりますが、公営でやっていくという検討などはされたのか、伺いたいと思います。今、計画中だと思いますが、幾らぐらいになるのか教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"保育園の運営に関しましては、基本的に認可保育園は民設民営を基本としまして、それが難しい場合は公設と考えておりますので、今のところ、公設公営という考えはございません。","voiceIndex":49,"id":"exchange-021"},{"speaker":"のだて委員","kind":"意見","question":"先ほど、今後も開設の予定はあるということで、今回も４園設置されるということで、今、保育士不足が言われておりますけれども、保育士の確保等はしっかりできて、４月のところから、まだ１年近くありますが、見通しはどうなっていますか。","respondent":"大澤待機児童対策担当課長","answer":"このえ中延保育園につきましては、計画承認の前から、もう６月に入ってすぐ、見込みで保育士の募集を始めていまして、こちらも大田区に２園持ってありますので、そちらのほうの異動も含めて、品川区のほうできっちりやっていくと聞いております。","voiceIndex":51,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、４月の開園で人員が整えられるように、区のほうとしても整備をしていって、待機児童が出ないようにやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-023"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、北品川一丁目保育施設は、暫定ということでしょうか。それから、ゼロ歳児園と１歳児園があるのですけれども、どういうところでゼロ歳にして、どういうところで１歳にという、何か切り分けがあるのですか。暫定だと、５年なら１歳なのだろうと思いますが。","respondent":"大澤待機児童対策担当課長","answer":"えがおの森保育園・かつしまにつきまして１歳児というのは、いろいろ地域的なバランスですとか、事業者の考え方にもよりますので、その辺は事業者任せ、保育園の考え方にもよると考えています。","voiceIndex":54,"id":"exchange-024"},{"speaker":"あべ委員","kind":"質問・要望","question":"北品川一丁目保育施設ですけれども、暫定であるということと、それから、まだ区では公設民営はそんなに事例が多くない中で、ぜひ、運営事業者は未定ということではありますが、保育内容、運営については、しっかり契約内容を詰めていただきたいと考えています。それについて、ぜひ、抜かりのないようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２７年度から開設計画、何か今までと違ったことがあるのか、もうちょっと、そこのところを聞かせていただきたいのと、今日、ここにご報告があった保育園が、どのくらいの期間、どういう経過を経て、この発表に至っているのかを教えていただきたい。","respondent":"大澤待機児童対策担当課長","answer":"先ほどの計画承認の話ですが、１度、計画承認をとってから工事に着工いたします。","voiceIndex":57,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"工事の期間というのはそれぞれ違うと思うのですが、どのくらいかかるのかということ。まだ現地を見にいっていないので、どういう状況なのかというのを教えてください。北品川一丁目保育施設は公設民営ということなのですけれども、公設民営で開園するまでの準備にかかるお金と、あと、民設民営で支援策はあるのですが、公的に出して、お金はどのくらい差があるのか、どんな状況なのか、教えていただきたい。","respondent":"大澤待機児童対策担当課長","answer":"仮囲いをつくりまして、その中で土壌改良工事をしておりますので、その後に、８月から保育園の設置工事を始める予定になっております。えがおの森保育園・かつしまにつきましては、８月から工事を始めまして、１月の中旬にはでき上がる予定です。","voiceIndex":59,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"予算のところなのですけれども、平成２８年度の予算はこれでいいのかと思って、施設整備のところで、１,９００万円計上されているのと、あと、園舎の借り上げとかはもう具体的になっているのですか。この表の見方がよくわからないのですが、いつ段階だったら、実際にかかる費用がわかるのですか。","respondent":"佐藤保育施設調整担当課長","answer":"今、１,９００万円というお話で、平成２８年度の予算はそのとおりです。解体工事で１,３００万円、建物のリースが６００万円かかりまして、リース期間は前後１カ月ずつ、準備と解体等の準備が入って６２カ月で、３億７,２００万円です。","voiceIndex":61,"id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"北品川一丁目保育施設なのですけれども、ここは結構、面積が広いようです。今回は、そういう中で、定員の規模が６０人ということで、これは園庭をつくろうということで、こういう規模になるのか。それとも、暫定なので、あまり多くすると後が大変ということなのか。どういうところからこの定員が出てきたのか、考え方を教えてください。","respondent":"佐藤保育施設調整担当課長","answer":"定員と園庭等の話ですが、基本的にこれは港区との区境で、待機児童と今後の乳幼児人口等を見たときに、品川区民の利用がどれぐらいというのもありますと、５年間限定と総合的に考えまして、６０人の定員ですが、この他４０名は。","voiceIndex":63,"id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"今の定員は６０人とありますけれども、途中で拡大の可能性があるということは、施設的には少し余裕を持ってつくられるという理解でよろしいでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"委員がおっしゃるとおりです。","voiceIndex":65,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"北品川一丁目保育施設なのですけれども、昨日、ほかの委員の方から質問があって、例の広町の夢工房の話が出たのですが、設置、運営事業者を決めるときに、区も努力されていると思うのですが、あのような状況を過去に１度やられたというようなことは、なかなか把握し切れないものなのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"そのほかの細かいところは、私ども、気をつけて見てはおりますが、なかなか表に出てこない部分につきましては、そこまで調べることがなかなかできていませんので、不測の事態ということはできるだけないように努力するとは思っております。","voiceIndex":67,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それよりも、補助金の形でやっていく、いわゆる民民のほうがそういったことが起きやすい。第三者委員会に行って問題になったのも、そういうことです。ひろまち保育園みたいな契約の形ではなくて、民民の形でやった中ではそういうことだと思うのですけれども、民民のチェックもきちんとしていただきたいのです。","respondent":"大澤待機児童対策担当課長","answer":"認可保育園につきましては、東京都の認可ですので、基本的には東京都が指導検査ということになりますが、区の指導検査の担当も、必ず東京都が検査に入るときには一緒に立ち会って検査に入っておりますので、その辺は十分気をつけて対応していきたいと考えています。","voiceIndex":69,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"つかむ姿勢をぜひ持っていただきたいと思います。例えば経験年数とか、平均年齢が何歳で、賃金がどの程度かということは、つかもうと思えば十分つかめる。人件費比率とか離職率とか、そこに働いていらっしゃる方の働き方がどうなっているのかというのをぜひつかむ姿勢を持っていただいて、保育の質の向上を図っていただきたいのですが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"全ての事業者につきまして、今、継続して勤めていただくことが大事だと認識していらっしゃいますので、どの事業者も産休、育休は必ず整備しておりまして、研修制度、研修計画もきちんとつくっています。今、担当課長から初任給の話をさせていただきましたが、改めまして、どの金額で、どのような処遇、年収があるかというのは事業者ごとの事業費に基本的になりますので、その取り扱いについてはご承知おきをお願い申し上げます。","voiceIndex":71,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公表するかどうかは別として、妥当な処遇、待遇になっているのかどうかというところをぜひしっかり把握をしていただきたい。このところ、どんどん保育園も増えていますし、所管のところもすごく大変かと思いますけれども、ぜひ、きちんとした仕事をしていただくためのチェックをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-034"}]},{"id":"topic-03","title":"保育園の民営化と大規模改修計画等","agenda":"保育園の民営化と大規模改修計画等","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"幾つか確認なのですけれども、民営化の基本方針のところで、区立園については幼児教育の中核とするということなのですが、幼稚園とともにというのは、幼保一体にしていくということなのか、それぞれで中核にしていくということなのか、確認させていただきたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"民営化の対象園の検討状況ですが、３番の(2)にも書いてありますが、施設水準が高い保育園は委託事業者を確保しやすいということで、改築や大規模改修を実施するタイミングで併設施設でないところを一定の条件として考えているところです。","voiceIndex":80,"id":"exchange-035"},{"speaker":"のだて委員","kind":"確認","question":"幼保一体の考え方は、今のところ区立は別々としてということでしたけれども、今後は、そうすると幼保一体も考えつつ、中核にしていくということなのかという確認です。民営化対象園の検討の単独園ということでしたけれども、ほかにも特別保育の実施状況とかがあるのですが、この辺はどういった考えで判断されていくのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"２点、ご質問です。幼保一体施設の関係に関しては、検討を進めながら両にらみで推進していくです。民営化対象園の検討の特別保育の関係ですが、特別保育はいろいろあります。","voiceIndex":82,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"その次にある特別な配慮を要する児童への対応で、区立園ではそれの機能強化を図っていくということなのですが、この特別な配慮を要する児童というのは、どういった方を対象にしているのか、具体的に教えていただきたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"２点目の特別な配慮を要する児童というのは、今、特別支援という事業をやっておりまして、そういった関係を想定しています。","voiceIndex":84,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"今回、財政負担の低減も含めて民営化をやっていくということですけれども、この財政負担の低減というのは、人件費を削減していくということにもつながっていくのではないかという危惧があるのですが、このお考えはどうなっているでしょうか。改修してから民営化していくということですけれども、この改修費、昨日の話でもありましたが、これは区が出していくのか、伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"人件費と財政負担の低減の関係ですが、財政負担の低減に関しては、最終的に民設民営にした場合に、国と都から３,０００万円ぐらいの負担金が入りますので、その負担金等を見込んでいるのが１点と、あと、施設を新しく改築、大規模改修しますので、それ以降、使っている。","voiceIndex":86,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、民営化していくために公費で改修を行って、民営、委託していくということになるわけで、税金を民営化のために、企業のもうけのためにやっていくと見えるのですけれども、どう考えていらっしゃるのか、伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"改築経費の区の負担の考え方ですけれども、民営化するために無理やり改築、改修するわけではございませんで、施設的にもう老朽化がかなり進んでいて、改築が必要なところに、どうせやらなければならないことですので、改築と改修を行うです。","voiceIndex":88,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"しかし、せっかく公費を投入したところから民営化していくというのは、区民のお金を使って委託していくというか、疑問が残るというか、納得できないところがあるのですけれども、そこをもう少し、区民に説明できる形、納得できるようなご説明をいただければと思うのですが、いかがでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"私立保育園がもう区内にも３８園ありまして、定員３,０００名ぐらいの保育を日々やっていただいておりまして、保護者の方からも大きな信頼を得ている実績がありますので、民間でできることは民間に委ねるという基本方針に基づいて、区としては。","voiceIndex":90,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"次の質問に行きまして、保育園と幼稚園を７ブロックで連携しているというお話だったのですが、地域センター１３地区というのはわかるのですが、この７ブロックというのはどういう地域でまとまっているのか、ぜひ、資料等も出していただきたかったのですが、これはどういう形でやっていらっしゃるのか、伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"７ブロックの中身ですが、公立の保育園と幼稚園を大体１ブロック７から８園ぐらいに分かれていまして、具体的に地域を言いますと、品川地区、大崎地区、大井地区、大井南と八潮が一緒、荏原も３つに分かれていまして、荏原西、東、南ということで７ブロックで、地域で連携して。","voiceIndex":92,"id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"３点、確認します。同じ地域内にありますので、改修がされる方向なのか、確認をさせてください。民営化に関して、これは品川区だけでなく、他自治体も進めていることかと思うのですが、他の自治体の民営化率の状況を少し教えていただきたいのと、他の自治体が民営化にすることによって、大きくこういうふうに改善をされたとか、何かそういう事例がありましたら、教えていただきたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"八潮北保育園に関しては、７月２６日５時半から八潮北保育園で行います。八潮西保育園に関しては、その翌日、７月２７日、八潮西保育園で６時から行います。八潮南保育園は、またその翌日、７月２８日に八潮南保育園で６時から保護者の方への説明会を行う予定です。","voiceIndex":94,"id":"exchange-042"},{"speaker":"新妻委員","kind":"質問","question":"この周知ですけれども、地域の町会、自治会にはどのようになっていますでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"直近の工事をする八潮わかば幼稚園の近隣の関係者には、６月３０日、７月２日、あと７月１９日は夜間、３回に分けて、丁寧に説明をしたいと考えております。","voiceIndex":96,"id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"この民営化の目的、民間活力の活用と財政負担とあるのですけれども、この２つについて、まずはお伺いしたいと思います。ただ、いろいろな自治体は、今の公立園を民間にしたときにどういう変化があるという比較をしているのです。今の状況から言えば、後ろにずれる可能性もあるので、今、八潮地区でキャパシティーを減らす時期ではないのではないかと思うのですが、そのお考えを伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"区においては、多様な保育サービスと２番の(1)の2)に書いておりますけれども、この辺は公立ならではということで、詳細については今後検討しますが、公であったり、専門機関との連携等は区のほうで多くを担ったほうがいいと考えているところです。","voiceIndex":98,"id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"できれば、いつごろ、どういう形で出していただけるかわかるといいのですが、教えていただければと思いますが、未定であれば未定ということで構いません。定員の見直しとか、あとは八潮南保育園というのが一連の工事の後でどうなっていくかというのも含めて、ぜひ、区民に違和感のない方針をとっていただければと思います。","respondent":"佐藤保育施設調整担当課長","answer":"運営費の比較を出す時点ですが、集計してみて、またお知らせしたいと思います。八潮南保育園の定員に関しては、繰り返しになりますけれども、直前と今後の推移等を見て、総合的にまた考えていきたいと思います。","voiceIndex":100,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"出していただいた資料に沿ってお伺いしますけれども、１の(1)のところ、前にも何回かはお話ししていただいているのですが、相当数は区立のままとすると。すごく曖昧な書き方をしているのですが、この区立のままというのは公設公営のことなのか、公設民営のことなのか、両方のことなのか、その辺を教えていただきたいのが１つです。特色ある保育というのがどういうことを捉えているのか。","respondent":"佐藤保育施設調整担当課長","answer":"２点目の特色ある保育等の区の考え方ということなのですが、第２回の定例会で部長からも答弁していますけれども、民営化で行うことによって、区の保育に対する考え方やビジョンを変えるということはありませんので、今後も就学前の乳幼児に対する質の高い保育、教育を行って。","voiceIndex":102,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特色あるというのは、私立のところをお伺いしたのです。財政負担の低減のところなのです。ここは本当に何回伺っても納得できない。そこをしっかり認識して捉えていかないと、私立の特徴で、民間の力を活用していきます、保育力を活用していきますと言っても、結果的には賃金のところの問題点が大きく響くと思うのですが、その辺の考えはいかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"ビジョンにかかわることなのですけれども、品川区に小中一貫教育というすぐれた教育のシステムがありますので、認可保育園に預けていただいた保護者の方には、接続をよくして、小１プロブレムのない保育にするのが、これから私たち。","voiceIndex":104,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面で、公立できちんとした保育ができるという底辺には、賃金の保証がある、処遇の待遇がきちんとされているということで、安定した保育の仕事ができるのではないかと私は思っているのですが、午後とか何か言っていたのですが、ここはすごく大事な民営化のところで、ここを外しては議論にならないと思うのですが、その点はいかがでしょうか。","respondent":"竹田保育課長","answer":"過去と比べまして、５０代の層がどんどん退職していく中で、新規採用を毎年５０人程度増やしているという中で、経験値の高い人が抜けて若い人が入るという、人の入り繰りがありますので、全体的に、同じ人数を確保していても人件費が下がっていくという傾向があろうかと思います。","voiceIndex":106,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回は八潮地区と三ツ木地区の中身が本当に具体化になっているのですけれども、民営化はやめてほしいと思うのは、これから検証していくと書いてあります。おっしゃっていますけれども、既に民営化されて、保育の現場、子どもたちの状況がどうなっているのかというのは、かなり検証できているのです。すごく民間委託が進んでいます。ぜひ、踏みとどまって、考え直していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問","question":"民営化はよくないとか、公立がいいとか、逆に公立が悪いとか、いろいろな意見というのはあると思うのですけれども、今、具体的に公営企業を利用しているので、その利用者の間で、客観的なデータの集積という意味で、公立と民間を比較したような、例えばアンケートとか調査とかのデータはあるのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"区立保育園と私立保育園を比較しているデータなのですが、平成２８年４月入園申込者の方々の第１希望の数字があります。区立を第１希望に書いてある方は１,７４９名、私立を第１希望に書いてある方は１,３１５名と、ほぼ同程度という数字が出ています。","voiceIndex":109,"id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"だから、そういう客観的なデータというのを１回、都のほうでも、持っているのだったら、それをある程度、出してもらいたいし、持っていないのであったら、議論の出発点になるような、信頼できる母集団のデータというのを、ぜひ集めて開示していただきたいと思うのですが、いかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"委員がおっしゃるとおりでございまして、客観的な事実、ファクトで私どもは説明させていただいているところです。","voiceIndex":111,"id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"そうすると、親はどうかと。だから、その辺で客観的なデータをどのような形で収集して、どのように子どもが幸せで、本当に子どもの幸せをもとにした親御さんの立場はどうなのかというようなことを、こちらとしても、誤った、一部の意見みたいなものが広まらないような点からも、ぜひアプローチできるようなものが欲しいと私たちは要望します。","respondent":"あくつ委員長","answer":"今、鈴木委員からご提案がありましたけれども、ほかの委員からも何人かから、そういう比較というご意見がありましたので、正副で検討させていただきまして、また理事者ともご相談をさせていただきながら、先ほど鈴木委員のご発言の中にもありましたが。","voiceIndex":113,"id":"exchange-052"},{"speaker":"あべ委員","kind":"意見","question":"保育園の入園希望の申請というのは、保育の質以上に入りやすさですとか、家から近いかとか、新規園のほうが入りやすいから、新規園は今はみんな私立です。そういったことからも、本当に子どもにとっていい保育がどういったところで行われているかということが正確にわかる資料とは何かということをぜひ深く考えていただいて、資料を選んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-053"}]},{"id":"topic-04","title":"平塚シルバーセンター跡の施設整備","agenda":"平塚シルバーセンター跡の施設整備","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"多世代交流施設とは違うということなのでしょうか。どんな違いがあるのか、教えていただきたいと思います。この広さでいくと、延べ床面積だと５００平米あるということで、保育園等、今、待機児童もある中で、解消に向けて検討はされたのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"保育園等の検討はというところなのですが、検討しました結果、面積的に通常の認可保育園等は不可能な面積でして、もし、仮につくるとすれば、小規模保育施設ですが、在宅支援の観点からも重要というふうに考えて、在宅支援施設のほうを選択したものです。","voiceIndex":121,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"この施設の性格づけは今後ということだったのですが、つまりは、多世代交流施設とは違うという捉え方でいいのか、改めてになるかもしれませんが、確認させていただきたいと思います。保育園ですけれども、面積的に無理だという話だったのですが、今回、ご説明があった私立園でも４００平米ぐらいでやっているところがありますけれども、これは上下に分かれているから無理だということなのでしょうか。","respondent":"竹田保育課長","answer":"多世代ということですが、１階は高齢者、２階は子育て支援施設ということなので、通常はそれぞれの目的に使っていただくのですが、それぞれの世代が定期的に交流するような機会も設けていきたいと考えております。","voiceIndex":123,"id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"確認","question":"もう一回、確認したいのですけれども、さっきの保育課長のご説明だと、荏原保健センターの和室ルームが移転するとおっしゃったのですが、保健センターのオアシスルームが移転するのですか。","respondent":"竹田保育課長","answer":"荏原保健センター内のオアシスルームについては、ポップンルームであいたスペースをオアシスルームにしまして、定員を拡大していきたいと考えております。","voiceIndex":125,"id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"質問","question":"オアシスルームというのは、就学前のお子さんを対象に、時間単位で一時預かりをするということで、これは要するに、子育てしているご両親はいなくて、お子さんをオアシスルームのスタッフが預かるという形になるのですか。それとあと、ポップンルームというのは、お父さん、お母さん、それからお子さんが来て、そこでスタッフと自由に遊ばせるという形態ということで理解してよろしいですか。","respondent":"竹田保育課長","answer":"オアシスルームは１時間単位でお預かりして、その間に保護者の方がリフレッシュ等をしていただくという施設でございまして、ポップンルームは、お子さんを連れてきていただいて、お子さんも遊びますし、保護者同士の交流等を通して、地域交流に役立てていきたいという施設です。","voiceIndex":127,"id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"意見","question":"私たちも、待機児童の対策と同じで、保育園にお子さんを預けるご家庭のご両親にも支援が必要だと思っているのですけれども、在宅で大変にご苦労されながら子育てしているご両親もいらっしゃるわけです。こういう形で、在宅の子育てしているご両親を支援する。こういう施設を開設するということが非常に大切なことだと思うので、これに関しては非常に高く評価しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-058"},{"speaker":"あべ委員","kind":"質問・要望","question":"オアシスルームは非常に要望が強いもので、今回は増設ということになると思いますので、関連したいと思います。大体、１日の定員が、ここでどのくらいになるのか。それから、保健センターも定員増という形と今おっしゃっていたと思うのですが、荏原保健センターではどのくらい定員を増やす予定なのかということをまず教えてください。","respondent":"竹田保育課長","answer":"まだ基本設計等が始まっていない段階なので、確実なことは申し上げられないのですが、新設のこちらの施設については、定員１２名を考えております。それから、荏原保健センター内も定員は１０人ですので、２人増員して、１２人ということで考えております。","voiceIndex":130,"id":"exchange-059"},{"speaker":"あべ委員","kind":"確認","question":"ポップンルームというのは、毎日開かれているものでしたか。週に何回だったという気もするのですけれども、確認をさせてください。この建物全体の性質なのですけれども、基本的に高齢者が毎日通う施設で、２階にオアシスルームもあるし、時々、親子向けの事業もやっている。その辺のイメージを教えていただければと思います。","respondent":"竹田保育課長","answer":"もう一つの意味合いとしましては、指導員がおりますので、面積が限られていますので大々的なことはできないのですけれども、小さなイベント等、あるいは講習会等を企画しまして、地域の方にご参加いただくという２つの側面があろうかと思います。","voiceIndex":132,"id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"この平塚２丁目の場所が家庭あんしんセンターと非常に隣接していたと思います。それはそれとして、これだけ立地が近いので、子どもが利用できる新しい施設と平塚の家庭あんしんセンターが何らか意見するなり協力するなりということはあるのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"自由に使える部分も続けてはいくのですけれども、今、対象者のアフターフォローという形で、対処したお子さんを呼ぶ事業とかに取り組み始めたりしていますので、ありようについては、保育課等とも調整しながら検討しようかと思っています。","voiceIndex":134,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは１階のところなのですが、高齢者のところなので、所管ではないのですけれども、前のときも、元のシルバーセンター機能を残してほしいという意見もあったので、ぜひ、地域の方が時としては使えるような場所があるのかどうか。いろいろな使い勝手があるというところでは、在宅支援でとても求められているということで、２カ所に増えて、定員が増えるということは、とても喜ばしいことだと思います。","respondent":"竹田保育課長","answer":"平塚シルバーセンター跡地を入れれば１０カ所という形になります。それから、ポップンルームですが、先ほど申し上げた７月１日の北品川第二保育園で１カ所できますので、そこを１カ所と、現在、荏原保健センター内にあるもので２カ所という形になります。","voiceIndex":137,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当は保育園をつくってほしかったのですが、いろいろな地域に子育て支援の場所が身近なところにできるということはとてもいいことなので、ぜひ活用していただくとともに、子育ての要望、どういう支援が必要かとか、いろいろ意見を聞かれる場所にしていただけたらと思います。１点、当然だと思いますが、２階建て施設で、エレベーターはつきますか。その点だけ心配だったのです。","respondent":"竹田保育課長","answer":"まだ基本設計前の段階ですので、明確には申し上げられませんが、そういうことも踏まえて考えていきたいと考えています。","voiceIndex":139,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"児童センターなどは、結構、お母さんがお子さんを連れて、荷物を持って、上まで階段を上がるのが大変ということで、妊婦もいらっしゃるので、ぜひエレベーターをきちんとつけていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-064"}]},{"id":"topic-05","title":"平成２９年度新入学者の取扱い","agenda":"平成２９年度新入学者の取扱い","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"２、３ページの城南小学校と小山小学校のところで、実績では３クラスになっていますけれども、平成２９年度の受け入れ可能数だと２クラスになっていますが、小山小学校は前回と同じ９６名となると、先ほどのご説明だと学区内の方は抽選することなく入るということになっていくのだと思いますが、９０名だった場合は、３クラスにしたりとかということはあるのでしょうか。","respondent":"有馬学務課長","answer":"その結果として、平成２８年４月では、城南小学校は３クラス、小山小学校は３クラスという結果になりました。区域外の児童数がこの人数を超えた場合はしっかりと対応して、受け入れをしていきたいというふうになっております。","voiceIndex":146,"id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、そういった対応で、狭いスペースで勉学に励むということがないようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-066"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今日の議論の中でもいろいろ出されましたけれども、ぜひ、意見を聞いて、わかりやすい資料を出していただきたいと思います。","respondent":"あくつ委員長","answer":"午前中も申し述べさせていただきましたとおり、本日はご意見として賜りましたので、今後、実施していくにあたり、必要に応じて正副委員長または理事者と協議をしてまいります。","voiceIndex":151,"id":"exchange-067"},{"speaker":"あべ委員","kind":"意見","question":"それぞれ大切な項目で、こういったことでよろしいと思うのですが、子どもの家庭支援についてという言葉について、今、お話を聞くと、オアシスルームや乳幼児や貧困世帯などの支援ということで、子育て家庭の支援とかという言葉はよく聞くのですけれども、子どもの家庭という言い方はあまりしないです。もし、今の気持ちが伝われば、何か余裕があれば、修正案など出していただければと思います。お任せします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":153,"id":"exchange-068"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"調査項目が決まってから探そうと思っていたので、本日は案を持ってきていません。いつも一生懸命探して提案しても、ここに入らなくて、すぐ没になったりして、今日は持ち寄っていないので、お時間をいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"意見","question":"先進的な在宅子育て支援をしているような施設とかシステムを見たいです。それと、あとは保育園のあり方というので、いろいろな形態の保育園とかをもしも視察に入れていいのだったら、その見学もしたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-070"},{"speaker":"あべ委員","kind":"意見","question":"行政視察だと、どちらかというと遠方に宿泊込みで行く傾向が強くて、片道１時間ぐらいのところは、一番、見にいけない傾向があって、そこは何とかならないかと１０年間、思い続けているのですけれども、なかなか何とかならない。そういった近隣都市の実情を見にいく仕組みもあわせて機会がとれればとは思っております。","respondent":"あくつ委員長","answer":"私ども、正副委員長でも、そのようなことは今、検討しているところではあります。今回は行政視察ということで、委員会の中でもご意見が出ていたと思うのです。","voiceIndex":159,"id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"時々、言っていますのでよろしくお願いします。行政視察の目的の立て方にもよると思うのですけれども、所管事務調査の項目にしっかり沿ってというのも理屈に合いますし、そうでないものも１つぐらい入っていいのではないかという考え方もあると思います。自殺予防で言えば、例えば名古屋市なども、前回のときには書かせていただきましたので、もし可能であれば名古屋市を入れていただきたいと思います。","respondent":"あくつ委員長","answer":"先方の受け入れ状況にもよりますし、全て所管事務調査の項目に沿ってやらなければいけないということではありませんので、なるべく検討して、考えたいと思います。","voiceIndex":161,"id":"exchange-072"},{"speaker":"新妻委員","kind":"提案","question":"具体的に、山口県光市のコミュニティ・スクール、あさなえネットの取り組みが非常にいいということで、どうかというところを提案します。所管事務調査には入っておりませんが、発達障害というところで、早いうちから発達障害を見つけていくシステムをつくっている湖南市を参考にしながら、今、進めている愛媛県四国中央市の発達支援センターもどうかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-073"},{"speaker":"高橋（し）委員","kind":"質問","question":"民営化の話で、政令市が多いのですけれども、堺市、福岡市、京都市、広島市、仙台市とか盛んで、堺市などは今年の３月に改めて、１回、少しとめたところをやっています。保育園の民営化です。行政とここが組んだのは初めてだと伺っています。もう一つは飛んでしまうのですが、児童相談所で、中野区は５年後開設を目指しているというお話があったのですが、政令市で児童相談所を置いているところもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"意見","question":"去年、行った視察が山口県下関市のコミュニティ・スクールと、それから北九州市と、あと保育士募集の佐賀市だったので、去年行ったメンバーが何人かいるので、できたら新しいところで勉強したいという希望があります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-075"},{"speaker":"あべ委員","kind":"意見","question":"本筋からは外れると思うのですけれども、昨年度の行政視察で、１つのまち、品川区の視察が３カ所も、同じ自治体、今日は何とか委員会で、明日は残りの委員会、あれはどうかと思います。横の調整も、若干とっていただけるといいとは思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":167,"id":"exchange-076"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"もう一つは、「子どもの自殺をなくしたい命を守り抜く学校、社会の取り組みを」の大きなタイトルの質問の中で、１点目は自殺の背景、事実の把握をしっかりしてほしいということで、調査委員会の設置を求めましたが、ここのご答弁の中で、学校に起因をしない、いじめや子ども同士のトラブルというものが入っていないということで、早々に結論づけているわけですけれども。","respondent":"竹田保育課長、熊谷指導課長、村尾教育総合支援センター長","answer":"学校生活に起因する事実はない以上、保護者もそれを求めておりませんので、調査委員会等を設けるなど、これ以上の原因究明は行わないことを考えております。教職員についてですけれども、これも先日ご説明いたしましたとおり、ゲートキーパー研修を先日、生活指導主任を対象に行いました。","voiceIndex":172,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問","question":"こういう手が打たれたけれども、それが実際に働いていらっしゃる保育士や職員の方の給料に反映をされているというところをつかんでいるのかどうかというところを１つ、お伺いをしたいと思います。受けとめて、何とか消化しようという体制では、子どもたちの育ちにマイナスの状況が生まれてしまうと思うのですが、いかがでしょうか。","respondent":"竹田保育課長","answer":"東京都が今回実施したキャリアアップ補助金は、賃金のみの処遇に関して限定するという補助金ですので、その辺の補助金の趣旨は十分、各施設にお伝えしています。","voiceIndex":178,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問","question":"民営化のところは、これから行っていくというところでは、よそで行われている事例もあるので、具体的なところでまたいろいろ質問をしていきたいと考えています。現に、今回、複数のお子さんということにおいては、学校で出会った２人なのです。そういった意味で、学校と地域がつながってほしいと思っているので、今日、同じご答弁をいただいても、そこでとまってはまずいのではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国連の権利委員会の中でも、子どもたちが日本の教育の中ですごくストレスを感じていると。これは誰も否定できないことであると私は思うのです。そういった面も含めて、学校と地域の連携で、つながりを深めていっていただきたいと思うのですが、それは学校が中心になっていただきたいと考えていますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-080"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"例えば、原因究明の委員会でもつくったときに、教育委員会でそういうことは可能ですか。そんなことができるものですか。ご遺族や周りの友達や、それから先生たちの話を聞かないで、原因究明はできないと思うのですが、この辺をお答えいただきたいと思います。","respondent":"熊谷指導課長","answer":"今、副委員長のお話のとおり、ご遺族のご意向というのが一番大事な部分でありますので、それなしで調査委員会を設けるということは不可能です。","voiceIndex":185,"id":"exchange-081"},{"speaker":"沢田副委員長","kind":"質問","question":"周りにいらっしゃる、身近な方たちへのケアというものも、１つの自殺予防、自殺が起きたときの大変大きな課題になっているわけです。そういう中で、原因究明、調査するということは、その人たちを再び傷つけることになるし、苦しめることになるということは私も一般質問で言いましたけれども、それについて何ら触れられない。そういう人たちはそれでいいのですかということなのです。家族もそうです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-082"},{"speaker":"飯沼委員","kind":"意見","question":"もちろん話したくない人のものをあえて掘り起こしていくようなことではない。個人への配慮は、当然、大事だと思います。」ここが大事なのですが、「遺族が、どうして我が子が自殺したのかを知りたいと思うのは自然であり、事実を知ることが遺族にとって最高のケアであり、また予防につながる調査であることを共通認識にしてほしい」という言葉で背景調査の意義をおっしゃっているのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":188,"id":"exchange-083"},{"speaker":"鈴木（博）委員","kind":"質問","question":"思春期というのは、心が非常に揺れ動く時期で、死をすごく身近に感じるし、自殺も身近に感じるのです。この委員会でもいいし、市民講演会でもいいですけれども、そういう形で、１回、勉強会みたいなものをぜひ区のほうで企画してやっていただければ、みんなが共通の正しい理解を土台にして議論ができるようになるので、非常にすばらしい試みなのではないかと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-084"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からも、２点ほどお伺いしたいと思います。特に私立の場合、いろいろなのです。ただ、例えば時間がたって、遺族の方が、やはりあのときのことについてもう少し知りたいとか、こういうことについて、やはり調べてほしいというようなことが、半年後とか１年後とか、時間がたったときに出てきたときには、そこにしっかりと対応をしていただきたいと思います。","respondent":"竹田保育課長、熊谷指導課長","answer":"実際の保育の運営面でのお話ですが、こちらにつきましても、指導検査等の権限の範囲内で現状把握、それから保育の改善に努めてまいりたいと考えております。今、ご質問がありましたとおり、今後ということで、ご遺族のご意向ですとか、さまざま状況が変わってきたときには、また真剣に配慮しながら、また、子どもたちの心のケアにも努めながらとは考えております。","voiceIndex":193,"id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":53995,"voices":200}},{"id":"h28-20160628-5","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"総務委員会","time":"午後 １時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"当初予算でなくて補正で組んだというところの説明を、もう一度伺いたいと思います。それと住民基本台帳の追加分ということで９,３４０万５,０００円、これは、個人番号カードにかかわる経費というのは、かなり額が多くなってきているように思っているのですれど、そういう中でさらに追加というところは、どうしてなのかを伺いたいと思います。","respondent":"秋山財政課長、仁平情報推進課長","answer":"ただし、シティプロモーション事業で検討を進めていく中で、区の魅力を発信していくということにおいて、７０周年というものを有効に活用といいますか、やることによって、相乗効果でシティプロモーション事業の効果も上げていこう。個人番号カードの交付は国のほうの予算で措置されるものです。当初、全国的に１,５００万枚ぐらいだろうという見込みで計算しておりましたが、想定より申請数が多く、倍の３,０００万枚ほどになっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"品川区ではどのぐらいのトラブルがあるのか、わかれば教えていただきたいのですけれども、そういう状況もあって、かなり実施というか、きちんとしたシステムの構築がなかなかというところがあって、どうも新聞報道によると、マイナンバー制度で使う個人番号カードの交付におくれが生じている問題で、このシステム機構は、理事長と副理事長が報酬を２カ月間一部返納することを決めたと。","respondent":"秋山財政課長","answer":"今回の幼保一体施設の実施設計ですけれども、定員についてというお尋ねだと思います。これは今の定員はおっしゃるとおりですけれども、それが実際に幼保一体施設になったとき、どうなるかというのを、設計の中で検討するというふうに聞いております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"１６０名が入れるような方向で検討するのかどうかというのが、今一つわからなかったので、そこは明確に答えてください。それと住民基本台帳のほうのお答えをお願いしたいと思います。","respondent":"秋山財政課長、仁平情報推進課長","answer":"幼保一体施設の定員については、「設計の中で検討します」というふうに聞いております。我々としましては、せっかく交付に窓口のほうへ見えられたお客様に対しまして、システムがとまったということでかなりお待ちいただく時間が長くなってしまったとか、その日に発行できずに郵送で対応させていただいたとか。","voiceIndex":10,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も、区制７０周年事業は、なぜこれが当初予算でなかったのかとずっと思っていたので、わかりました。その分の回復のための経費とか、そういうものはどうなっているのか。そもそも私もどれぐらいのトラブルが起きて、どれぐらい、今どういう状況になっているのか、この補正の判断をするに当たってもご報告いただきたいと思うのですが、いかがでしょうか。","respondent":"久保田総務課長、仁平情報推進課長、秋山財政課長","answer":"私からは７０周年記念事業のＰＲ経費についてお答えいたします。こちらの補正予算の説明資料には、ラッピングバス運行等ＰＲ経費と書いてあります。それと、先ほどのトラブル状況ということですけれども、障害の回復以降は通常どおり作業ができておりますので、特段システム上のトラブルというのは。６月の補正の理由の一つは、夏場の有意義な体験の機会ができると、確保するためということで、今後の継続性ということでありますけれども。","voiceIndex":13,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"それら全部を含んで、この予算ということでよろしいのですよね。ラッピングの中身、要するに７０周年ということをラッピングして走らせるという趣旨なのでしょうか。その辺のことを教えていただきたいのと。そうすると、先方に委託していくことになるのかなと思うのですが、委託先というのもこれまでの継続というふうに捉えてよろしいのでしょうか。その辺の事業の中身がどうなっていくのか教えてください。","respondent":"久保田総務課長、秋山財政課長","answer":"ラッピングバスについてですけれども、経費としましては３００万円ほどの見積もりということで、予定しているものです。中身についてですが、７０周年ということの周知を図るということとあわせて、シティプロモーションの観点から「わ！宮古市の復興支援ですけれども、この事業につきましては、品川区のＰＴＡ連合会から派生した非営利の団体というのがずっとこの事業を、宮古市との間に入って、募集をしたりという実務を進めてきたところがありますので。","voiceIndex":17,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"予算で区民の皆さんにもきちっと報告しているわけですが、普通の細かい事業ならあれですが、その辺どうなのでしょうか。本来、区制７０周年記念事業ならば、やはり総務管理費の中で事業を一本化して、こちらの環境費のほうに計上すると、なぜここで２つに分けるのか、その事業は確かに違うのですが、本来、区制７０周年記念事業というのは総務管理費で、きちっと一本化してやるというのが筋ではないか。","respondent":"秋山財政課長","answer":"考え方ですけれども、看板事業ではないかですけれども、７０周年について、今年になって初めて考えたということでは当然なくて、当初は平成２９年度中ではどうかということで、２８年度の予算策定時には、そういう形で判断していたところです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"大倉委員","kind":"質問・要望","question":"この７０周年に向けて、本当に前々から準備されてきていると思うので、どういったところでどういうことを考えながらやってきたという、その検討の過程について、ちょっと教えていただきたいのと。７０周年の事業をなぜやるのかという、そもそも論ですね。しながわ百景リニューアルですが、先ほどお話の中では、もう既にないものがあるとかという中で、現状どうなっているか、教えていただきたいと思います。","respondent":"久保田総務課長、中元広報広聴課長","answer":"私どもとしましてはこうした考えから、節目の事業、７０周年事業というものを大切にして、行っていきたいということで、この間には品川区と荏原区の合併があったり、また自治権の確立の歴史があったり。しながわ百景の現状ですが、完全に場所がなくなってしまったものが、はっきり把握しているのが６カ所ほどあります。","voiceIndex":22,"id":"exchange-007"},{"speaker":"大倉委員","kind":"質問","question":"しながわ百景の現状なのですが、今もう６カ所はないということで、ホームページ上とか、その百景の中で表示とかはどうなっているのか、教えてください。","respondent":"中元広報広聴課長、久保田総務課長","answer":"しながわ百景につきましても、同じように区制７０周年のご紹介と一緒に、まず古い百景のご紹介をちょっとして。さらには、地域を知っていただくということでパネル展等も考えてございまして、昭和２０年代の品川区の生まれたときから。すみません、答弁漏れがございました。銘板等ですが、なくなった場所につきましては撤去をさせていただいているところです。","voiceIndex":25,"id":"exchange-008"},{"speaker":"大倉委員","kind":"質問","question":"具体的に言うと何かとか、特にあれですけれど、例えば婚姻届とかそういったものを７０周年記念で発行してみようとか、いろいろ質問の中でもあったと思うのですけれど、品川区独自の婚姻届みたいな、そういったものも考えてもいいのかなというところがあるので、そういった７０周年だからこそ、記念として何かこう、品川区で試験的に試してみようみたいなものがあれば。","respondent":"久保田総務課長","answer":"全庁周知を図っていく中で、既存の事業の中で７０周年に絡めて、何かちょっと工夫ができないかとか、新しいことができないかということを考えてありますので、委員からのご提案の趣旨も踏まえまして、それぞれの既存事業の中、また新規事業の中。","voiceIndex":29,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"スポーツ協会とか、そういう団体の方々も含めて、一緒に話をしてほしいと思っていて、一緒になってみんなでやりましょうということを、まずはそういう方々とも機会を設けて、それぞれの所管でもいいのですけれども、そういうのをやらないと、そのままずっと流れていくような気がしてならないので、ただ全庁挙げて冠といっても。","respondent":"久保田総務課長","answer":"この件につきましては、７０周年ということで全庁挙げての体制を組んですので、私どもも今回の予算が通った後には、例えば商店街ですとか町会へ働きかけて意見をいただくという機会は、各所管を通じてになると思いますけれども、そういった機会を設けるとともに。","voiceIndex":31,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひお願いします。それで、これは通った後ですけれど、第３回定例会でも構わないですし、いつでもいいのですけれど、それに伴ってお話を聞いて、また補正が出てくるということも、私はありかなと思うのですね。議会も、５０周年のときは子ども議会とか、周年行事の一環としてやったり、お二人は現役で体験されてるかもしれないですけれど、そういうこともあったやに聞いています。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-011"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ちょっと基本的なことを教えてほしいのですが。最初のほうで、今のまさに７０周年記念事業、総務一般管理費、広報広聴費、地域活動費、それから社会福祉総務費、児童福祉施設費、先ほど質疑があった環境対策費ですが、これ、歳入はまずどこになるのか、ちょっと教えていただきたいのですが。","respondent":"秋山財政課長","answer":"歳入は、２０ページからの歳入で充当事業と書かれてあるものにつきましては、特定財源ということで充当費があります。財源につきましては、多くは２２ページの繰越金、これを財源として、今回補正として出しています。","voiceIndex":34,"id":"exchange-012"},{"speaker":"つる副委員長","kind":"確認","question":"すみません、まず基本的なことの確認でした。先ほど吉田委員からちらっと確認がありましたが、２５ページの７０周年記念事業の補正予算規模なのですが、先ほど来の質疑の中で、このタイミングの話だとか、いろいろある中で、年度中にというお話があって。","respondent":"久保田総務課長","answer":"そういった意味では、当初考えていたものとほぼ同じぐらいの規模かなということではありますが、ただ、中身等につきましても、まだ平成２９年度に向けてという検討もあるかと思いますので、引き続き検討はしていきたいと思っているところではあります。","voiceIndex":36,"id":"exchange-013"},{"speaker":"つる副委員長","kind":"質問","question":"わかりました。先ほどのご答弁の中で、シティプロモーションとの相乗効果ということでお話があった中で、ただ、記念事業としてラッピングバスなどの細かい部分とか、パネル展とかそういう話があったのですが、まさにシティプロモーションとの相乗効果と言われている、その相乗効果の部分というのは、どういうふうに考えているのか詳しく教えてください。","respondent":"久保田総務課長","answer":"しながわ」だけでやりますと、それぞれ単体のもので終わってしまう可能性がありますけれど、それらを総合的に事業として組み立てて進めていくことで、それぞれの事業の持っている強みというか面白みのところが、効果としてさらにプラスアルファで出ていくと思っているところです。","voiceIndex":38,"id":"exchange-014"},{"speaker":"つる副委員長","kind":"確認","question":"記念式典が来年３月で、そこに向けてのボルテージを上げていくという、いろいろな取組み方があると思うのですが、今、シティプロモーションとの相乗効果という部分をお話しいただいて、まさに区民の方に対してのそういった部分と、また、まさにシティのプロモーションですから、区外の方々にどういうふうにして、その７０周年も含めて、まさに品川区の魅力等を発信して。","respondent":"久保田総務課長、中元広報広聴課長","answer":"ですから例えば冠事業等につきましても、９月から一斉に冠を各事業に付与していただくとか、ラッピングバスも具体的に、私ども内部の検討ですけれども、例えば半年間とか決まった期間の運行がありますので、それに合わせて。そういうことでアクセス数等もある程度はいい結果が、数値が出ればいいかなということで考えております。","voiceIndex":40,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"やはり個人のプライバシーについてもかなりいろいろ、ネットで情報漏れがある中で、全くそれがなくならない中で、それを継続していくというこの住基ネットについては、やめるべきだと私たちはもともと思っているし、そういう中で数え切れないぐらいのシステムダウンが起こって、予想以上に経費がかかっているという点から、反対です。２つ目の理由は、幼保一体施設の実施設計の委託についてです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-016"},{"speaker":"南委員","kind":"意見","question":"ごめんなさい、３００万円としても、やはりラッピングバスというのは、気運醸成というのはあるかもしれませんけれども、ほかの方法でいくらでもできるし、やはり区民のいろいろな政治に対する不信とか、お金の使い方とか、生活実感が本当に厳しくなっているときに、そういうものはもう少し配慮があっていいのではないかと思いますので、意見として申し上げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、ほかの事業については先ほど７０周年については補正で出てきたということが、どうしても納得いかないところはありますし、ラッピングバス自体も７０周年記念事業としてはいかがなものかというふうに思います。ただ７０周年記念事業そのものについては、ちゃんと意義を持って進めるべきだと考えていますし、地域振興費、社会福祉費などもぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"政治資金を初めとする税金の使い方に対して、本当にひどい実態が明らかになった、そういう中で選挙になったわけですけれども、そういう事態を招いた舛添氏の責任は重いと思います。したがって辞任は当然だと私たちも考えています。同時に、こういう方を知事として担いだ政党の責任はあると思いますので、そのことは言っておきたいと思います。それで、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-019"}]},{"id":"topic-02","title":"福井県坂井市との連携事業","agenda":"福井県坂井市との連携事業","exchanges":[{"speaker":"南委員","kind":"質問","question":"坂井市のアンテナショップが戸越銀座商店街にということですが、このアンテナショップというのは常設なのですか。年間通じて常設のショップなのかというのが１点。シティプロモーションサミットは第４回の開催だというのですが、この間、どのような状況があったのか、過去の状況を教えてください。","respondent":"柏原企画調整課長、中島企画部副参事","answer":"営業の時間であるとか、定休日等々については、これから調整と聞いてありますけれども、基本的にはずっとあけているお店ということで聞いてございまして。その後、平成２６年の相模原市、昨年度は弘前市で開催されました。過去、相模原市で開催されたときは１２３自治体が参加されまして、シティプロモーションに関心が高い自治体が、多く集まるサミットです。","voiceIndex":80,"id":"exchange-020"},{"speaker":"南委員","kind":"意見","question":"わかりました。品川区の戸越銀座商店街を選んでいただいたのはうれしいのですけれども、これを品川区に聞くのも何なんですけれども、地域の繁栄している商店街であることは確かなのですが、どうして品川区なのかというのがちょっと。わかる範囲でいいですけれど、失礼のないような感じで聞きたいと思うのですが。","respondent":"柏原企画調整課長","answer":"昨年来、連携を始めたということで、実は昨年、物販を品川区内で行いたいということで、同商店街でお店といいますか借りまして、物販をしたという経緯があります。","voiceIndex":83,"id":"exchange-021"}]},{"id":"topic-03","title":"冨士見台中学校外壁改修その他工事請負契約","agenda":"冨士見台中学校外壁改修その他工事請負契約","exchanges":[{"speaker":"南委員","kind":"意見","question":"工事内容を見ると、外壁も建具も校庭面だけとなっているのですけれど、そうでない部分というのは大丈夫だという認識でこういうふうになっているのかと思うのですけれど、一般的に外壁とか建具は同じような年数がたっているので一緒に工事をするのではないかと思っていたのですけれど、その辺はどうなってこうなっているのか。","respondent":"小林施設整備課長","answer":"この工事ですけれども、夏休み期間で進めていくということを聞いているのですけれども、その関係で全面の外壁を一気にやりますと、当然足場を外す時期とか遅くなりますので、計画的に工事を進めるために、範囲を区切ったということだと思います。","voiceIndex":94,"id":"exchange-022"},{"speaker":"南委員","kind":"確認","question":"そうすると、当然必要性はあるけれども、そういう工事期間の関係で一部にとどめたということですから、その他の必要な部分はまた計画的にというと、来年の夏になるのかわからないですけれど、そうやってやっていく予定はあると、そういうことで確認していいですか。","respondent":"小林施設整備課長","answer":"教育委員会のほうで進めているものですけれども、多分そういうものだと考えています。","voiceIndex":96,"id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"関連した質問になるのですけれども、太陽光発電設置エリアの屋上防水というのがありますが、これは今までどういうふうになっていて、今それがどういう必要性が出てきて、こういう工事になったかということ。それから発電周りフェンスの新設というふうになっているのですが、どういうことでこれを新設するのか、すみません、基本的なことなのですけれど、この工事の内容について教えてください。","respondent":"小林施設整備課長","answer":"先ほどもお話ししましたが、教育委員会で工事をやるものですから、私のわかる範囲でお答えしますけれども、太陽光発電を設置するときには、風だ何だということで飛ばされないように、床のスラブにアンカーというものを打ちます。","voiceIndex":98,"id":"exchange-024"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、これは取り上げていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"提案","question":"それが、本場がある品川区がそういう事業のことについてまるっきり、今まで勉強もしないまま来ているということは、いいことなのかという感じになりまして、これは一回、委員会としてもしっかり勉強したほうがいいのではないかと思いまして、提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-026"},{"speaker":"大倉委員","kind":"意見","question":"シティプロモーションは先ほどの報告にもあったとおり、連携事業で今度サミットも開催するという中で、２０２０年のオリンピック・パラリンピックに向けてもしっかりと品川の魅力を発信していく、いろいろな人に来てもらうというところでも、さらに一歩進んでやっていくのが大事かなと思って、項目に挙げさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"ネットとしては、やはりマイナンバー制度がなかなかうまく進んでいないような状況で、それは常に調査を続けていかなければいけないのではという問題意識があって、これを挙げましたが、例えばふるさと納税についても、もともと品川区のふるさと納税のあり方は、いわゆる税収が上がらない地域が考えるふるさと納税と違う考え方があってもいいのではないかと思っていたので、これもいいかなとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっと質問いいですか。そこら辺は委員長にも差配いただかないと、これを取り上げるとなると、扱いが非常に微妙なところがあって、いろいろな所管の人をどうやって呼ぶかみたいな話にもなりかねないから、それはやはりやるべきではないと思います。いろいろな人を呼んで、所管をまたぐようなことをするべきではないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-029"},{"speaker":"南委員","kind":"意見","question":"ですけれど、幾つか項目があって、１年かけてやっていくので、１回、２回のそういう議論の場があってもいいのではないかと思っているので、その辺の組み立て等についてはお任せするのですけれど。ぜひ２項目、２テーマというところにコンプリートしないで、いろいろなところを出して研究して行ければいいかと思っているので。お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"恐らく何度説明されてもわかりにくいのではないかと思うので、これ１本だけでほとんど終わる状態なのかなと。私は思っていたのは、せっかくこの場でやるなら、これからこの品川区が置かれている立場、大都市問題ですか、高齢化がさらに進む、かといって子どもたちがたくさん品川区に入ってくる、さまざまな問題が起きると思うのですが、そういう将来を見据えた議論ができる場があるといいなと思います。","respondent":"松澤委員長","answer":"ありがとうございました。さまざまなご意見をいただきました。このいただいた意見をもとにして、正副で再度調整し、次回７月２６日の委員会でお示し、決定していきたいと思いますが、よろしいでしょうか。","voiceIndex":111,"id":"exchange-031"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"大倉委員","kind":"意見","question":"シティプロモーションが先ほど出たので、所管事務調査のところで。さっきも申しましたが、全国シティプロモーションサミット、これを見に行くのも一ついいのかなと思ってはいるのですが。なので、坂井市に。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ所管事務調査で取り上げるところを、考えていただきたいと思います。品川区も今はマイナス５億円ではないかと言っているぐらいですから、首都圏のどこか大きいところで、その減ることをどう捉えて、どういう対策をしているかというのも、ほかの自治体のそういうのも、増えているところと、すごく減っているところ、あわせて話が聞きに行ければ、すごく参考になるのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"我々毎年国内視察、各自治体を見てくるわけですが、やはり今お話が出たシティプロモーションにしても、その自治体が人口が減る、そして若者もいなくなる、仕事もなくなる、ですから何とか起死回生しようということで、さまざまな手を打っております。遠方に行って、そこに行けば必ず言われることは、「何で品川区さんが来るんですか」と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"それと、今、須貝委員がおっしゃった２泊３日の日程にこだわらない視察のあり方というのも、もうそろそろ実施していけるような、そういうことをしてもいいのではないかと思っているのです。ですから、所管事務調査で行くということを前提にしながら組んでいくということは必要だと思うし、２泊３日という日程にこだわらず組んでいったほうがいいのかなと思います。","respondent":"松澤委員長","answer":"いろいろご意見をいただきました。行政視察は毎年第３回定例会後に実施しておりますけれども、今回同様にして行きたいと思います。いろいろな意見がありますけれども、よろしいですね。","voiceIndex":118,"id":"exchange-035"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問","question":"それで今回については行くということだけでなくて、どうなのでしょうか、そういう毎年行くことについては、みたいな議論というのは、正副のところでどういうふうに行われたのか。その辺についてどうなのか、経過を教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-036"},{"speaker":"南委員","kind":"提案","question":"そういうご意見で、委員長としては視察に行きたいというご提案があったということですけれど、それを決める前に意見を諮っていただきたかったと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2050#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":37816,"voices":137}},{"id":"h28-20160628-10","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時４０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"別に、委員会運営に支障がなければ、こちらは柔軟に対応してもいいのかなというふうに思います。その判断は、委員長が仕切るでしょうから、それに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"貴重な時間をお借りいたしまして、リオオリンピック視察・調査への議員派遣の件ですけれども、議会でぜひ再考していただき、中止を求めたいと思います。ぜひ、議運の場というか、議論の場を設けていただいて、ぜひ、中止の再考をしていただきたいと思います。","respondent":"鈴木（真）委員長","answer":"ご意見いただきました。既に派遣が決定し、議決もとっている案件ですので、検討するということで、検討します。","voiceIndex":18,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり、主体である都議会議員が行かないのにもかかわらず、区議会が行くというのは、ちょっと何か間違っているのではないかと思いますので、ぜひ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":3194,"voices":22}},{"id":"h28-20160629-14","meetingId":"h28-cm06","date":"2016年6月29日","dateIso":"2016-06-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ４時１７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"公有地等、公共施設活用に関すること","agenda":"公有地等、公共施設活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"幾つかお伺いします。どんなことを今、検討されているのかというのを、まずお伺いします。そこで働く労働者の賃金水準や、正規・非正規など、雇用形態はどう反映される数字なのか、お伺いします。これが２点目ですね。単身者の若い人が増えているということなのか、その辺について、ちょっとお伺いします。","respondent":"柏原企画調整課長","answer":"１点目のＰＤＣＡの関係です。検討の体制の部分ですけれども、これにつきましては、先ほどもちょっとご案内いたしましたけれども、どういった形でチェックをかけるかというところは、タイミングも含めて、ちょっと今、検討しています。","voiceIndex":8,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと、なかなか、この数字をどう読むかというのは、難しい点があるのですが。最後のところからですけれども。単身者の転入が多いという傾向なのですよね。品川区全体でいうと。その転入の中の２０代、２０歳から２９歳の単身者がかなり多いということではないということなのでしょうかね。その辺をちょっともう一度お伺いしたいと思います。区としては、どうすれば実現できるとお考えなのか。","respondent":"柏原企画調整課長","answer":"人口移動の部分ですけれども、この２つの表、４９ページと５１ページの表ですけれども、単純にこれとこれだけを持って、２０歳から３９歳の単身の世帯の出入りが多いかというのは、ちょっとこれだけでは比較はできないのですが。","voiceIndex":10,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"雇用の場のところですけれども。魅力ある雇用の場というところにおいての、そういったディーセント・ワークという点では、区はどのように、この魅力ある雇用の場という関連で考えていらっしゃるのかは、お伺いします。合わせていかがでしょうか。というのが雇用のところですね。できないという現実がある中で、何を望んで、何を区に望んでいるのかというのは、ちょっとお伺いしたので、聞かせてください。","respondent":"柏原企画調整課長","answer":"委員のご提案といいますか、関連のお話をいただいたところ、ありますけれども、区としてできる、何ができるのかというところで、区のほうで総合実施計画であったり、長期基本計画である、区でできるものについての、ここは施策というのを挙げさせていただいて。","voiceIndex":12,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、この目標を達成する上でも、こうしたところの数値目標を、今も掲げられておりますが、もう少し強化、もっと強化していく必要があると思いますし、それが、今回の行革委員会の、総合戦略人口推計と区内の施設需要というところでの調査項目に、まさに合致した、必要な充実だと思うのですけれども、その点はいかがでしょうか。これは要望です。","respondent":"柏原企画調整課長","answer":"こちらも、例えば認可保育園等の開設・運営支援というのは、重点ということで、１つ大きな目標として掲げてありますので、決して、この辺が政策として載せていないということではなくて、こういったところを重点を置きながら、施策は進めているというものですので。","voiceIndex":14,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"人口推計を見ますと、現在の子どもの数でも、認可保育園を希望しながら入れなかった方が１,０００人近くいたというところで、このビジョンを見ても、子どもの現在の数と、同程度まで子どもがいるというのは、６１ページですか、かなりもう、随分先ですね。年少人口でもいいのですよ。ですから、私は、やはりこれでは足りないと思うのですが。この、年少人口の将来推計値との関係で、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"計画に達成するように、所管のほうでも努力をしていますので、この人口ビジョンとかけ離れた形で施策を行っているものではないというふうに考えてあります。","voiceIndex":16,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"その前提に立って、幾つかお考えを伺いたいところです。私ども、最近、その乳幼児人口が増えている中に、乳幼児の転入も多くて、なかなか保育園に入れなくてというような流れの言葉をよく聞くのですけれども、実際に数字を見ていると、０から４歳ですか、この人口というのはむしろ転出が増えている。区としては、どのように感じてらっしゃるかということを、１つまず教えてください。","respondent":"柏原企画調整課長","answer":"ただ、分析については、やはりもう少し深く入ったところの分析というのは、必要だというのは認識しています。","voiceIndex":22,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"それぞれありがとうあります。後半の話から行くと、要は、区としては、区の人口バランスについて、指導的に考えるというよりも、民間の開発に従って人口バランスが移っていけば、それに合わせて、区として公共施設の再配置を見直すという、そういう考え方に立っているということでよろしいのでしょうか。今後も、住民の人口維持という形で行くのか。それについて、お考えを教えてください。","respondent":"柏原企画調整課長","answer":"人口の分布によって、公共施設の再配置という、需要に対する供給の考え方というのは、当然検討しなくてはいけないというふうには思ってありますけれども、単純に施設を移すというよりは、その施設の機能であるとか、そういったところも含めながら。","voiceIndex":26,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"ハードの整備だけではなくて、何と言ったらいいのでしょうか。というのが、例えば、１人目のお子さんを生むのがもう３０歳を過ぎてからだよというような状況が、今多い中で、これはどうすることも、なかなかできないし。老朽化している。あります。そういうのを順番に、もうやっていこうというような形で、しっかり考えるのにいいタイミングなのではないかと思うのですが、例えばその辺、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"今後の施設の老朽に対応するところです。今、例示として旧荏原第四中学校ということで挙げていただきました。今の、使っている使い方は、先ほど午前中にお話をしたとおりです。いわゆる老朽施設に対する施設の建替えの代替地といいますか、というところの考え方であると思います。","voiceIndex":30,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"来年切れるということは、そこからまた使えるわけですから、やはり、今ちょうど、長期的に見た長期基本計画の中でも、この総合戦略とブッキングさせながら進めていく中では、すごく適地と言いましょうか、これからの品川区、どういうふうになっていくのだろうというのに、宣伝になると言ったら言葉は悪いですけれども、新たな仕掛けの始まりというようなところもありますので、そういった意味では。","respondent":"柏原企画調整課長","answer":"区が持っている基本的な行政計画、長期基本計画であったり、総合実施計画であったり、そこと、この書いてある、例えば指標をとりなさいであるとかいった、一定の要件があるのですが、その要件を満たしていれば、そういう総合計画で。","voiceIndex":32,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問・要望","question":"１年間に。偶然、返ってきた八百何通がそうだったのかもしれないけれども、大概の方はもう転入されてきているとか、また転出していく方がやはり多い場所なのかという思いもありますから、その長期基本計画の中でも結構ですから、やはり１０年スパンなのか５年スパンなのかわからないですけれども、このようなものでニーズの把握というのはし続けていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"何点かお伺いしたいのですが。先ほどの計算式の説明をいただいたのですが、要するに、何なのという。これが、３兆９,０００億円強から、５年後に４兆３,０００億円にするということが、ちょっとイメージが、全然、済みません、湧かないので。もしかしたら、ここをもっと深めていかなければいけないという話にもなるかもしれませんので、そういうことを前提に、まず、もう１回お話を、説明を受けたい。","respondent":"柏原企画調整課長","answer":"ちょっと繰り返しになりますけれども、売上以外の部分で付加価値、労働であるとか、税の部分であるとか、そういったところも含めて、全体的な底上げを、企業全体として１０％上げたいということでつくったというのが、この目標値になってあります。","voiceIndex":36,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほどの、策定委員会の中で、非常にハードルが高いというところのイメージを、もう１回持たせていただきたいので、その１０％上げて４兆３,０００億円にするという、非常にハードルが高いけれども、いけるのではないかといったところの、専門家のご意見、お話というのは、どういった内容だったのでしょうか。","respondent":"柏原企画調整課長","answer":"狙いといいますか、もちろん、情報通信業であるとか、そういったところには、もちろん、今伸びていくところですし、品川区の特徴でもありますので、そこも、我々としてはバックアップしたり、頑張っていただくという支援はするのですけれども、それ以外の業態についても。","voiceIndex":38,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"説明しづらいところは、ありがとうございました。勉強させていただきたいと思います。もう１点だけ。左のグラフと見比べても、ちょうど、出生数がありますけれども、おおむね一致しているというところで、１つは、先ほど出生数のお話がありましたけれども、もう１つの大きな要素として、この転出超過、転入超過ですかね。この、なぜ転出超過になったのかというのは、何か分析は、されていたら教えてください。","respondent":"柏原企画調整課長","answer":"区だけの単独の何かでできるかというのは、こういう部分についてはなかなか難しい面はありますけれども、こういう、日本全国、世界も含めての経済の大きな動きがあったところで、地価にそれが影響を与えたというところで、この転出が多くなったという時期が。","voiceIndex":40,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"今、バブルと地価高騰という２つの言葉があったのですけれども。ですので、今の分析はちょっと。では、港区とか、他の２３区も、全部こういうことで、それはもう一くくり、バブルと地価高騰が要因で、では、いわゆる行政のやってきた仕事との関係性とか分析というのは、もう少し何かあってもいいのかなという思いで、ちょっともう１回お聞きしたい。","respondent":"柏原企画調整課長","answer":"それは、もちろん地価という部分もありますけれども、施策の部分について、どうそれが品川区にとどまっていただけるのかであるとか、品川区に入っていただけるかというのは、こういったところの分析も踏まえながら。","voiceIndex":42,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"最後に。５年という期間で既に初年度がスタート、昨年ですかね。してしまったのかという中で、あと３年、４年という中で、これは分析、ＰＤＣＡも含めて、特に分析をしなければいけない項目が、どれですかと聞くと、またたくさんありますということになるかもしれませんけれども。それでまたＰＤＣＡのほうに反映をさせていきますというような考え方はどうなのでしょうか。","respondent":"柏原企画調整課長","answer":"要するに、数値目標の部分についても、変える部分については変えてもよろしいというようなこともありますので、その辺は、上方修正か下方修正かはちょっと置いておくにしても、そのＰＤＣＡを踏まえながら、どういった事業が、では効果的なのかという、課題の研究と合わせて。","voiceIndex":44,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"済みません。ちょっと１つ確認をさせていただきたいのですが。先ほど、別の委員から、品川区の各地区の人口推移ということで、八潮地区がやはり、人口減が進んでいるというお話がありました。今後、この５年間、平成３１年度までのこの目標の中で、そういうところもしっかりとご検討いただく中での、この八潮地域における、品川区ができる施策というのは、どんなものがあるのでしょうか。","respondent":"柏原企画調整課長","answer":"まちづくりの視点で、この八潮というまちを、今後どう考えていくのだというのは、区としても、ビジョンというとちょっとあれかもしれませんが、考え方みたいなものをちょっと検討しながら出していくという。","voiceIndex":50,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"八潮の地域は、ちょうど４年後のオリンピック・パラリンピックの開催競技会場にも近い地域であります。このオリ・パラの開催というのが、１つは大きなものになるかと思うのです。なので、さらにまたここの人口増を目指し、またこれを、皆さんに来ていただきやすいようなまちづくりとか、また交通の便ですとかも、ぜひご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-017"},{"speaker":"沢田委員","kind":"意見","question":"ただ、この品川区内の、上の、実宿泊者数は１１２万人から１２３万人ということで、１１万人ぐらい増やしていきたいという目標だとは思うのですけれども、そのうちの外国人は３万人ぐらい増やしていきたいということで、この中の、基本目標の中の流れを読んでいると、オリンピックに向けてということで、外国人観光客の誘致を推進していくとは書いてあるのですけれども、そこまで、それよりもやはり。","respondent":"柏原企画調整課長","answer":"基本目標３番目のところの、ここの数値目標の捉え方といいますか、考え方につきましては、今、委員がご紹介いただいたとおり、オリンピック・パラリンピック、こういったところを契機に、宿泊という数値をとりましたけれども、来訪していただきたいと。","voiceIndex":56,"id":"exchange-018"},{"speaker":"沢田委員","kind":"意見","question":"まさにそれをちょっと聞きたかったのですけれども。品川区内に余り、少ないということで。これは、予想されているのは、ほとんど今、品川区のビジネスホテルとか、もうほとんどいっぱい、９割以上の稼働率だという話も、以前もありましたけれども。今、この先、ホテルとかが増えていくという見通しがあるのかというのもあると思うのですけれども、その辺のところのお考えをお聞かせください。","respondent":"柏原企画調整課長","answer":"ただ、民泊で劇的に数が増えるかというのは、やはり限界があろうかと思いますので、やはり、それ以外の部分での泊まれるような施設というのは必要だと思ってありますが、今の段階では、劇的に、そういったホテルであるとか、宿泊施設が増えるというような傾向といいますか。","voiceIndex":58,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"人口ビジョンのアンケートのところで、理想の子どもの数を実現するのが難しいというところでいきますと、一番の理由が、出産・子育て・教育にお金がかかりすぎるということで、６０％になっておりまして、理想の子どもの数を実現するために、今後、品川区が取り組むべき点、良くなってほしい点でいきましても、２番目に、出産・子育てに対する経済的支援を充実するというのを望んでおりますけれども、この間。","respondent":"柏原企画調整課長","answer":"地元の方のご意見であるとか、そういったところを踏まえながら、旧荏原第四中学校に限らず、施設についての総合的な検証・検討が必要だというふうに思ってありますので、これからもそういった形で進めていきたいというふうに思ってあります。","voiceIndex":61,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"アンケートのところで、全てかなえなくてもいいというお話でしたけれども、やはり、１番と２番のところで来ているものですので、出生率１.４５に上げていくということを考えても、やはりこの経済的負担がかせになっている結果だと思いますので、その辺、どういった施策。今後、総合的に判断していくことですけれども、その経済的負担の軽減を含めてやっていくという理解でよろしいのでしょうか。","respondent":"柏原企画調整課長","answer":"こういったところを踏まえながら、いろいろな面のニーズであったり、お声であったり、他の面でもいろいろな声を聞く場面があります。そういったところを総合的に見ながら、区が、どういった形で施策を打てるかを検討して、施策を打っていくというものです。","voiceIndex":63,"id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"資料をご検討いただきたいのですけれども。地域ごとに、公共施設が今、どういう状態にあるのか。例えば、ブロックなり地域センターごとに、人口１万人当たりの各公共施設数がどういう状況にあるのかというものが、マップでわかるようなものがあると、かなり現状がわかりやすいかなと思ったのです。マップでなくてもいいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-022"}]},{"id":"topic-02","title":"羽田空港の機能強化に関すること","agenda":"羽田空港の機能強化に関すること","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"今、経済効果のことでたくさん説明をいただいて。今、先ほど、最初の説明の中でも、区長がその課題についていろいろ質問されたということで、その中で、今、まだ明確な答弁がなかったように、ちょっと聞こえたのですけれども、もう一度ちょっと改めて、そこのところだけ確認をさせていただきたいと思います。区長が質問されたことに対しての、国交省側のお答えのほうを確認させてください。","respondent":"三ツ橋環境課長","answer":"それに対して国は、まだ、夏ということだけで、具体的な方策内容につきましても、その夏がいつなのかというのが、７月なのか８月なのかという、はっきりした、本当に明確なことは答えておりません。そちらが実情です。","voiceIndex":72,"id":"exchange-023"},{"speaker":"沢田委員","kind":"意見","question":"いろいろともう話は、時間が大分たっているかと思うのですね。やはり品川区として、しっかりと、先ほど区長が、ほかにもいろいろと、落下物のことだとか、説明会をちゃんとやってほしい、そういうことを、しっかりともっとやっていただかないと、なかなか、この先ということに関しては、なかなか判断できる情報が少ないのではないかなと思うのですけれども、そのあたりのお考えをお聞かせください。","respondent":"三ツ橋環境課長","answer":"その中では、環境に配慮した方策の方向性という文言で出されておりまして、検討の方向性というものが３つ出されております。それが、飛行経路の運用方法の工夫であったり、あと、環境対策であったり、この方向性、安全対策であったり、その３つに関しては出されております。","voiceIndex":74,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"今日まで続いている対策委員会が先般開かれて、質疑応答が委員会であったということで、区長がそこにいたのか、何を求めたのかというのがわからなかったのですけれども、もう少し詳しく説明していただきたいのですが。とりわけ、最初のほうに、何かこういう撤回を求めよという投書が来ていますと。その辺もちょっとわからない説明だったので、そこをまず教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"こういう意見が区民から来ておりますよということを、区長が伝えたものです。その他、先ほど申し上げましたように、説明会の方法について、また環境に配慮した方策についてなど、具体的にどうなっているのかということを聞いております。","voiceIndex":77,"id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"非常に、評価するのは難しいのですが、そういう声があるのだということを伝えたということは、確かに、私はあえて評価したいと思いますが、それではもちろん足りない。それでちょっと確認したいのですが。環境影響に配慮した方策の策定というのを、この夏にすると。その時期は何月だと言わなかったという話ですけれども、これは何なのですかね。何なのかというのをお伺いしたいのですけれども。","respondent":"三ツ橋環境課長","answer":"先ほど言いました３点ですけれども、この環境に配慮した方策というものが、例えばどのような方策が考えられますでしょうかという質問形式になっておりまして、その中で、今、検討の方向性はこういう方向性があるんですよと、国が言っているところでございまして。","voiceIndex":79,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"今、課長がおっしゃったのは、８月の夏の前に、とりあえず４月に国が出した方向性というものなのですね。それは私も知っています。中身も知っています。それで、そこで余りはっきりしていないというのも知っていますが。この環境影響に配慮した方策の策定ということは、イコール、国が計画を、案をとって決定するということの宣言だと思うのですけれども、それはどうなのでしょうか。間違いなのでしょうか。","respondent":"三ツ橋環境課長","answer":"しかしながら、恐らく委員がおっしゃいましたように、こういうルート案ですよということが出されるのではないかと。そういうふうに想定されるものです。","voiceIndex":81,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。そのとおりだと思うのです。先ほど、区長が委員会で何を言ったかという話はありましたけれども、やはり、委員会の開催を待たずしても、区、品川区独自でも、明確な計画撤回を、意見を表明していく必要が、私はあると思いますし、それを、区には求めたいと思います。その頻度は１日にどれくらいで、何時ぐらいを飛んでいたのかというのを、ちょっとわかれば教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"その延長線上、品川区の場所が左側になるのですけれども、この図でいきますと、書かれてはおりませんが、左側となっておりますので、ちょっと、町丁目までははっきりいたしませんけれども、ちょっと想定していただける範囲で、旧Ｃと旧Ａと旧Ｂがございまして。","voiceIndex":83,"id":"exchange-028"},{"speaker":"安藤委員","kind":"提案","question":"わかりました。合わせまして、経済効果についてお伺いしたいのですけれども。といいますのは、今までさんざん、経済なのだ、経済のためには必要なのだということで、国が説明して、この新ルートを提案してきたのに、なぜ今、今まで出せなかったのかなというのは、ちょっとわからない。なぜ今の発表なのかというのと。それよりも、この経済効果というのは大きいメリットだと考えていらっしゃるのか、伺います。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"町丁目につきましては、具体的に想定される範囲ですけれども、この旧Ｃであったり旧Ａであったりの、黄色い部分でいきますと、新Ａと一番下の部分がオレンジ色の部分が旧Ｃになるのですけれども、そのあたりの左側の部分ですので。この経済波及効果に対しまして、区の評価ですけれども、この経済波及効果、国が、この公表の仕方としましては、幾らの増産が見込めて、そして雇用が幾ら増えますよという、プラスの面で述べているような。","voiceIndex":85,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"まさにその、今、メリットとして評価するものではないということまでおっしゃっていますし、比べるものではないということで、一般質問の本会議での答弁もありましたけれども、そこは私たちもそうだと思うのですね。考え方が一致するところだと思うのです。だからこそ、区は、踏み込んで、この計画に対しては、正面から撤回を求めるべきだと思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"区も、かねてから申し上げておりますように、今、このルート、新飛行経路は、案として今、国から出されているということと、そして、この環境影響につきましては、区も、課題があることを、国に、今までも申し上げて、そしてその対応を求めてきたところです。","voiceIndex":88,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"いろいろご答弁ありがとうあります。港区ですけれども、品川駅もありますし、この主要４駅の真上を通るです。この経済波及効果を、国土交通省が出されるのであったら、品川区にとっての経済波及効果はどのくらいなのかということも、改めて、品川区として、国土交通省に対して、出していただきたいということを、ぜひともお願いをしていただきたいのですけれども、これについて、いかがお考えでしょうか。","respondent":"中村都市計画課長","answer":"しかしながら、やはり、この波及効果の数値を出す計測をするもととなります、訪日外国人、あるいは日本人の新たな旅行者からもとにしたものだということで、これは、広い範囲で捉えれば７０５万人というものの数字から推計はできるけれども、ただこれが、品川区だとか。","voiceIndex":91,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"冒頭お話出ました、東京国際空港騒音対策委員会についてなのですけれども。区長も、先ほど、この委員会の中で、しっかり区民のことを考えて、前向きなご質問というか、国に対して要望されたということなので、非常に関心がある委員会だと思いますので、この東京国際空港騒音対策委員会の公開というのも、国に対して求めていっていただきたいと思うのですけれども、それについて区はどうお考えなのでしょうか。","respondent":"三ツ橋環境課長","answer":"今回、この東京国際空港騒音対策委員会というのは、昭和３５年から、こちらに明記しておりますように、開催して、ずっと開催しているもので、この時代というのは情報公開の云々がなかったようなのです。","voiceIndex":93,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"区長も先ほど、委員会の中で、かなり積極的なご発言をされたと思うのですけれども。区民の意見だけではなく、議会の意見書もあるということも、しっかりとお伝えをしていただきたいということと。もう、かなり積極的に主張をしております。この新ルート案撤回という、基本的なところから、しっかりと主張をしていただきたいと考えておりますけれども、その点について、いかがお考えでしょうか。","respondent":"中村都市計画課長","answer":"区が反対というところにつきましては、先ほどの繰り返しになりますけれども、まず、国の対応について注視するです。過去におきまして、品川区上空を飛行していたというところにつきましては、これは、防音対策などが公共施設等で行われたという事実もあります。","voiceIndex":95,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほどの、東京国際空港騒音対策委員会においても、区長の質問に対して、環境方策はいつなのかという問いに対して、夏ですという漠然とした答えしか返さないような国の態度ですので、しっかりと、品川区の代表者たる品川区長、及び品川区民の安全・安心を守るべき自治体としての品川区は、しっかりと国に対して、より、今まで以上、より積極的に。","respondent":"中村都市計画課長","answer":"この方策を、国が策定するに当たりましては、区といたしましては、この中間の取りまとめが公表されて以来、ずっと、品川区に対してデメリットをなるべく少なくするような方策について、可能な限り検討していただきたいということを申し述べてまいりました。","voiceIndex":97,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも、その注視した結果、国が出してきた案が、あまりにも品川区民の生命、安全を害するようなものでしたら、積極的に反対をしていただきたいと考えております。ぜひともよろしくお願いします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-035"},{"speaker":"あべ委員","kind":"提案","question":"幾つか質問させていただきたいと思います。このときも、かなりいろいろあったかと思います。その前に、海上ルートが自動的に出てきたわけではなくて、やはり陸上ルートというものも、合わせてというか、打診がされていたと、提案がされていたと思いますし。これは、聞いてストレートに出てくるかわかりませんけれども、どのようにお考えか、まず教えてください。","respondent":"三ツ橋環境課長","answer":"そのあたりも、かなり状況が違っているのではないかと考えています。しかしながら、この交渉という部分に関しましては、やはりノウハウは、過去の経緯も含めて考えなければいけないとは思っておりますので、可能な限り確認はしてまいりたいと考えています。","voiceIndex":101,"id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"それが１点です。この土台の数字の評価についてお伺いしたいと思います。とすれば、そうした関連の自治体とともに、例えば、連絡協議会ですとか、勉強会ですとか、そういったものをきちんと設けて、利害をともにすると言ったらいいのでしょうか。そういったところで、共通の対策を考えていくというやり方もあるのではないかと思いますので、ぜひ検討していただきたいと思うのですが、いかがでしょうか。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"現状といたしましましては、成長率は、非常になかなか足踏み状態という現状がありますが、ただこれ、２０２０年までにどうなるかはわかりませんけれども、今、計測値は、そういった状況の中での計測だというふうに認識しております。近隣区、例えば目黒区、港区などと一緒に、平成２６年にこの案が出されたころに関しましては、４区で勉強会は実施しておりまして、ここ最近、その勉強会が実施しておりませんので、また連携を図りながら実施していきたいと思います。","voiceIndex":103,"id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"それぞれありがとうございました。デメリットは、別に、訪日外国人が来たことのデメリットというよりも、その新ルートそのものに対するデメリットを網羅的にまとめてということを求めたいと思います。そうではないという考え方も、十分に合理的なのだということを、できるだけ区民に示していくことが必要だと思いますので、区としての姿勢を教えてください。以上、２点、もう１回ご答弁をお願いします。","respondent":"三ツ橋環境課長","answer":"実際に、騒音測定などにつきましては、また、どのようなこと、実施するに当たって、いろいろ検討していかなければいけないものがたくさんあると思いますので、慎重に検討していきたいと考えています。","voiceIndex":106,"id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"私ども、この２年間、会派としても、何度も国交省の担当の方とお話をさせていただいたり、いろいろな要望を出させていただきましたけれども。結果として、この２年間、ほぼ、品川区部分については、ゼロ回答に近いと考えています。最後になりますけれども、私たち議会といたしましても、一昨年の１２月に意見書をまとめました。最後は私見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"昭和５１年の広報には、航空機公害の被害について、意識調査も行っています。電話や会話が聞こえないという生活の影響から、体への影響ですとか、気分への影響も調査しています。こういった、今回の計画は、さらにひどいものだと、悪影響があると思うのですけれども。これは、区民の住環境の悪化になると思うのですが、どうでしょうか。","respondent":"三ツ橋環境課長","answer":"実際に、影響というものがどの程度なのかというのは、国が国の責任をもって考えなければならないと考えていますので、実際は、この法律上は、対策地域とはなっておりませんので、この住民への影響という部分につきましては、法律範囲外と考えております。","voiceIndex":110,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"住民の影響について、法律外だということなのですけれども。法律がどうこうということではなくて、やはり、騒音だけでなく、落下物の問題ですとか、大気汚染、また墜落事故も、可能性もありますので、こういったことを考えると、区民への影響というのは、悪いことばかりだと思うのですが、そこを聞いたので、もう一度、答弁お願いします。","respondent":"三ツ橋環境課長","answer":"区も、騒音影響があり、また、安全対策というものは、十分徹底してもらわなければいけないと考えていますので、全く法律範囲外だからといって、全く騒音影響がないというふうには考えておりません。","voiceIndex":112,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"何らかの対策をやってもらうということで、ぜひそれは求めていっていただきたいと思いますが。そのために、区民の命も危険にさらすというリスクを考えれば、この計画に対して、やはり区長は、撤回を求める声もあったということですけれども、区としても、一歩踏み込んでいただいて、計画反対、撤回を求めていっていただきたいと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"撤回を求めることにつきましては、また、先ほどの繰り返しになりますけれども、この環境影響に配慮した方策につきまして、国の方策を注視するです。","voiceIndex":114,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"当時、沖合移転したときに拡張された便数を見ても、年間２４万回となっておりまして、今回の新ルートが実行されれば、年間４４万回ということで、約、倍に、今回の影響は、前回よりも大きいわけでありまして、住環境の悪化、危険増大、図り知れないと思いますので、ぜひ、この夏まで待つのではなくて、今のうちから、計画撤回を求めていっていただきたいと思いますが、改めて伺います。","respondent":"中村都市計画課長","answer":"この夏までの国の方策、これは待つということではなくて、その方策の中に、可能な限り、品川区に対してデメリットが少なくなるようなそういった検討をお願いをしていますので、まずはやはりそれを見てからということになるかと思います。","voiceIndex":116,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"待つわけではないということで、今回の、夏の環境方策を出されることについても、決定が出されるのではないかと想定されるということでしたので、ぜひ、決まる前から、計画撤回していく立場で、区民の命を守るために、頑張っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-044"},{"speaker":"安藤委員","kind":"提案","question":"これまでの請願質疑の中でも、私は、こんな計画はほかにあるのですかと質問したのですが、品川区は、国資料によるとということで、ロンドンのヒースロー空港や、ニューヨークのラガーディア空港、大阪伊丹空港や福岡空港などを挙げておりました。脚下げは高度何メートルぐらいのところ、もっと言えば、着陸手前何メートルぐらいで行うのか、今回のルートではどの辺になるのか、伺います。","respondent":"中村都市計画課長","answer":"これは、航空機だとかパイロットによって、いろいろと違うということですけれども。ただ、その脚下げの位置についても、これは、国としても、その辺は情報としては明らかにしていきたいとは言っております。現時点では、まだ明らかにされておりません。","voiceIndex":124,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"目黒駅のあたり。９.５キロメートル先です。これは大変危険ではないかというふうに思っておりまして、そういうことですから、やはり、区としても調査し、認識を持つべきだし、示されていないというのであれば、本当に、国がこのまま計画を強行するというのは、本当に許されないことだと言わざるを得ないと思います。だから中止しかないと思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"車輪の出し入れそのものが安全であるという、そういった説明にはなりませんけれども、今、国のほうからは、氷の落下の事例を調べていく中では、車輪の出し入れに伴って氷が落下するという原因が。","voiceIndex":126,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは、国の説明をうのみにすることはできないと思いますし。十分に、研究、注意をしていかなければいけないところですし、少なくとも、この脚下げの位置というのは、今回の新ルートではどこになるのかというのは、強く、この国に、明らかに、もう今すぐでも明らかにするように、早急に求めていただきたいと思いますけれども、この点が何かありましたらということが１点です。","respondent":"中村都市計画課長","answer":"その建物の範囲につきましては、これは、まずやはり優先順位としては、公共施設や、それから病院等の準公共施設、また住宅だとかという、今、要求のところでは、全ての建物について、そういった措置をお願いをしています。","voiceIndex":128,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうなりますと、これ、今の時期に、条件闘争に入っているのですか、というふうに聞こえてしまうのです。私は、この時期に、被害が最も集中する地元自治体の品川区の区長として、今やるべきことというのは、条件闘争ではなくて、正面からこの中止を、というか、撤回というのを、求めることではないかと思うのですけれども、いかがでしょうかね。条件闘争なのですか。これは。","respondent":"中村都市計画課長","answer":"現在、国が、この夏に方策を出すという中で、その方策を出す上での話として、出す際には、そういった、事前に、可能な限りの防音等の環境影響に配慮した方策について、具体的に検討するように要望したもので、これがすなわち、品川区上空を飛ぶこの案について。","voiceIndex":130,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"方策を出すのであれば、こういったことをやってくださいと。仮に、それが、区が言うとおり、区長が言うとおり、国がのみますということになって、環境方策が出たら、品川区は、自分たちの要求が通った。その上で、環境影響に配慮した方策が策定されたということで、賛成するということなのでしょうか。","respondent":"中村都市計画課長","answer":"この環境に配慮した方策は、防音や安全だとか、方針を項目として出て、具体的なものは何一つないです。したがいまして、国から、具体的なものが出たとしますと、そこから、区としてどうするかというのが始まっていくのかなというふうに考えてあります。","voiceIndex":132,"id":"exchange-049"},{"speaker":"安藤委員","kind":"提案","question":"今やるべきことは、やはり、きちんと、国が方針を決定する前に、区民の立場に立って、計画撤回をということを強く求めていくということだと思いますし、それを改めて、品川区には肝に銘じていただきたいし、そのような立場で臨んでいただきたいというふうに思います。質問したいのは、どうして品川区は、私たちの質問に対して、このような考えが示されていないと言えるのでしょうか。それをお伺いします。","respondent":"中村都市計画課長","answer":"国からの説明です。この、２０２０年以降の計画につきましては、新たな滑走路が建設された後に、これで、さらに品川区の環境影響が低減をされればこれに越したことはございませんけれども、これは案が実現したと、仮にした場合ですけれども。","voiceIndex":134,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"ですから、今回の、やはり都心ルート案の解禁というのは、イコール、将来の新滑走路プラスさらなる増便ということと直結していることだと、私は思います。しかも、滑走路の交差部分の解消というのは、幾ら技術が発展してもできませんし、やはり私は、今から、今回の新ルートを許せば、さらなる増便の道を開くことになるという認識を持つべきだと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"区といたしましても、この時間帯につきましては、非常に、国からの説明では、１日の生活の中で、最大限、時間帯としては配慮したというふうに言っているところですけれども、この時間帯が、幅が広がったりしてしまっては、区民に対する影響が。","voiceIndex":136,"id":"exchange-051"},{"speaker":"松澤委員","kind":"質問","question":"安藤委員に聞いていいですか。私、初めてこの委員会に出たもので、初めてこの航空機の問題、羽田の問題についての議論を聞いたのですが。今、安藤委員が脚下げの位置がどうのこうのと言っていたのですけれども、脚下げの位置を知ることによって、何がわかるのか、それをちょっと、勉強不足なので、安藤委員、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-052"},{"speaker":"安藤委員","kind":"意見","question":"脚を下げるときに、飛行機に付着した氷塊、氷の塊が落下するというケースが多いので、今回の新ルートでどの辺の地点で脚を下げるのかということを知ることは、具体的に品川区民にどのような危険があるのかというのを、より正確に知る上で、とても大切な情報だと、私は思います。それがわかるということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"例えば、私たちも、大阪の伊丹空港、やはり騒音問題など調査に行ったのですよ。そのとき、勉強不足で、こういうの、どこで脚を開くのかなどというのは質問してこなかったのですね。恐らく、安藤委員は熱心ですから、当然、伊丹に行って、高度何メートルで脚を開く、あるいは、開いたらこれを航空会社が地元に説明しているとかという答弁を聞いてきたと思うのですね。その結果をちょっとお知らせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-054"},{"speaker":"安藤委員","kind":"意見","question":"重要なのが、成田です。成田のほうでは現在でも、管制官のほうから、海の上で脚をおろしてくださいという指導をしていて、わざわざ双眼鏡を使って、脚下げを忘れていたら、脚下げを忘れていますよということを、管制官のほうから飛行機に通達しているということもやっているということもありますので、それは、やはり、危険性を認識しているからだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-055"},{"speaker":"松澤委員","kind":"質問・要望","question":"脚下げで危険がある。そこまで言うのなら、やはり自分たちでしっかりと、他で、何メートルでここの空港は下げていますよ、成田は何ですよ、それだけの根拠を示して質問しないと、ただ、何か私、今聞いて、何か不安をあおっているだけではないかなと。こういう質問をされるのでは、何か審議できないなと思っているのですよ。しっかりと根拠を持った質問をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-056"},{"speaker":"あべ委員","kind":"意見","question":"今のご議論なのですが。私も手元に数字がないので、一般論にしておきますけれども。そういった意味では、どこだったか、成田でも１３件でしたか。氷が。１８のうち、１０。氷だけで１３。失礼しました。飛行経路やら、そのときの１本１本の状況によって、実際に何メートルのときに必ず出すとか出さないというよりは、大体５００メートル程度が目安というのも妥当なラインではないかと、私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-057"},{"speaker":"松澤委員","kind":"質問","question":"今のようなことならば、我々だってわかるのですよ。言われれば。ただそれを、何メートルで下げるのだ、言えないのか、という質問というのは、聞いていて、聞き苦しい。それなら数字の根拠を示して、しっかりと言ってきなさいよ。私は、ただ不安をあおっているだけの質問だな、嫌な質問だなと思って聞いていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"請願にもありますけれども、着陸前の８分間が一番危険であるいうことが言われておりますけれども、この８分間というのは、品川区の上空を飛行しているということでいいのか、改めてなのですが、ちょっと確認させていただきたいと思います。","respondent":"中村都市計画課長","answer":"こういったことも踏まえて、国交省、あるいは航空会社も、その辺は、事故については、そういった時間帯ですとか、あるいは統計的に見たパイロットのウイークポイントですとか、あるいは心理的な状況、こういったものも、やはり過去の事例から。","voiceIndex":146,"id":"exchange-059"},{"speaker":"のだて委員","kind":"意見","question":"品川区上空が８分のうちに入っているということで、やはり一番墜落事故の危険性も高い時間帯ということで、やはり墜落の危険性も書かれていましたけれども、免れないということになると思いますので、この計画、ぜひ、私としてもやめていくべきだと考えていますので、採択していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-060"},{"speaker":"若林委員","kind":"意見","question":"私どもも、これまでの前５本も含めて、審査をして、そのときの状況、ご説明いただいた中で、まずは説明がまだ、いわゆる不十分であるということを中心に、まず国交省の今後のいわゆる方策、対応をしっかり見極めてからの、いわゆる結論に持っていくという考え方は、再三申し上げておりますので、今の段階では、継続ということで、同じ扱いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":154,"id":"exchange-061"},{"speaker":"安藤委員","kind":"意見","question":"私たちとしましては、６本、結論を出すべきだと思っています。やはり、夏の環境影響に配慮した方策の策定も迫っておりますし、この時期に明確な撤回をという意思を上げていくことが必要だと思いますし、それとあと、区民の皆さんの運動も、大きく声も広がっている中、委員の皆さんにも届いたと思うのですけれども、会の方から、採択してほしいということで、熱意あふれる手紙も届いております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-062"},{"speaker":"あべ委員","kind":"意見","question":"私どもとしては、まずこれ、６本一括で考えていきたいと考えています。その上で、今期、このメンバーでの行革委員会が、今回第１回ということもありまして、今回継続をお願いしたいと思います。ただ、これが、国の事業であるということを鑑みますと、議会として、また他にいろいろ何かできることはないかということは考えているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-063"},{"speaker":"筒井委員","kind":"意見","question":"我々としては、国土交通省の環境方策がこの夏ということ、迫っているということでもありますし、請願内容も妥当だと考えますので、我々はまず反対という前提を鑑みれば、この場において結論を出すべきと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":157,"id":"exchange-064"},{"speaker":"渡部委員","kind":"提案","question":"意見書を、やはり会派で必要に感じたところが、やはりその提案をしてきて、当然その案文をお示しいただいて、それについて審議を諮っていくべきもの。今、出た話ですので、今どうこうというのでは、全くありませんので。１本つくるのに。ですから、それをしっかり、では、どういうふうにやっていくのかと、方策も何もないままそれを諮られるのは、非常に困りますので、なかったことにしましょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":161,"id":"exchange-065"},{"speaker":"安藤委員","kind":"提案","question":"正副のほうで検討していただくにしても、改めてこのタイミングで、議会として意見書を出していくというあべ委員の提案というのは、私は大事な点ではないかと思います。やり方とか、そういうのはいろいろあると思うので、そういった手続きは踏んでいただくにしても、意見書を出すということに関しては、大事なことだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-066"},{"speaker":"あべ委員","kind":"提案","question":"する、しないというのは手続きもありますし、会派ごとのお考えもあるでしょうし、やはり、皆から出てきた形の総意として、意見書としては、あるほうがいいだろうと思いますので、ここでいきなり提案して、さあどうだというのは、ちょっと仕切りが、流れが、違う流れのほうがやりやすいかなというふうに考えて。さっきのは提案と受け取らないでいただけるとありがたいのですが。よろしくお願いします。","respondent":"鈴木（ひ）委員長","answer":"わかりました。では、ちょっと皆さんから、意見書について、どういうふうな思いかというご意見もちょっと伺いたいというふうな思いがありまして、皆さんのご意見は伺いました。そうですね。その件に関しては、また、正副でもちょっと検討をさせていただきたいと思います。","voiceIndex":166,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":76111,"voices":171}},{"id":"h28-20160630-18","meetingId":"h28-cm06","date":"2016年6月30日","dateIso":"2016-06-30","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ４時５９分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"ざっと読みます。例えば、「品川大井ホッケー場」であるとか、それから「品川潮風公園」、できればこういうふうな、オリンピック開催時に公式な施設名に「品川」という名称がつけられるように、これがもしできれば、品川だけではなくて、ほかの自治体へも呼びかけをしていただいて、ほかの開催自治体が同じような仕組みをとっていただければなおありがたいと考えていますので、提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"提案","question":"次、文化プログラムの推進に関することですけれども、先ほども文化プログラムの視察の中でも触れましたが、認証を受けた文化プログラムとはちょっとまた違う観点の、文化庁が言っている「文化力」プロジェクト、また、それに類する芸術文化活動、品川区民芸術祭の位置づけを確認・整理した上で、品川区が取り組む方向性について検討していきたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"一番最初に、オリンピック・パラリンピックの推進に関することは、２つ出しました。１０番目の「ロンドンオリンピックのバリアフリーに学ぶ」、１１番の「オリンピック憲章を深める」です。一番最初だけかわります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"「ロンドンオリンピックのバリアフリーに学ぶ」というのは、新聞等々でも報道されていたのですけれども、レガシーの部分で、障害者スポーツに関するところではないかというふうに事務局からも言われたのですけれども、やはりまちづくり、そして、ロンドンオリンピックのときに、ロンドンが一気にオリンピックを契機にバリアフリーを進めたということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-004"},{"speaker":"いながわ委員","kind":"質問・要望","question":"３２番が、障害者スポーツの区内誘致を積極的にやっていくと。４９番が、文化プログラムの実施をする際の活動拠点はどこになるのかという疑問があったので、活動拠点の確認というのですか、それとあと、必要であれば、それに際しての整備、その活動拠点の整備をする際には、やはりレガシーではないですけれども、その後のまちづくりにもしっかり活かせるような、そういったものも含んで書きました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-005"},{"speaker":"藤原委員","kind":"提案","question":"リオの視察結果を特別委員会において、報告だけではなく、もちろんどういうふうに活用していくのか。障害者スポーツなのですけれども、ここは１点、ユニバーサルスポーツ大会（年２回）の確実な実施と定着ということをしていきたいです。４法人の連携と活用をこれからどういうふうにしていくのかということと、あと、もう一点は、議場で演奏会の開催をしたらどうかと提案したいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"それで、オリンピック・パラリンピックの推進に関することで、１９番、これは昨年度のこの委員会のときに、たしか道路の使い方でまだ検討段階ということだったのですけれども、選手が移動するときの専用道路と優先道路というのが出てきて、専用道路というのはイメージがつくのだけれども、優先というのはどうやって優先するのだろうかという質問をして、そのときはまだ東京都ですか。","respondent":"渡辺委員長","answer":"それはよろしいでしょうか。１点。今、それぞれご説明いただいて、次回以降、その内容で同種のものを整理して、テーマ別に委員間討議に入りたいと思っています。","voiceIndex":12,"id":"exchange-007"}]},{"id":"topic-02","title":"リオデジャネイロオリンピックの視察","agenda":"リオデジャネイロオリンピックの視察","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"そのために視察に行くというふうに思っていますので、やはりちょっと弱いというか、文字といいますか、そこをもっと強くでなくてもいいけれども、書いていただきたかったという思いがあるのです。それは当たり前ですというふうに言う答弁ではなく、その辺のことをしっかり書いていないわけですから、口頭でいいので答弁していただきたいのですけれども、お願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"こちらの目的に、２０２０の品川区内の会場で３競技、今、予定されていることもあって、「今後の取り組みに向け」というところで、２０２０年には活かしたいという気持ちがこちらに入っているわけですが、伝え切れなかったと思います。","voiceIndex":18,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"わかりました。税金を使って行くわけですから、最大の効果をもたらしてもらいたいという思いで私も質問しておりますので、そのことは、行ってくださる方、心にとめて行っていただきたい、視察をしてきていただきたい。そして、さっきの各会派の要望でも書いてありますけれども、それをどう活用していくかというのが一番大事だと思いますので、その辺、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"それで、質問に先立って、皆さんもお聞き及びだと思うのですけれども、昨日、私どもの会派だけでなく、維新・無所属品川と、品川・生活者ネットワークの３会派で、議運委員長、それから、議会の議長宛てに、リオデジャネイロオリンピック視察調査への議員派遣の中止を求める申し入れというのを行ってきたところです。それについてどういうふうに考えておられるのか、ここも質問したいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"３点目の、ブラインドサッカーの開催準備状況ですが、リオでも、ホッケーの後にパラリンピックでブラインドサッカーをやる予定です。","voiceIndex":21,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう点で、契約は終わっているというふうに、私はこの資料をいただいたときに思っていたし、それが普通の受けとめ方ではないかと思っているのですけれども、先延ばしになるということは、こういう金額にも影響が出るのかと、そういう心配もあるので、なぜ契約がまだ整っていないのか、その辺を教えていただきたいと思います。それと、無料にした意味、そこも伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"続きまして、今までの区側の説明が不足だったのではないかですけれども、こちらの視察についてご紹介というか、こちらの区の思いを伝える場面がなかなかなく、お伝えすることが不十分だったかとは思いますけれども、まさに視察の予算を計上させていただいた時点で。","voiceIndex":25,"id":"exchange-011"},{"speaker":"南委員","kind":"提案","question":"この間のこういう詳しい説明がなかったことについては、機会がなかったというご説明だったのですけれども、４月６日に区長から議会のほうに議員２名をどうかというご提案があったときに、それ以降の議運で、私どもは説明をしてくださいと、そういうことを再三主張してきたのです。ですから、議会が、議運が悪いのですか。好き嫌いもあるかもしれない。これは意見として指摘をさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"私はもう一度そこのところは伺っておきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"１点目の、事前キャンプについて、区民の方にいつどのように説明するかですけれども、まだ事前キャンプについての見通しが立ってございません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"すみません。予想外のことが起きるかもしれないから、やはり実際に見ておきたいという、そこの気持ちはわからなくないと思います。しかし、これだけの、先ほどの繰り返しになるから簡単に言うけれども、９６万円という１人当たりの金額だけでも、通常価格に比べれば相当な金額だと思うのです。何かあったような気もしたのですけれども、また後で質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"それとも皆さん、これを持って飛び込みという形で行くのでしょうか、会える人のところにお訪ねしていって、やるものなのか。私、こういうことを具体的に知らなくてごめんなさい。教えていただきたいと思います。それから、私もヒアリングのない視察というのがどうしてもイメージができなくて、それは必須ではないかと思います。今、それの交渉もこのコーディネートのほうになるのですか。今、どの状況か。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"多言語対応のサイン類ですが、当然、各国の組織委員会が統一的なサイン類も考えているということではありますけれども、それとはまた別に、おそらく今まであったまちのサインですとか、それとはまた別の形のサイン類ということも当然考えられるわけですので、そういった意味では。","voiceIndex":34,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"割と日にちが迫ってきていると思うのですけれども、何か見通しといいますか、関係者はわかるのです。コーディネートという言葉を聞くと、わかったような気がしてしまうのですけれども、実際私たちがどこかへ視察に行ったりするときも、何を見たいからこういう人に話を聞きたいのだとかという希望を出しますよね。その辺、教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"まさに今、委員ご指摘のとおり、そういったコーディネートをお願いしているところでございまして、本日お示しいたしました資料の２枚目に、調査・活動内容の予定とありますけれども、こういったことを、今、専門の業者に私どもでお願いをいたしまして。","voiceIndex":36,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"迷惑」ということが実際の経験としてあるのです。一方で、やはり現地を知っていただきたいというのがあるから、それを考えると、本当に終了した後とかの方が、むしろ率直なところで、こういうふうにもくろんで、こういうふうに組み立てたけれどももっとこうすればよかったとか、これはすごくうまくいったとか、後のほうがいろいろなことが聞けるのではないか。裏側まで見てきていただかないと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回ようやく委託料のところが内訳が出たということで、私たちずっと共産党としては内訳を求めてきていましたので、ようやく出たと思っているのですが、まず聞きたいのは、最初は２,１００万円と言っていたと。そこを聞かせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、航空券とホテル代、チケット代で２００万円というふうに言われてきていたのが、９６万８,０００円になると。あまりにも大まかだったのか、ずさんだったのか、どうにでもなるお金というふうにちょっと聞こえるのです。先ほど南委員も言いましたけれども、丼勘定と言われても仕方がないのではないかというような感じがするのですけれども、そこら辺はどのようにお考えなのか伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"最初のご説明でもお話ししましたとおり、当初予算につきましては、昨年の秋口に見積もりをとったものです。まだ昨年の秋口につきましては、やはりオリンピック時にどうなるかということも見通しが立たないままに、確実に安全に行くための予算をまずは確保させていただいたです。","voiceIndex":44,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"ただの観光地であれば、来てほしいという思いもあるので、いろいろな金額のつけ方をすると思うのですけれども、オリンピックというのは４年に１回、その国でしかやられないものですから、オリンピック価格、取れるだけ取ろうではないですけれども、そこまで上げていけるものだと思うのです。改めて伺うのですけれども、関係者と会えない、誰とも会えないとなっても、視察はされるのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"相手への折衝につきましては、今まさにしているところでございまして、区は当然会えるということを見越して、行くものです。","voiceIndex":48,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどもお国柄ということで、１カ月先のことは確約できないと。そういうお国柄なのだと。何を見るのか。観戦以外の調査は、これから７月中旬に詳しいことが出るということですけれども、これで本当に会えなかったら、競技を観戦しに行くだけになってしまいます。そして、話を聞きたいという、それが視察ですから、ですけれども、それが成り立たなかったときどうするのかというのを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"だけど、会えなかったらどうするのかということを今聞いたので、そこも改めてまたお願いしたいと思います。それで、その条例で、特別な事情により、または当該旅行の性質上困難である場合には、人事委員会と協議して定める旅費を支給することができるというふうに書いてあるのですけれども、今回、大分これを上回っている旅費になるのですが、人事委員会との協議はされたのかどうか伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今回の旅費につきましては、全面委託で委託料ですけれども、区として必要な経費だということで判断をして執行するものです。","voiceIndex":54,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"この条例よりももっと特例だということなのでしょうか。条例上はこういうふうにされているので、当然、人事委員会等が開かれて協議をされて、こうした旅費を支給するということが決まったのだろうと私は思うのですけれども、では、今回の決定は何なのかを伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘の旅費の規定につきましては、旅費という科目についての考え方でございまして、今回の視察にかかわる経費につきましては、その旅費の規定には当たらない、委託料です。","voiceIndex":56,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これだけ高額なお金をかけて行くというところでは、私たちもこういった詳細の経過がないから、余計何なのだろうというふうに思うわけです。ですので、やはりリオに行くのがこれだけ高額になるこの時期に、区民の税金を使って、しかも会えるかどうかもわからないのに行って、だけども、こっちで十分できることはまだまだたくさんあるのに……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"アクセス状況を見るとおっしゃっていましたけれども、私はこれだけの予算をかけるのでしたら、区内でバリアフリーを見る、障害者の皆さんを連れて参加していただいて、ここからここまでどうですか、ここからここはどうですかというふうに、やはり地元で現地でしっかり声を聞いていく、ここにこそこの予算をかけるべきだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど来、さまざまなご意見を伺いました。一般質問においても、この派遣についてはさまざまな主張がありましたけれども、今日は１つだけ確認をさせていただきたいと思います。そもそもオリンピックというのはそういうものなのですか。そういう位置づけなのかどうか。今までオリンピックを各国でやってきて、そのような仕組みになっているのかどうか、その辺についてお伺いしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"さまざまな面で大きな契機になるというふうに区は主体的に２０２０を捉えて、２０２０を契機にさまざま区が発展することを目指して、これまでもいろいろなことを取り組んでまいりました。それは他区に先駆けて、２年前からいろいろなことをやってきました。","voiceIndex":63,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そうなった瞬間に、オリンピックというのは他人のものになってしまうし、今、オリンピック、五輪教育というものを学校でやっていますし、これは子どもたちが主体者の一人になってほしいということでやっているわけでありますし、主催者と主体者というところをあえて混同するということはやめてほしいというふうに思いますし、そこのところは峻別をしていただきたい。このように考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"提案","question":"幾つか指摘といいましょうか、しますけれども、私が記憶する限りでは、昔は議会は全会派の区議会議員が海外に行っていたはずです。つまり、共産党の議員も参加していました。それから、よく実績なり成果なりとおっしゃるけれども、例えば、平成１１年度の品川区議会海外調査団の報告の提案が、介護保険の事業者評価であり、それから、第三者評価であり、苦情調査委員会に具体的に展開されているわけです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ご指摘のとおり、私たちは物見遊山で行くわけではございません。きちんと視察をいたしまして、帰ってきてからもきちんとした報告書にまとめ、まずは議会に報告をさせていただき、区民の皆様にも、目に見える形で活かしていきたいと考えております。","voiceIndex":66,"id":"exchange-028"},{"speaker":"伊藤委員","kind":"意見","question":"どうしても批判される方々は、そういう批判だけで終わってしまうのです。終わった後、こういうふうに私たちが報告書をつくって実績を出したということは一切書かれていない。むしろこちらのほうが大切です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"はどうなのでしょうか。教えていただきたいと思います。先ほどちょっと申し上げたのですけれども、公の自治体としての公正性という点で齟齬はないのかというのを非常に心配するので、そこについてさっき伺い損なってしまったので、教えていただきたいと思います。そういうやり方でいいのだということでやって、区民の理解を得られるのでしょうか。そう考えているのですか。そのことも聞きたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２点目につきまして、旅費でなければ高額な支出でいいのかということを区が言っているわけでは一切ございません。先ほどのご質問で、人事委員会への確認が必要だということについては、そこについては今回は当たりませんというご説明をさせていただいたものです。","voiceIndex":69,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"ですから、やはりそういう点で、この３つのホテルについて宣伝を公費でしていることになってしまうのではないかと思うので、それで聞いたのです。その辺を伺いたいと思います。書いてありますか。では、そこは後で教えてください。委託料の関係なのですけれども、さっきの質問との関係でそういう答弁をしたということですけれども、現実的には、規定があって、そこを超えた金額になるわけです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういったことの中で、３つ、あえて挙げさせていただいているです。続きまして、２点目、区といたしましては、委託料になればどんな多額の支出でもいいと考えているわけではございません。今回はあくまでも、オリンピックという時期でもあります。","voiceIndex":71,"id":"exchange-031"},{"speaker":"松永委員","kind":"質問","question":"東京オリンピック・パラリンピックに向けて特別委員会を設置して、議論を重ねておりました。そこで伺いますが、今回のリオ視察は、行政サイドからも要請をいただき、議決を経て議員派遣をしますが、区として議員派遣についてどのようなお考えを持っているのか、また、その意義とはどう考えているのか伺います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"特にご指摘のとおり、品川区議会におきましては、２年前から早々と特別委員会というものを設置し、さまざま議論し、特に一昨年につきましては、東京都に要望書まで出しているというような実績も上げているところです。","voiceIndex":73,"id":"exchange-032"},{"speaker":"松永委員","kind":"質問","question":"最後にまとめさせていただきまして、総合的な安全対策について伺いたいと思います。東京大会の安全・安心を考えて、リオ大会でどのような安全対策が講じられているのかを見る必要があると考えております。それは競技開催地区周辺以外の区民の生活圏です。安全・安心対策、要するに、治安の維持であると考えますが、その点についてお伺いしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"まさに本番のオリンピックをやっているときに、区民に当たるリオの市民の方たちの日常生活がどういうふうに関係してくるかということは、今後の２０２０にも十分参考になることですので、そういった視点でも、先ほど冒頭にも申し上げましたが、セキュリティーという部分も十分。","voiceIndex":75,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"聞きそびれてしまったので、すみません、最後に１点だけ。私は、その前の質問のときに、そういうこれだけの金額をかけて行くことに区民の理解は得られるかと聞いたのですけれども、そこについての答弁がなかったし、適正と認めて委託というふうな形をつくって、契約して支出をして行くということですけれども、そうであるならば、改めてもう一度、答弁がなかったのもあって伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"当然、結果報告につきましても、２０２０の大会に活かせるように、万全の報告を、成果を活かせるようにしてまいります。そういった意味で、最後には区民の方全員に理解を得られるように努力してまいります。","voiceIndex":78,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":39428,"voices":84}},{"id":"h28-20160706-10","meetingId":"h28-cm07","date":"2016年7月6日","dateIso":"2016-07-06","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議員派遣の件","agenda":"議員派遣の件","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"一言だけ意見を述べさせていただきたいと思います。本会議の議決を経て議員を海外に派遣するわけですから、今回のジュネーヴも、あわせてリオ五輪もですけれども、きちんと報告書を作成して、議長への報告と本会議での報告、発言を行って、同僚議員や区執行部、そして区民への派遣についての報告、説明は積極的に行うべきだと思いますので、意見だけ述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-001"}]},{"id":"topic-02","title":"リオデジャネイロオリンピックの視察","agenda":"リオデジャネイロオリンピックの視察","exchanges":[{"speaker":"沢田委員","kind":"確認","question":"品川区は２０２０年東京オリンピック・パラリンピック競技大会において、品川区内の会場でホッケー、ビーチバレーボール、ブラインドサッカー、３競技の開催が予定されていることから、今後の取組みにおいて、本番まで最後の夏季オリンピックである２０１６リオオリンピック競技大会期間中の会場を訪問し、地元自治体がどのようにかかわっているかを現地において確認することが重要であると考え。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"そのような考えでこのオリンピックに取り組めば、これは成功しないということですから、こうした会派の方がオリンピックを成功させたいとか、賛成である、応援したいと言っていることとかなり矛盾があるのではないかと考えております。これは区の責任としても行うべきだと。議会の責任としても行うべきであるということから、５月２６日の議会において議決に賛成をした次第です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"議員が行くのはよろしくないけれどもということなのでしょうか。それともこれは、議員も職員も派遣すべきではないという考え方なのか。議員派遣の中止をということで書かれると、どちらを指していらっしゃるのかがちょっとこの文章からわからなかったところですから、職員はいいけれども議員の２人だけが望ましくないというご意見なのか、ちょっとそこをお伺いしたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"なので、ちょっとその点の議論がないので、そこもお伺いしたいなと思うのと、先ほどちょっと質問をいただきましたけれども、今回は議会であるので議員派遣の中止を求める申し入れとしましたが、本日、この会議の後に区長に対しても、リオデジャネイロオリンピックの視察・調査への職員・議員派遣の中止を求める申し入れというものを行う予定であります。両方に対してです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"大多数の都民が都民の声によって主体である、その中の都議会が議員派遣、都議会として議員派遣を中止したということは、やはりこれは都民である以上、区民もいらっしゃるわけですから、私はそこは重く受けとめるべきではないかなと。でも２３区中ほとんど行っていないわけです。皆さんそういうことも私は考えるべきではないかなと思いますので、今回の派遣に対しては私は中止をしたいと申し入れます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-006"}]},{"id":"topic-03","title":"議長会等の報告","agenda":"議長会等の報告","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"先ほど申し上げた私の趣旨からすれば、もちろん区民に開かれた議会ということでの、発露ということまでは、もちろんこれはいたし方ない部分はあると思うのですが、議事の進行を妨害するようなこと、これは私たちに審議を負託されている区民の方にとっても望ましくないことだと思いますので、この点、事務局、もしくは議長のほうにお伺いをしたいのですが、何か会議規則において定まっているのか。","respondent":"原区議会事務局長","answer":"法的な根拠のほうから、ちょっと私のほうでご説明させていただきたいと思います。地方自治法の中で、この関係については定められてあります。１つは、会議の傍聴というところと議場の秩序維持という、これがそれぞれあります。","voiceIndex":60,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"制約というか、かなり厳しい規定になっていると。規則ではそこまでは明文化はしていないようですけれども。やはり議長におかれましては、多分さまざまなご苦労をされて今も運営をされているとは思うのですけれども、さらに毅然とした態度で議会の秩序を守っていただきたいと考えています。もしご意見がいただけるようであれば、ご意見伺いたいと思います。","respondent":"大沢議長","answer":"しかしながら、傍聴規則ゆえに、そこを押すことによってまた混乱を招かないようなこの規則の運用をしていきたいと思いますので、委員のご指摘しっかりと受けとめて、臆することなく毅然と議場の秩序維持に努めてまいりたいと思います。","voiceIndex":62,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"今の件なのですが、確かに今回傍聴席でいろいろ発言、強い発言もありました。ですが、その前に我々議員も皆さんの模範となるべく、やはり野次等慎んで、皆さんにその範を見せるべきではないですか。それがあってこそ、それをやってこそ、やはり区民の傍聴者に対して毅然とした態度で臨むという姿勢が、私はまず先だと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"運用については今議長がおっしゃったことで行っていくということが大事だと思いますけれども、ただ、今、須貝委員の意見もありましたが、拍手についても我々も頑張れよと拍手ある分には会議を妨害しているには直接は、一定程度の範囲であれば、それが直接当たるとなってしまってはどうかなという思いもありますし、拍手だったり、思わず出る野次も一定の範囲で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"そういった部分についてまで規制しようと考えている方は、多分この中には１人もいらっしゃらないのではないかと。ただおっしゃったように、今のやり方だとその場で議長がというやり方だけに頼ろうとすると、逆にその場がかえって荒れてしまうという恐れも確かにあるということで、例えば傍聴手続の際に一定確認していただく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"意見","question":"やはり一番傍聴の人がわかりづらいのは拍手はだめというのが、ちょっと理解できないのがあるので、そういうこともきちんと呼ぶ側がお願いして、やはりそれが大事だと思うので、全く誰にも呼ばれないで来る方もいるかもしれませんけれども、そういう方でよく呼ぶ方がいるのだったら、ぜひそこは議員もしっかり傍聴の方にもお願いして、徹底してもらうというのが大事だと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5190#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":20103,"voices":69}},{"id":"h28-20160714-8","meetingId":"h28-cm07","date":"2016年7月14日","dateIso":"2016-07-14","committee":"建設委員会","time":"午前１０時００分～午後 ４時０３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4176#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":1347,"voices":8}},{"id":"h28-20160726-6","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"区民委員会","time":"午後 １時００分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"すみません、わかればでいいのですけれども、今までこのメニューでいろいろ中小企業支援をやられてきたと思うのですけれども、実際品川区の景気というのでしょうか浮揚効果というのでしょうか、何でそれを測ればいいかというのはわからないと思うのですけれども、そういったデータというのは必要だと……。わかるところだけでいいです。","respondent":"山崎商業・ものづくり課長","answer":"そういうこともしっかりこれからは捉えて、産業施策というのはやはり考えていく必要があるだろうということで、重要性は認識しておりまして、いろいろな形で経済なり産業への波及効果というのですか、そこはしっかり指標などを使って見ていく必要があるかなと思ってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問・要望","question":"その何兆円の中にいわゆる中小企業の経済効果と言いますか、そういうのも含まれているのかということがもう一つと、私は含んでもらいたいという思いもあって、東京に２０２０年来るわけですから、その辺を絡ませていただきたいという思いがあって、その辺はいかがなのですかということと、それと一番上のところで、大手企業とのビジネスマッチング事業ということで、直接ではないかもしれないのですけれども。","respondent":"立木産業活性化担当課長、山崎商業・ものづくり課長、小川オリンピック・パラリンピック準備課長","answer":"平成２７年度からは国の緊急雇用の補助金が区としては終わりましたので、別に東京都の人材育成の関係の補助金を使いまして。それからもう一つ、ソフトのほうでは外国人をお招きするためにいろいろなおもてなしの関係で整備をされて多国籍の対応をしたりとか。今後、エンブレムにかかわらずオリンピックを盛り上げるためにいろいろなツールのことについてはこちらも考えておりまして。","voiceIndex":8,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"そしてそれがどういう内容のものなのか、第４次実施計画も始まりましたので、そこを伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"実施計画第３次、第４次の比較ですけれども、そもそもこの実施計画というのは、その上には長期計画があって、そこで示されたものをそれぞれ中期の３年間で具体化していくというのが実施計画になっております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"今、第３次から第４次、もちろんその上に長期基本計画、構想というのがそれぞれあるわけですけれども、第３次と第４次ではそれぞれ充実したということで、産業振興にかかわる大きな方向性としては継続という言い方をすればいいのか、同じ方向を向いているということなのか、ちょっとその辺を伺いたいと思ったのです。第４次実施計画の中での充実点、強化点という視点で１点伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味で、長期計画なり実施計画で掲げた基本的な考え方は変わっておりませんが、昨今ではベーシックなほうの支援としましては、やはり事業承継の支援などをしっかりやって、ここのところを区が事業化したということで。","voiceIndex":14,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"どういう品川の産業構造を目指していくのかと伺って、端的に伺うと二極化しているけれども、バランスをよく見ていきたいというお答えだったのかなと思います。本当に地方のところで大きい企業を誘致してそれがトップが撤退してしまってというのとちょっと似ているところと違うところも、また東京都市ならではであるのかなと問題意識もあるのですけれども、そこについてお考えを伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"ですから、そうした小規模の事業者の高い技術力を、以前は上の親会社のためだけに使っていたところを、広くやはり品川の小規模のものづくり企業の技術力をＰＲしたり、いろいろなご商売の相手を広げたりというようなことが、先ほど説明させていただいた販路拡大。","voiceIndex":16,"id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"ただ、そうした技術がないと日本全体のこのものづくり、工場一つが動かないという。なので、週末は急いでやったりするのですけれども。現状とともに、そういう新たな支援策というのは、私も議論を深めながら提案できるようにしたいとは思うのですけれども、とりあえず現状と新たな支援策をどう考えていらっしゃるのか、伺いたいと思います。","respondent":"立木産業活性化担当課長","answer":"例えば、大田区がやっているようなボブスレーとかリュージュとかですね、そういったようなものとか、あとは区内の高い技術を持っている企業たちをネットワーク化するというような形ですね、そういったようなことも今後しっかりと研究してまいりたいと考えています。","voiceIndex":18,"id":"exchange-006"},{"speaker":"中塚委員","kind":"提案","question":"なかなか業種ごとにいろいろ複雑にそれぞれ仕事が絡み合っていますので、ぜひつかんでいただきたいと思うのです。最後に、もう一点だけなのですけれども、私も具体的にこれを提案とまだそこまで行っていないので、今後深めていきたいなと思いますが。そういう仕組みにつながってくると思うのですけれども、現状の取組みと今後の方向を具体的に伺えたらと思います。","respondent":"立木産業活性化担当課長","answer":"就業関係に関しましては、労基署等と連携しましてセミナー等も行っておりますので、そういったいろいろなものを組み合わせてワークライフバランスがしっかりできるような区内の就業、それから企業と連携をとりながら連携したいと考えております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"人材確保のところです。就業体験支援ですとか就業支援セミナーとか、それぞれ取組みがあるのですけれども、産学官のところで、実際にこの品川区内中小企業と就労とかが結びつき、実のところどう把握されているのか伺いたいと思います。","respondent":"立木産業活性化担当課長","answer":"区内の大学と区でも包括連携の協定をとってありますので、そういったところで学生の区内企業への就職等で何か事業ができないかどうかというところを継続してまいりたいと思ってます。","voiceIndex":22,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"一点だけ質問します。その辺の基本をもとにうまく使える企業と使えない企業があるのではないかという指摘を頂いたのですけれども。基本は、その方は経営だから資金管理という意識が常に原点にないとダメなのではないかと言っていたのですが、その辺のところを具体的に、経営意識ですか、その部分というのをやはりこの支援事業にはどんなふうにウエートを占めるのか、その辺を教えてください。","respondent":"山崎商業・ものづくり課長","answer":"そういうふうに今直面する事業承継の課題を抱えているところには直接的な支援をし、まだまだ自分は若いし頑張れるよという企業もたくさんおりますけれども、そういう企業にはしっかり備えていただく必要性があるのですよという、周知啓発というのですか。","voiceIndex":24,"id":"exchange-009"},{"speaker":"伊藤副委員長","kind":"質問","question":"１点だけ。これだけいろいろ支援をやっていらっしゃることはわかるのですけれども、いろいろなところから今話を聞く機会があって、やはり伺ってきた話は、要は全体像がわからない、企業経営者の方々に。","respondent":"山崎商業・ものづくり課長","answer":"ちょっと工夫してわかりやすく整理をしつつ、あと、産業振興の大事なところは、国の支援はこういうものがある、あるいは東京都もこういうものがあるよ、公社はこうだよというふうにいろいろな登場人物が来て、さまざま受け持ちがありますので、それも含めてしっかりＰＲできる。","voiceIndex":26,"id":"exchange-010"},{"speaker":"伊藤副委員長","kind":"質問","question":"まとめますけれども、企業経営というのは例えば国がやっても東京都でも品川区でも変わらないと思うのです、相当あると思うのですよ。企業経営者の思いとして変わるならば。先ほどいろいろな長い長い討論があって、話があったけれども、それは品川区がどのような指導をしても変わらないですよ、企業。だから、あのイメージで企業支援の特集を組んでもいいではないですか。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2758#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":18237,"voices":34}},{"id":"h28-20160726-7","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、報告事項の(1) 臨時福祉給付金の実施","agenda":"の１、報告事項の(1) 臨時福祉給付金の実施","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１番目の高齢者向けの臨時福祉給付金なのですけれども、申請率が９１.８％ということで、この発送数から受け付け数を引くと、２,１４０人が受給資格がありながら受けられなかったと思うのですが、この申請されなかった方の理由を把握されていたら教えていただきたい。制度の基本的なところで、高齢者向けの３万円の申請をされた方も、この３,０００円の対象の中には入るのかについても教えてください。","respondent":"大串福祉計画課長","answer":"これは３年目になりますので、これまでもご申請いただいている方については、口座を印字したものでお送りしますので、その口座で変更がなければ、そのまま、返送していただいて、その指定された口座に振り込みをするという流れになっているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、こういう措置というのは決まっていないのではないかと思うのですけれども、来年の４月から、この制度が実施されない場合は、さらにまた、３,０００円という形で出てくるという方向なのか、そこら辺のところがわかったら教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"委員ご指摘のように、平成２９年４月から軽減税率の制度が開始される予定であることを踏まえというのが前提になっております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そもそも６,０００円というものが実際よりも少ないと思うのですけれども、この理由からしても、消費税が所得の少ない人ほど負担が高い、逆進性の税金だという矛盾を認めたからこそ、つくられた制度だと思います。これから１０％が延期ということになりましたけれども、改めて、延期ではなく中止すべきですし、８％も元に戻すべきということを主張させていただいて、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"確認","question":"確認ですけれども、１番の申請書発送数と支給数の差が大体２,０００人ぐらいあるということで、その方たちは、今回、２番の2)の支給対象者の３,４００人の中には含まれるということでよろしいのか。","respondent":"大串福祉計画課長","answer":"先ほど申し上げましたように、１番の高齢者向け、６５歳以上という区切りでやっているところ、なおかつ、また前年度の所得に対しての課税、非課税ということでやっておりますので、２番の制度の概要の1)の臨時福祉給付金は、今年度が対象になってまいりますので。","voiceIndex":11,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"その３,０００円のほうではなくて、2)の３万円のほうです。これは１番の３万円と同じ考えなのだけれども、１番でいただいた方は、もうだめということなのか。１番で、行方不明だとか亡くなった方は別なのでしょうけれども、理由はわからないですが、申請が漏れている方については、また2)の３万円は案内を出す、もしくは対象になっているという考えでいいのでしょうか。","respondent":"大串福祉計画課長","answer":"ただし、春の高齢者向け、６５歳以上で非課税ということで３万円を受給されている方は、障害・遺族基礎年金をもらっていた方であっても除かれるような構造になっているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"この条件が当てはまればということが前提なのですけれども、当てはまったとして、1)で対象になる可能性のある方と実際に申請した方の差が２,０００人ぐらい出ている。２番の2)では、今度は支給対象者が約３,４００人ということで、単純に見ると１,４００人ぐらい増える。その増えた１,４００人ぐらいは、見通しとしては、新たにその対象に加わる方がそれくらいいるという考え方でいいのでしょうか。","respondent":"大串福祉計画課長","answer":"そうした中で、突合はなかなか難しいところでございまして、今のところ、５月に支給された人数ということで、３,４００人という数字を出しています。３,４００人と２,０００人、その差の１,４００人という関係性が成り立つかどうかというのは難しいと思います。","voiceIndex":15,"id":"exchange-006"}]},{"id":"topic-02","title":"品川区行方不明高齢者早期発見の仕組み","agenda":"品川区行方不明高齢者早期発見の仕組み","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何点かお聞かせください。何枚かセットになっているのかをお聞かせいただきたいと思います。それから、２の早期発見のための品川くるみ見守りネットワーク構築というところなのですけれども、行方不明時の情報提供を担当するところは、コールセンターみたいな形でどこかに委託をするのか、それとも、区の高齢福祉課でやるのか、どうなのかもお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"認知症の疑いを含むということで、ご家族が心配であれば、申請をしていただければ、交付をいたします。アイロンシールにつきましては、今、枚数を具体的に検討中ですけれども、複数枚、用意をしております。ご希望があれば、さらにプラスしてもいいと考えております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区では既に、この制度でＧＰＳのものをやっていますね。私は、このＧＰＳのことについても、こういう仕組みがあるので、ぜひご利用くださいという周知をしていただきたいと思うのですけれども、その周知については、どう考えられているのか。この自己負担の毎月かかる料金についても、もうちょっと助成制度があるといいと思うのですけれども、その点についてはいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ＧＰＳの周知につきましては、ＧＰＳについては利用料金がかかりますので、きちんと在宅介護支援センターでご相談に乗っていただきながら、使い方の説明だとか、あと身につけ方とか、そういう具体的な方法のご説明を受けてからやったほうがいいと考えております。","voiceIndex":25,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、この冊子というのはその１つだと思うのですけれども、認知症というところで見たときに、本当に少ない情報しかないという状況なので、ＧＰＳというものも含めて、詳しくはどこというところでもいいのかもしれないのですけれども、そういう制度があるというお知らせはぜひしていただきたいということで、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"１つ目が見守りアイテムの３点セットで、キーホルダーをつけられるようにするということですが、内容を見ると、大田区で実施しているのと全く同じと思います。今回、しなメールの配信ですけれども、しなメールを受信される方がチェックをしないと受け取れないような状況なのか、それとも、何らかの形で、全員にお知らせできるようにするのか、そこら辺の基本的な考え方を教えてください。","respondent":"永尾高齢者福祉課長","answer":"現在のところ、しなメールにつきましては、今、協議中ですけれども、一番最初の画面にいきなり出すというのは難しい状況だと聞いております。やはり選択をして、チェックをしていただくことが必要だと聞いているところです。","voiceIndex":28,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"多分そうかと思いながら質問させていただきました。様々周知するなどして、チェックをしていただける方が増えるように、どういう努力をしたらいいのかはぴんとこないですけれども、いろいろな場面で広報を使うとか、そういうような形で推進をしていただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"２番の(1)の行方不明時の情報提供のところなのですが、まず、捜索依頼に基づきとありますけれども、この捜索依頼は家族からのということでいいのかというのが１つ。それから、(2)も含みますけれども、情報提供先です。ここにはどのような情報を流すのか。個人の名前とか住所とか、個人情報をどの辺まで流すのかというのを教えてください。","respondent":"永尾高齢者福祉課長","answer":"この情報提供につきましては、申請のときにきちんと同意書をご家族の方にとってからやる方式をとろうと考えています。","voiceIndex":31,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。その場合に、これに登録している方は、そういえば区にも登録しているから、区にも連絡しようとなれば一番いいのですけれども、どうしても、そこをうっかり忘れていて、警察にだけ、おじいちゃんがいなくなってしまった、探してくださいといったときに、警察から区に連携されるような仕組みというのはあるのかどうか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"警察に捜索依頼を出した場合ですけれども、この制度についても、今、警察に具体的な登録の方法等も周知しています。その中で、区の名簿を警察の中での管理ということで、欲しいという声も出ているところですので、その辺は、これからもう少し調整をしていきたいと考えています。","voiceIndex":33,"id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問・要望","question":"例えば警察に行った場合に、品川区の場合はこういうものをやっているので、そこにも登録されていませんかとか警察の方が言っていただけるような、もっと言えば、警察から区に問い合わせたときに、そこで連携がうまくいくようなものをぜひ構築していただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"安藤副委員長","kind":"確認","question":"１点、確認です。そして、情報提供先ですけれども、今現在、しなメール登録者は何人ぐらいなのかということです。そういった意味からも、鉄道事業者なども含まれるのかということをお伺いします。資料のところの配付対象者というところなのですが、2)の外出に不安のある６５歳以上の方というのは、ちょっとイメージがつかないのですが、どういった方なのか、お伺いします。","respondent":"永尾高齢者福祉課長","answer":"在宅介護支援センターの営業時間外の件です。こちらについては、警察で対応ということで、今、調整をしています。","voiceIndex":36,"id":"exchange-015"}]},{"id":"topic-03","title":"の３、行政視察","agenda":"の３、行政視察","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第１回目から、この７自治体で始まって、これからも７自治体でいくのか、それとも、岡山市が呼びかけて、自主的にほかの自治体が参加したということなのか、その辺の経過も教えていただきたいと思います。国のこういう介護度を改善させていくモデル事業とか、そういう国の方針とのかかわりというのがどうなのかについてお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"この質の評価のモデル事業ということですけれども、厚生労働省としては、モデル事業ということは考えていないとは思いますけれども、今、介護報酬を検討している状況の中で、こういう質の評価についても、項目として入っておりますので、国とともに。","voiceIndex":48,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"介護サービス質の評価先行自治体ということなのですけれども、品川区としては、要介護度を改善させていこうということで、改善をした場合、介護報酬が下がってしまう分を区が補填をして、頑張って、介護度が下がったとしても報酬が下がらないので安心して取り組んでくださいという仕組みでやっていると思うのですけども、介護サービス質の評価先行自治体というのは。","respondent":"永尾高齢者福祉課長","answer":"品川区は施設に限定しておりますので、各自治体それぞれ取り組みがばらばらになっています。ただ、目的が一緒ですので、そういう例を紹介しながら、どの方法が全国で一律にやる場合にいいかということの検討を国にやってほしいという提言をしようと考えています。","voiceIndex":50,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3452#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":19340,"voices":53}}]);
